var e=JSON.parse(`[{"wordId":20910,"answer":"one of the best","form":"원형","example":"Sunday morning is one of the best times to visit the museum.","exampleTranslation":"일요일 아침은 박물관에 가기 가장 좋은 때 중 하나다.","sense":"최고 중 하나"},{"wordId":20912,"answer":"which one is better","form":"원형","example":"Which one is better for the beach, the red hat or the blue hat?","exampleTranslation":"해변에는 빨간 모자랑 파란 모자 중 어느 게 더 나아?","sense":"어느 게 나아"},{"wordId":20913,"answer":"could you say that again","form":"원형","example":"I missed your phone number, so could you say that again?","exampleTranslation":"전화번호를 놓쳤는데 다시 말씀해 주시겠어요?","sense":"다시 말해 주세요"},{"wordId":20914,"answer":"could you speak up","form":"원형","example":"The music is very loud, so could you speak up a bit?","exampleTranslation":"음악이 너무 시끄러우니 좀 더 크게 말해 주실래요?","sense":"크게 말해 주세요"},{"wordId":20915,"answer":"what does that mean","form":"원형","example":"My doctor said my results were normal, but what does that mean exactly?","exampleTranslation":"의사가 내 검사 결과가 정상이라고 했는데, 그게 정확히 무슨 뜻이야?","sense":"무슨 뜻이야"},{"wordId":20916,"answer":"how do you spell","form":"원형","example":"How do you spell the name of the street you live on?","exampleTranslation":"네가 사는 거리 이름 철자가 어떻게 돼?","sense":"철자가 어때"},{"wordId":20917,"answer":"how do you say","form":"원형","example":"How do you say good morning in Japanese?","exampleTranslation":"일본어로 좋은 아침이라는 말을 어떻게 해?","sense":"어떻게 말해"},{"wordId":20918,"answer":"do you mean that","form":"원형","example":"Do you mean that the train is not stopping at our station today?","exampleTranslation":"오늘 기차가 우리 역에 서지 않는다는 뜻이야?","sense":"라는 뜻이야"},{"wordId":20919,"answer":"are you sure that","form":"원형","example":"Are you sure that you turned off the stove before we left?","exampleTranslation":"우리 나오기 전에 가스레인지 끈 거 확실해?","sense":"확실해"},{"wordId":20922,"answer":"what exactly is","form":"원형","example":"What exactly is included in the price of this tour?","exampleTranslation":"이 투어 가격에 정확히 뭐가 포함돼 있나요?","sense":"정확히 뭐야"},{"wordId":20923,"answer":"in that case","form":"원형","example":"In that case, we can take a taxi to the concert instead.","exampleTranslation":"그렇다면 대신 콘서트장까지 택시를 타면 돼.","sense":"그렇다면"},{"wordId":20926,"answer":"there seems to be","form":"원형","example":"There seems to be a problem with the internet in my room.","exampleTranslation":"제 방 인터넷에 문제가 있는 것 같아요.","sense":"있는 것 같다"},{"wordId":20928,"answer":"this is not what","form":"원형","example":"This is not what the photo on the website looked like.","exampleTranslation":"이건 웹사이트 사진에서 본 모습이 아니에요.","sense":"이건 아니에요"},{"wordId":20930,"answer":"I was told that","form":"원형","example":"I was told that breakfast is served until ten in this hotel.","exampleTranslation":"이 호텔 조식은 열 시까지 제공된다고 들었어요.","sense":"라고 들었어요"},{"wordId":20936,"answer":"would it help if","form":"원형","example":"Would it help if I watched the kids while you cook dinner?","exampleTranslation":"네가 저녁 하는 동안 내가 아이들을 봐 주면 도움이 될까?","sense":"도움이 될까"},{"wordId":20937,"answer":"what can I do","form":"원형","example":"What can I do to make you feel better after such a long day?","exampleTranslation":"힘든 하루를 보낸 너를 기분 좋게 하려면 내가 뭘 하면 될까?","sense":"뭘 하면 될까"},{"wordId":20939,"answer":"leave it to me","form":"원형","example":"If you need someone to plan the trip, leave it to me.","exampleTranslation":"여행 계획 짤 사람이 필요하면 나한테 맡겨.","sense":"나한테 맡겨"},{"wordId":20941,"answer":"never mind","form":"원형","example":"Never mind about the dishes, I will wash them in the morning.","exampleTranslation":"설거지는 신경 쓰지 마, 아침에 내가 할게.","sense":"신경 쓰지 마"},{"wordId":20942,"answer":"no problem at all","form":"원형","example":"Changing your seat is no problem at all, sir.","exampleTranslation":"좌석을 바꾸시는 건 전혀 문제없어요, 손님.","sense":"전혀 문제없다"},{"wordId":20944,"answer":"thanks for","form":"원형","example":"Thanks for watering my plants while I was on vacation.","exampleTranslation":"휴가 간 동안 화분에 물 줘서 고마워.","sense":"해 줘서 고마워"},{"wordId":20945,"answer":"I really appreciate","form":"원형","example":"I really appreciate the flowers you sent when I was sick.","exampleTranslation":"아팠을 때 보내 준 꽃 정말 고마워요.","sense":"정말 감사해요"},{"wordId":20949,"answer":"I owe you one","form":"원형","example":"You helped me move all those boxes, so I owe you one.","exampleTranslation":"그 상자들을 다 옮기는 걸 도와줬으니 신세 졌어.","sense":"신세 졌어"},{"wordId":20951,"answer":"what happened to","form":"원형","example":"What happened to the bakery that used to be on this corner?","exampleTranslation":"이 모퉁이에 있던 빵집은 어떻게 된 거야?","sense":"무슨 일 있었어"},{"wordId":20953,"answer":"how was your","form":"원형","example":"How was your first day at the new school?","exampleTranslation":"새 학교에서 첫날은 어땠어?","sense":"어땠어"},{"wordId":20954,"answer":"how did it go","form":"원형","example":"You had a job interview yesterday, so how did it go?","exampleTranslation":"어제 면접 봤잖아, 어떻게 됐어?","sense":"어떻게 됐어"},{"wordId":20955,"answer":"what kind of","form":"원형","example":"What kind of dog would be best for a small apartment?","exampleTranslation":"작은 아파트에는 어떤 종류의 개가 제일 좋을까?","sense":"어떤 종류의"},{"wordId":20956,"answer":"what are you going to","form":"원형","example":"What are you going to cook for the family dinner on Sunday?","exampleTranslation":"일요일 가족 저녁 식사로 뭘 요리할 거야?","sense":"뭐 할 거야"},{"wordId":20957,"answer":"are you ready to","form":"원형","example":"Are you ready to leave, or do you need five more minutes?","exampleTranslation":"출발할 준비 됐어, 아니면 오 분 더 필요해?","sense":"할 준비 됐어"},{"wordId":20958,"answer":"would you like some","form":"원형","example":"Would you like some cake with your tea this afternoon?","exampleTranslation":"오늘 오후에 차랑 같이 케이크 좀 드실래요?","sense":"좀 드실래요"},{"wordId":20959,"answer":"what would you like","form":"원형","example":"What would you like to do on your day off tomorrow?","exampleTranslation":"내일 쉬는 날에 뭘 하고 싶어?","sense":"뭘 원하세요"},{"wordId":20960,"answer":"if I had","form":"원형","example":"If I had a bigger kitchen, I would cook for my friends more often.","exampleTranslation":"부엌이 더 크다면 친구들에게 요리를 더 자주 해 줄 텐데.","sense":"만약 있다면"},{"wordId":20961,"answer":"I wish I could","form":"원형","example":"I wish I could speak French as well as my sister does.","exampleTranslation":"언니처럼 프랑스어를 잘할 수 있으면 좋을 텐데.","sense":"하면 좋을 텐데"},{"wordId":20962,"answer":"it would be great if","form":"원형","example":"It would be great if the store delivered on weekends too.","exampleTranslation":"그 가게가 주말에도 배달해 주면 정말 좋겠어.","sense":"하면 좋겠어"},{"wordId":20963,"answer":"what would you do if","form":"원형","example":"What would you do if your flight was canceled at the last minute?","exampleTranslation":"비행기가 막판에 취소되면 어떻게 할 거야?","sense":"어떻게 할 거야"},{"wordId":20964,"answer":"in case","form":"원형","example":"I keep some cash in my wallet in case the card machine breaks.","exampleTranslation":"카드 단말기가 고장 날 경우에 대비해 지갑에 현금을 좀 넣어 둔다.","sense":"경우에 대비해"},{"wordId":20965,"answer":"just in case","form":"원형","example":"Write down your hotel address just in case your phone dies.","exampleTranslation":"휴대폰 배터리가 나갈 수도 있으니 혹시 모르니까 호텔 주소를 적어 둬.","sense":"혹시 모르니까"},{"wordId":20966,"answer":"unless you","form":"원형","example":"The cookies will burn unless you take them out in ten minutes.","exampleTranslation":"십 분 안에 꺼내지 않으면 쿠키가 탈 거야.","sense":"하지 않는다면"},{"wordId":20967,"answer":"even if","form":"원형","example":"I will finish this report tonight even if it takes until midnight.","exampleTranslation":"자정까지 걸리더라도 오늘 밤에 이 보고서를 끝낼 거야.","sense":"하더라도"},{"wordId":20968,"answer":"even though","form":"원형","example":"Even though the restaurant was small, the food was amazing.","exampleTranslation":"식당은 작았는데도 음식은 정말 훌륭했다.","sense":"인데도"},{"wordId":20969,"answer":"as soon as possible","form":"원형","example":"The landlord promised to fix our heater as soon as possible.","exampleTranslation":"집주인이 난방기를 가능한 한 빨리 고쳐 주겠다고 약속했다.","sense":"가능한 한 빨리"},{"wordId":20970,"answer":"right now","form":"원형","example":"The baby is sleeping right now, so please speak quietly.","exampleTranslation":"아기가 지금 자고 있으니 조용히 말해 주세요.","sense":"지금"},{"wordId":20973,"answer":"these days","form":"원형","example":"Many people buy their groceries online these days.","exampleTranslation":"요즘은 많은 사람들이 온라인으로 장을 본다.","sense":"요즘"},{"wordId":20975,"answer":"so far","form":"원형","example":"We have saved about half of the money for our trip so far.","exampleTranslation":"우리는 지금까지 여행 경비의 절반 정도를 모았다.","sense":"지금까지"},{"wordId":20976,"answer":"I ended up","form":"원형","example":"The shoes were on sale, so I ended up buying two pairs.","exampleTranslation":"신발이 할인 중이라 결국 두 켤레를 사게 됐어.","sense":"결국 하게 됐어"},{"wordId":20977,"answer":"it took me","form":"원형","example":"It took me three weeks to get used to my new glasses.","exampleTranslation":"새 안경에 익숙해지는 데 삼 주가 걸렸어.","sense":"걸렸어"},{"wordId":20978,"answer":"after all","form":"원형","example":"I thought the test would be hard, but it was easy after all.","exampleTranslation":"시험이 어려울 줄 알았는데 결국 쉬웠다.","sense":"결국"},{"wordId":20979,"answer":"now that you mention it","form":"원형","example":"Now that you mention it, I did see your keys on the kitchen table.","exampleTranslation":"듣고 보니 네 열쇠를 부엌 식탁에서 본 것 같아.","sense":"듣고 보니"},{"wordId":20980,"answer":"come to think of it","form":"원형","example":"Come to think of it, we have not been to the beach all summer.","exampleTranslation":"생각해 보니 우리 여름 내내 해변에 한 번도 안 갔네.","sense":"생각해 보니"},{"wordId":20981,"answer":"I almost forgot","form":"원형","example":"I almost forgot to tell you that the meeting moved to Thursday.","exampleTranslation":"회의가 목요일로 옮겨졌다는 걸 말해 주는 걸 하마터면 잊을 뻔했네.","sense":"잊을 뻔했다"},{"wordId":20982,"answer":"to change the subject","form":"원형","example":"To change the subject, did you decide where to go for vacation?","exampleTranslation":"화제를 바꾸자면, 휴가 어디로 갈지 정했어?","sense":"화제를 바꾸자면"},{"wordId":20983,"answer":"as I was saying","form":"원형","example":"As I was saying before the phone rang, we need a bigger table.","exampleTranslation":"전화가 울리기 전에 말하던 대로, 우리는 더 큰 식탁이 필요해.","sense":"아까 말하던 대로"},{"wordId":20984,"answer":"guess what","form":"원형","example":"Guess what, my sister is having a baby in the spring!","exampleTranslation":"있잖아, 우리 언니가 봄에 아기를 낳는대!","sense":"맞혀 봐"},{"wordId":20985,"answer":"you know what","form":"원형","example":"You know what, I think we should paint the kitchen yellow.","exampleTranslation":"있잖아, 부엌을 노란색으로 칠하는 게 좋을 것 같아.","sense":"있잖아"},{"wordId":20986,"answer":"believe it or not","form":"원형","example":"Believe it or not, my grandmother still rides her bike to the market.","exampleTranslation":"믿기 힘들겠지만 우리 할머니는 아직도 자전거를 타고 시장에 가신다.","sense":"믿기 힘들겠지만"},{"wordId":20988,"answer":"I have no idea","form":"원형","example":"I have no idea how to turn on this new coffee machine.","exampleTranslation":"이 새 커피 머신을 어떻게 켜는지 전혀 모르겠어.","sense":"전혀 모르겠어"},{"wordId":20990,"answer":"it slipped my mind","form":"원형","example":"I meant to buy milk on the way home, but it slipped my mind.","exampleTranslation":"집에 오는 길에 우유를 사려고 했는데 깜빡했어.","sense":"깜빡했어"},{"wordId":20995,"answer":"let me check","form":"원형","example":"Let me check whether we have any eggs left in the fridge.","exampleTranslation":"냉장고에 달걀이 남아 있는지 확인해 볼게.","sense":"확인해 볼게"},{"wordId":20996,"answer":"let me think about it","form":"원형","example":"The job offer sounds great, but let me think about it tonight.","exampleTranslation":"일자리 제안은 좋아 보이지만 오늘 밤에 생각 좀 해 볼게.","sense":"생각해 볼게"},{"wordId":20997,"answer":"give me a second","form":"원형","example":"Give me a second to find my wallet in this big bag.","exampleTranslation":"이 큰 가방에서 지갑 찾을 동안 잠깐만요.","sense":"잠깐만요"},{"wordId":20998,"answer":"sounds good to me","form":"원형","example":"A picnic by the lake on Sunday sounds good to me.","exampleTranslation":"일요일에 호숫가 소풍이라니 난 좋아.","sense":"난 좋아"},{"wordId":21001,"answer":"exhibits","form":"복수형","example":"The science museum added new exhibits about space travel last spring.","exampleTranslation":"과학관은 지난봄 우주여행에 관한 새 전시품들을 추가했다.","sense":"전시품"},{"wordId":21002,"answer":"exhibitions","form":"복수형","example":"Our city library holds small photo exhibitions in the lobby every month.","exampleTranslation":"우리 시립 도서관은 매달 로비에서 작은 사진 전시회를 연다.","sense":"전시회"},{"wordId":21003,"answer":"galleries","form":"복수형","example":"My aunt spent her whole vacation visiting galleries in New York.","exampleTranslation":"이모는 휴가 내내 뉴욕의 미술관들을 돌아다녔다.","sense":"미술관"},{"wordId":21004,"answer":"curators","form":"복수형","example":"The curators met with the artist to choose which works to show.","exampleTranslation":"큐레이터들은 어떤 작품을 전시할지 고르려고 작가를 만났다.","sense":"큐레이터"},{"wordId":21005,"answer":"masterpieces","form":"복수형","example":"This small museum owns two masterpieces by famous Dutch painters.","exampleTranslation":"이 작은 박물관은 유명한 네덜란드 화가들의 걸작 두 점을 소장하고 있다.","sense":"걸작"},{"wordId":21006,"answer":"sculptures","form":"복수형","example":"The park near my office is full of colorful metal sculptures.","exampleTranslation":"우리 사무실 근처 공원에는 화려한 금속 조각품이 가득하다.","sense":"조각품"},{"wordId":21007,"answer":"paintings","form":"복수형","example":"My grandmother hung three of her own paintings in the living room.","exampleTranslation":"할머니는 직접 그린 그림 세 점을 거실에 걸어 두셨다.","sense":"그림"},{"wordId":21008,"answer":"gift shop","form":"원형","example":"I bought a mug and some postcards at the gift shop yesterday.","exampleTranslation":"나는 어제 기념품 가게에서 머그잔과 엽서 몇 장을 샀다.","sense":"기념품 가게"},{"wordId":21009,"answer":"permanent collection","form":"원형","example":"Most of the museum's permanent collection comes from one wealthy family.","exampleTranslation":"그 박물관의 상설 소장품 대부분은 한 부유한 가문에서 기증받은 것이다.","sense":"상설 소장품"},{"wordId":21010,"answer":"special exhibition","form":"원형","example":"The special exhibition about space will stay open until the end of March.","exampleTranslation":"우주를 주제로 한 특별전은 3월 말까지 열린다.","sense":"특별전"},{"wordId":21011,"answer":"artifacts","form":"복수형","example":"Divers brought up several artifacts from an old ship near the coast.","exampleTranslation":"잠수부들이 해안 근처의 오래된 배에서 유물 몇 점을 건져 올렸다.","sense":"유물","alts":["relics"]},{"wordId":21012,"answer":"replicas","form":"복수형","example":"The shop sells small replicas of famous buildings for tourists.","exampleTranslation":"그 가게는 관광객을 위해 유명한 건물의 작은 모형을 판다.","sense":"모형","alts":["models"]},{"wordId":21013,"answer":"wings","form":"복수형","example":"The hospital has two new wings for children and older patients.","exampleTranslation":"그 병원에는 어린이와 노인 환자를 위한 새 병동이 두 개 있다.","sense":"건물 동"},{"wordId":21014,"answer":"portraits","form":"복수형","example":"The school hallway is lined with portraits of former principals.","exampleTranslation":"학교 복도에는 역대 교장 선생님들의 초상화가 줄지어 걸려 있다.","sense":"초상화"},{"wordId":21015,"answer":"most abstract","form":"최상급","example":"Of all the pieces in this room, this one is the most abstract.","exampleTranslation":"이 방에 있는 작품 중에서 이것이 가장 추상적이다.","sense":"추상적인"},{"wordId":21016,"answer":"oil painting","form":"원형","example":"My uncle spent six months working on one large oil painting of the sea.","exampleTranslation":"삼촌은 바다를 그린 큰 유화 한 점에 여섯 달을 매달렸다.","sense":"유화"},{"wordId":21017,"answer":"watercolors","form":"복수형","example":"My daughter painted some watercolors of flowers for her grandmother.","exampleTranslation":"딸은 할머니께 드리려고 꽃 수채화 몇 점을 그렸다.","sense":"수채화"},{"wordId":21018,"answer":"docents","form":"복수형","example":"The museum is looking for volunteer docents who can speak Spanish.","exampleTranslation":"박물관은 스페인어를 할 수 있는 자원봉사 해설사를 찾고 있다.","sense":"전시 해설사"},{"wordId":21019,"answer":"museum map","form":"원형","example":"The museum map shows that the restrooms are next to the cafe.","exampleTranslation":"박물관 안내도를 보면 화장실은 카페 옆에 있다.","sense":"박물관 안내도"},{"wordId":21020,"answer":"coat check","form":"원형","example":"It was so cold that the line for the coat check was very long.","exampleTranslation":"날씨가 너무 추워서 외투 보관소 앞의 줄이 아주 길었다.","sense":"외투 보관소"},{"wordId":21021,"answer":"free admission","form":"원형","example":"Children under six get free admission to the aquarium all year.","exampleTranslation":"여섯 살 미만 어린이는 일 년 내내 수족관에 무료로 입장할 수 있다.","sense":"무료 입장"},{"wordId":21022,"answer":"memberships","form":"복수형","example":"The gym offers cheaper memberships for students and seniors.","exampleTranslation":"그 헬스장은 학생과 어르신에게 더 저렴한 회원권을 제공한다.","sense":"회원권"},{"wordId":21023,"answer":"installations","form":"복수형","example":"The festival placed giant art installations along the river this year.","exampleTranslation":"올해 축제에서는 강을 따라 거대한 설치 미술 작품들이 놓였다.","sense":"설치 작품"},{"wordId":21024,"answer":"on loan","form":"원형","example":"The rare dinosaur bones are on loan from a museum in Canada.","exampleTranslation":"그 희귀한 공룡 뼈는 캐나다의 한 박물관에서 빌려 온 것이다.","sense":"대여 중인"},{"wordId":21025,"answer":"priceless","form":"원형","example":"These old family photos are priceless to me, so I keep them safe.","exampleTranslation":"이 오래된 가족사진들은 내게 매우 귀중해서 안전하게 보관한다.","sense":"매우 귀중한"},{"wordId":21026,"answer":"dinosaurs","form":"복수형","example":"My son can name more than fifty dinosaurs from memory.","exampleTranslation":"우리 아들은 공룡 이름을 쉰 개 넘게 외워서 말할 수 있다.","sense":"공룡"},{"wordId":21027,"answer":"fossils","form":"복수형","example":"We found tiny shell fossils in the rocks along the beach.","exampleTranslation":"우리는 해변 바위에서 작은 조개 화석을 발견했다.","sense":"화석"},{"wordId":21028,"answer":"mummies","form":"복수형","example":"The documentary explained how people in ancient Egypt made mummies.","exampleTranslation":"그 다큐멘터리는 고대 이집트 사람들이 미라를 어떻게 만들었는지 설명했다.","sense":"미라"},{"wordId":21029,"answer":"artworks","form":"복수형","example":"The hotel lobby displays artworks by young local artists.","exampleTranslation":"그 호텔 로비에는 젊은 지역 작가들의 미술품이 전시되어 있다.","sense":"미술품"},{"wordId":21030,"answer":"pottery","form":"원형","example":"My mother takes a pottery class every Saturday morning.","exampleTranslation":"어머니는 매주 토요일 아침에 도자기 수업을 들으신다.","sense":"도자기"},{"wordId":21031,"answer":"self-portraits","form":"복수형","example":"The art teacher asked us to draw self-portraits using only a mirror.","exampleTranslation":"미술 선생님은 거울만 보고 자화상을 그리라고 하셨다.","sense":"자화상"},{"wordId":21032,"answer":"still life","form":"원형","example":"For homework, we each had to draw a still life of kitchen objects.","exampleTranslation":"숙제로 우리는 각자 부엌 물건을 그린 정물화를 그려야 했다.","sense":"정물화"},{"wordId":21033,"answer":"more interactive","form":"비교급","example":"The new science center is much more interactive than the old one.","exampleTranslation":"새 과학관은 예전 과학관보다 훨씬 더 체험형이다.","sense":"체험형의"},{"wordId":21034,"answer":"do not touch","form":"원형","example":"My little brother wrote do not touch on a note and stuck it on his computer.","exampleTranslation":"남동생은 쪽지에 만지지 말라고 써서 자기 컴퓨터에 붙였다.","sense":"만지지 마시오"},{"wordId":21035,"answer":"restoration","form":"원형","example":"The restoration of the old train station took almost three years.","exampleTranslation":"오래된 기차역을 복원하는 데 거의 3년이 걸렸다.","sense":"복원"},{"wordId":21036,"answer":"modern art","form":"원형","example":"My sister studied modern art in college before she became a designer.","exampleTranslation":"언니는 디자이너가 되기 전에 대학에서 현대 미술을 공부했다.","sense":"현대 미술"},{"wordId":21037,"answer":"contemporary","form":"원형","example":"The theater group performs contemporary plays written by young writers.","exampleTranslation":"그 극단은 젊은 작가들이 쓴 현대극을 공연한다.","sense":"현대의"},{"wordId":21038,"answer":"last entry","form":"원형","example":"The zoo stays open until six, but last entry is at five.","exampleTranslation":"동물원은 여섯 시까지 열지만 마지막 입장은 다섯 시이다.","sense":"마지막 입장"},{"wordId":21039,"answer":"museum pass","form":"원형","example":"I bought a museum pass online, so we can skip the ticket line.","exampleTranslation":"내가 온라인으로 박물관 통합 이용권을 사 두어서 우리는 매표소 줄을 건너뛸 수 있다.","sense":"통합 이용권"},{"wordId":21040,"answer":"statues","form":"복수형","example":"Many tourists take photos with the bronze statues in the town square.","exampleTranslation":"많은 관광객이 시내 광장의 청동상들과 사진을 찍는다.","sense":"동상"},{"wordId":21041,"answer":"murals","form":"복수형","example":"Students painted bright murals on the walls of the school cafeteria.","exampleTranslation":"학생들이 학교 식당 벽에 밝은 벽화를 그렸다.","sense":"벽화"},{"wordId":21042,"answer":"antiques","form":"복수형","example":"My parents love searching for antiques at weekend flea markets.","exampleTranslation":"부모님은 주말 벼룩시장에서 골동품을 찾아다니는 것을 좋아하신다.","sense":"골동품"},{"wordId":21043,"answer":"art critic","form":"원형","example":"A famous art critic wrote a kind review of my friend's first show.","exampleTranslation":"한 유명한 미술 평론가가 내 친구의 첫 전시회에 대해 호의적인 평을 썼다.","sense":"미술 평론가"},{"wordId":21044,"answer":"brushstrokes","form":"복수형","example":"Her quick brushstrokes made the flowers look like they were moving.","exampleTranslation":"그녀의 빠른 붓놀림 덕분에 꽃들이 움직이는 것처럼 보였다.","sense":"붓놀림"},{"wordId":21045,"answer":"canvases","form":"복수형","example":"The art store is having a sale on canvases and paint this week.","exampleTranslation":"그 화방은 이번 주에 캔버스와 물감을 할인 판매한다.","sense":"캔버스"},{"wordId":21046,"answer":"frames","form":"복수형","example":"I ordered wooden frames for the photos from our wedding.","exampleTranslation":"우리 결혼식 사진을 넣을 나무 액자를 주문했다.","sense":"액자"},{"wordId":21047,"answer":"timed entry","form":"원형","example":"The popular garden uses timed entry to keep the paths from getting crowded.","exampleTranslation":"그 인기 있는 정원은 길이 붐비지 않도록 시간 지정 입장제를 운영한다.","sense":"시간 지정 입장"},{"wordId":21048,"answer":"natural history museum","form":"원형","example":"On rainy days, we often take the kids to the natural history museum.","exampleTranslation":"비 오는 날에는 아이들을 데리고 자연사 박물관에 자주 간다.","sense":"자연사 박물관"},{"wordId":21049,"answer":"on display","form":"원형","example":"The bakery keeps its prettiest wedding cakes on display in the front window.","exampleTranslation":"그 빵집은 가장 예쁜 웨딩 케이크를 앞쪽 진열창에 전시해 둔다.","sense":"전시 중인"},{"wordId":21050,"answer":"behind glass","form":"원형","example":"At the jewelry store, the most expensive rings are kept behind glass.","exampleTranslation":"보석 가게에서 가장 비싼 반지들은 유리장 속에 보관된다.","sense":"유리장 속에"},{"wordId":21051,"answer":"venues","form":"복수형","example":"Our town has three wedding venues, and all of them are booked in June.","exampleTranslation":"우리 동네에는 결혼식장이 세 곳 있는데 6월에는 모두 예약이 찼다.","sense":"행사장"},{"wordId":21052,"answer":"front row","form":"원형","example":"I always sit in the front row in class so I can hear the teacher.","exampleTranslation":"나는 선생님 말씀이 잘 들리도록 수업 때 늘 맨 앞줄에 앉는다.","sense":"맨 앞줄"},{"wordId":21053,"answer":"standing room","form":"원형","example":"The morning train was so crowded that there was only standing room.","exampleTranslation":"아침 기차가 너무 붐벼서 서서 갈 자리밖에 없었다.","sense":"입석"},{"wordId":21054,"answer":"setlists","form":"복수형","example":"The band changes their setlists every night, so each show feels different.","exampleTranslation":"그 밴드는 매일 밤 곡 목록을 바꿔서 공연마다 느낌이 다르다.","sense":"곡 목록"},{"wordId":21055,"answer":"lineups","form":"복수형","example":"This summer, both big festivals have amazing lineups full of famous singers.","exampleTranslation":"올여름에는 두 대형 축제 모두 유명 가수들로 꽉 찬 멋진 출연진을 자랑한다.","sense":"출연진"},{"wordId":21056,"answer":"box office","form":"원형","example":"The box office at the stadium opens two hours before the game starts.","exampleTranslation":"경기장 매표소는 경기 시작 두 시간 전에 문을 연다.","sense":"매표소"},{"wordId":21057,"answer":"intermissions","form":"복수형","example":"The play is almost four hours long, but there are two short intermissions.","exampleTranslation":"그 연극은 거의 네 시간짜리지만 짧은 휴식 시간이 두 번 있다.","sense":"중간 휴식"},{"wordId":21058,"answer":"orchestras","form":"복수형","example":"Many high schools in our city have their own student orchestras.","exampleTranslation":"우리 시의 많은 고등학교에는 자체 학생 관현악단이 있다.","sense":"관현악단"},{"wordId":21059,"answer":"conductors","form":"복수형","example":"Famous conductors from around the world will lead the concerts this season.","exampleTranslation":"이번 시즌에는 세계 각국의 유명 지휘자들이 연주회를 이끈다.","sense":"지휘자"},{"wordId":21060,"answer":"musicals","form":"복수형","example":"My mom has seen many old musicals and still sings the songs at home.","exampleTranslation":"엄마는 옛날 뮤지컬을 많이 보셔서 지금도 집에서 그 노래들을 부르신다.","sense":"뮤지컬"},{"wordId":21061,"answer":"standing ovation","form":"원형","example":"After her graduation speech, the students gave the principal a standing ovation.","exampleTranslation":"졸업 연설이 끝나자 학생들은 교장 선생님께 기립 박수를 보냈다.","sense":"기립 박수"},{"wordId":21062,"answer":"backstage","form":"원형","example":"My cousin works backstage at the theater, helping the actors change costumes.","exampleTranslation":"사촌은 극장 무대 뒤에서 배우들의 의상 갈아입는 것을 돕는 일을 한다.","sense":"무대 뒤에서"},{"wordId":21063,"answer":"merch","form":"원형","example":"The band sells most of its merch online instead of at concerts.","exampleTranslation":"그 밴드는 굿즈 대부분을 공연장이 아니라 온라인에서 판다.","sense":"굿즈"},{"wordId":21064,"answer":"earplugs","form":"원형","example":"My roommate snores, so I sleep with earplugs every night.","exampleTranslation":"룸메이트가 코를 골아서 나는 매일 밤 귀마개를 끼고 잔다.","sense":"귀마개"},{"wordId":21065,"answer":"soundcheck","form":"원형","example":"The singer arrived late, so the soundcheck started an hour behind schedule.","exampleTranslation":"가수가 늦게 도착해서 음향 점검이 예정보다 한 시간 늦게 시작됐다.","sense":"음향 점검"},{"wordId":21066,"answer":"spotlights","form":"복수형","example":"Bright spotlights lit up the old castle walls during the night festival.","exampleTranslation":"야간 축제 동안 밝은 조명들이 오래된 성벽을 환하게 비췄다.","sense":"스포트라이트"},{"wordId":21067,"answer":"curtain call","form":"원형","example":"The little actors in the school play waved to their parents during the curtain call.","exampleTranslation":"학교 연극에 나온 어린 배우들이 커튼콜 때 부모님께 손을 흔들었다.","sense":"커튼콜"},{"wordId":21068,"answer":"ushers","form":"복수형","example":"The theater needs more ushers for the busy holiday season.","exampleTranslation":"그 극장은 바쁜 연휴 시즌을 위해 안내원이 더 필요하다.","sense":"극장 안내원"},{"wordId":21069,"answer":"seat number","form":"원형","example":"I lost my ticket, so I could not remember my seat number on the plane.","exampleTranslation":"표를 잃어버려서 비행기 좌석 번호가 기억나지 않았다.","sense":"좌석 번호"},{"wordId":21070,"answer":"general admission","form":"원형","example":"General admission tickets for the baseball game are only ten dollars.","exampleTranslation":"그 야구 경기의 일반 입장권은 겨우 10달러이다.","sense":"일반 입장"},{"wordId":21071,"answer":"scalpers","form":"복수형","example":"The band sold tickets by name to stop scalpers from raising the prices.","exampleTranslation":"그 밴드는 암표상들이 가격을 올리지 못하도록 실명으로 표를 팔았다.","sense":"암표상"},{"wordId":21072,"answer":"wristbands","form":"복수형","example":"All the hotel guests wear colored wristbands to use the pool.","exampleTranslation":"호텔 투숙객은 모두 수영장을 이용하려면 색깔 있는 팔찌를 찬다.","sense":"입장 팔찌"},{"wordId":21073,"answer":"acoustics","form":"원형","example":"The acoustics in our church are so good that nobody needs a microphone.","exampleTranslation":"우리 교회는 음향이 아주 좋아서 아무도 마이크가 필요 없다.","sense":"음향 효과"},{"wordId":21074,"answer":"live music","form":"원형","example":"We had live music at our wedding instead of a DJ.","exampleTranslation":"우리는 결혼식에서 디제이 대신 라이브 음악을 준비했다.","sense":"라이브 음악"},{"wordId":21075,"answer":"gigs","form":"복수형","example":"My brother plays small gigs at coffee shops on weekends.","exampleTranslation":"형은 주말마다 카페에서 작은 공연을 한다.","sense":"소규모 공연"},{"wordId":21076,"answer":"cover band","form":"원형","example":"My dad and his friends started a cover band that plays old rock songs.","exampleTranslation":"아빠와 친구분들이 옛날 록 노래를 연주하는 커버 밴드를 결성했다.","sense":"커버 밴드"},{"wordId":21077,"answer":"audiences","form":"복수형","example":"The comedian changes his jokes for younger audiences.","exampleTranslation":"그 코미디언은 젊은 관객층에 맞춰 농담을 바꾼다.","sense":"관객"},{"wordId":21078,"answer":"performers","form":"복수형","example":"Street performers entertain tourists in the square every summer evening.","exampleTranslation":"여름 저녁마다 거리 공연자들이 광장에서 관광객들을 즐겁게 한다.","sense":"공연자"},{"wordId":21079,"answer":"drummers","form":"복수형","example":"The parade had twenty drummers marching at the very front.","exampleTranslation":"그 퍼레이드에서는 드러머 스무 명이 맨 앞에서 행진했다.","sense":"드러머"},{"wordId":21080,"answer":"vocalists","form":"복수형","example":"The choir is looking for two new vocalists for the holiday concert.","exampleTranslation":"그 합창단은 연말 공연을 위해 새 보컬 두 명을 찾고 있다.","sense":"보컬"},{"wordId":21081,"answer":"concert hall","form":"원형","example":"Our school band will perform at the city concert hall this spring.","exampleTranslation":"우리 학교 밴드가 올봄 시립 연주회장에서 공연한다.","sense":"연주회장"},{"wordId":21082,"answer":"concertgoers","form":"복수형","example":"Hundreds of concertgoers waited in the rain for the gates to open.","exampleTranslation":"수백 명의 공연 관람객이 문이 열리기를 빗속에서 기다렸다.","sense":"공연 관람객"},{"wordId":21083,"answer":"nosebleed seats","form":"원형","example":"My brother bought nosebleed seats for the basketball game to save money.","exampleTranslation":"형은 돈을 아끼려고 농구 경기의 맨 꼭대기 좌석을 샀다.","sense":"꼭대기 좌석"},{"wordId":21084,"answer":"floor seats","form":"원형","example":"My friends paid extra for floor seats so they could dance near the stage.","exampleTranslation":"친구들은 무대 가까이에서 춤추려고 돈을 더 내고 플로어석을 샀다.","sense":"플로어석"},{"wordId":21085,"answer":"autographs","form":"복수형","example":"My little brother collects autographs from his favorite baseball players.","exampleTranslation":"남동생은 좋아하는 야구 선수들의 사인을 모은다.","sense":"사인"},{"wordId":21086,"answer":"meet and greet","form":"원형","example":"The author held a short meet and greet at the bookstore after her talk.","exampleTranslation":"그 작가는 강연이 끝난 뒤 서점에서 짧은 만남 행사를 열었다.","sense":"만남 행사"},{"wordId":21087,"answer":"light stick","form":"원형","example":"My sister bought a new light stick for her favorite group's concert.","exampleTranslation":"여동생은 좋아하는 그룹의 콘서트에 가져갈 새 응원봉을 샀다.","sense":"응원봉"},{"wordId":21088,"answer":"doors open","form":"원형","example":"The movie starts at eight, and doors open about twenty minutes before.","exampleTranslation":"영화는 여덟 시에 시작하고 입장은 약 이십 분 전에 시작된다.","sense":"입장 시작"},{"wordId":21089,"answer":"presales","form":"복수형","example":"Most presales for popular concerts sell out in just a few minutes.","exampleTranslation":"인기 콘서트 선예매는 대부분 몇 분 만에 매진된다.","sense":"선예매"},{"wordId":21090,"answer":"e-tickets","form":"복수형","example":"The airline sent our e-tickets to my email this morning.","exampleTranslation":"항공사가 오늘 아침 내 이메일로 우리 전자 티켓을 보냈다.","sense":"전자 티켓"},{"wordId":21091,"answer":"will call","form":"원형","example":"My tickets did not arrive in the mail, so I picked them up at will call.","exampleTranslation":"표가 우편으로 오지 않아서 현장 수령 창구에서 찾았다.","sense":"현장 수령 창구"},{"wordId":21092,"answer":"operas","form":"복수형","example":"My grandfather loves Italian operas and listens to them while he cooks.","exampleTranslation":"할아버지는 이탈리아 오페라를 좋아하셔서 요리하실 때 들으신다.","sense":"오페라"},{"wordId":21093,"answer":"ballet","form":"원형","example":"My daughter has taken ballet lessons since she was five.","exampleTranslation":"딸은 다섯 살 때부터 발레 수업을 받아 왔다.","sense":"발레"},{"wordId":21094,"answer":"recitals","form":"복수형","example":"The music school holds student recitals at the end of every term.","exampleTranslation":"그 음악 학원은 매 학기 말에 학생 발표회를 연다.","sense":"발표회"},{"wordId":21095,"answer":"symphonies","form":"복수형","example":"Mozart wrote more than forty symphonies during his short life.","exampleTranslation":"모차르트는 짧은 생애 동안 마흔 곡이 넘는 교향곡을 썼다.","sense":"교향곡"},{"wordId":21096,"answer":"music festival","form":"원형","example":"My college friends and I met at a music festival ten years ago.","exampleTranslation":"대학 친구들과 나는 10년 전 한 음악 축제에서 처음 만났다.","sense":"음악 축제"},{"wordId":21097,"answer":"take a bow","form":"원형","example":"The teacher asked the students who won the contest to stand up and take a bow.","exampleTranslation":"선생님은 대회에서 우승한 학생들에게 일어나서 인사하라고 하셨다.","sense":"인사하다"},{"wordId":21098,"answer":"sound system","form":"원형","example":"We rented a sound system for the outdoor party in our backyard.","exampleTranslation":"우리는 뒷마당 야외 파티를 위해 음향 장비를 빌렸다.","sense":"음향 장비"},{"wordId":21099,"answer":"ringing in my ears","form":"원형","example":"After the fireworks show, I noticed a strange ringing in my ears.","exampleTranslation":"불꽃놀이가 끝난 뒤 나는 귀에서 이상하게 윙윙거리는 소리를 느꼈다.","sense":"귀 울림"},{"wordId":21100,"answer":"ticket holder","form":"원형","example":"Each ticket holder can bring one small bag into the stadium.","exampleTranslation":"표 소지자는 한 명당 작은 가방 하나를 경기장에 가지고 들어갈 수 있다.","sense":"표 소지자"},{"wordId":21101,"answer":"insomnia","form":"원형","example":"My grandmother suffers from insomnia, so she often reads until three in the morning.","exampleTranslation":"할머니는 불면증이 있으셔서 새벽 세 시까지 책을 읽으실 때가 많다.","sense":"불면증"},{"wordId":21102,"answer":"naps","form":"복수형","example":"Young children need short naps during the day to stay in a good mood.","exampleTranslation":"어린아이들은 기분 좋게 지내려면 낮에 짧은 낮잠이 필요하다.","sense":"낮잠"},{"wordId":21103,"answer":"fall asleep","form":"원형","example":"Babies often fall asleep in the car during long drives.","exampleTranslation":"아기들은 오래 차를 타고 가면 차 안에서 잠드는 일이 많다.","sense":"잠들다"},{"wordId":21104,"answer":"overslept","form":"과거형","example":"I overslept yesterday morning and missed the first bus to school.","exampleTranslation":"나는 어제 아침 늦잠을 자서 학교 가는 첫 버스를 놓쳤다.","sense":"늦잠 자다"},{"wordId":21105,"answer":"snoring","form":"-ing형","example":"I could not sleep last night because my roommate kept snoring loudly.","exampleTranslation":"룸메이트가 계속 크게 코를 골아서 나는 어젯밤 잠을 못 잤다.","sense":"코를 골다"},{"wordId":21106,"answer":"sleepwalking","form":"-ing형","example":"Doctors say that sleepwalking is more common in children than in adults.","exampleTranslation":"의사들은 자다가 걸어 다니는 증상이 어른보다 아이들에게 더 흔하다고 말한다.","sense":"자다가 걷다"},{"wordId":21107,"answer":"nightmares","form":"복수형","example":"My daughter had nightmares for a week after watching a scary movie.","exampleTranslation":"딸은 무서운 영화를 본 뒤 일주일 동안 악몽을 꿨다.","sense":"악몽"},{"wordId":21108,"answer":"bedtime","form":"원형","example":"Our kids always ask for one more story at bedtime.","exampleTranslation":"우리 아이들은 잘 시간이 되면 늘 이야기 하나만 더 해 달라고 조른다.","sense":"잘 시간"},{"wordId":21109,"answer":"snoozing","form":"-ing형","example":"Snoozing your alarm again and again can make you feel even more tired.","exampleTranslation":"알람을 계속 미루면 오히려 더 피곤해질 수 있다.","sense":"알람 미루다"},{"wordId":21110,"answer":"sleepier","form":"비교급","example":"My son always gets sleepier after a warm bath in the evening.","exampleTranslation":"아들은 저녁에 따뜻한 물로 목욕하고 나면 늘 더 졸려 한다.","sense":"졸린"},{"wordId":21111,"answer":"drowsiest","form":"최상급","example":"Right after lunch is the time when I feel drowsiest at work.","exampleTranslation":"점심 직후가 회사에서 내가 가장 나른함을 느끼는 때이다.","sense":"나른한"},{"wordId":21112,"answer":"more exhausted","form":"비교급","example":"I felt more exhausted after the long drive home than after the whole workday.","exampleTranslation":"나는 하루 종일 일한 것보다 집까지 오래 운전한 뒤에 더 녹초가 됐다.","sense":"녹초가 된"},{"wordId":21113,"answer":"well-rested","form":"원형","example":"The players were well-rested and ready for the big game on Saturday.","exampleTranslation":"선수들은 푹 쉬어서 토요일 큰 경기에 나설 준비가 되어 있었다.","sense":"푹 쉰"},{"wordId":21114,"answer":"toss and turn","form":"원형","example":"Many people toss and turn on hot summer nights without air conditioning.","exampleTranslation":"에어컨 없는 더운 여름밤에는 많은 사람이 잠 못 이루고 뒤척인다.","sense":"뒤척이다"},{"wordId":21115,"answer":"pillows","form":"복수형","example":"The hotel offers soft and firm pillows, so guests can choose.","exampleTranslation":"그 호텔은 손님이 고를 수 있도록 푹신한 베개와 단단한 베개를 둘 다 제공한다.","sense":"베개"},{"wordId":21116,"answer":"blankets","form":"복수형","example":"We packed warm blankets for the outdoor movie night in the park.","exampleTranslation":"우리는 공원에서 열리는 야외 영화의 밤에 가져갈 따뜻한 담요를 챙겼다.","sense":"담요"},{"wordId":21117,"answer":"melatonin","form":"원형","example":"My doctor told me to try melatonin before buying stronger sleep medicine.","exampleTranslation":"의사는 더 강한 수면제를 사기 전에 멜라토닌부터 먹어 보라고 했다.","sense":"멜라토닌"},{"wordId":21118,"answer":"sleeping pill","form":"원형","example":"My grandfather took a sleeping pill before the long overnight flight to Europe.","exampleTranslation":"할아버지는 유럽행 장거리 야간 비행 전에 수면제를 한 알 드셨다.","sense":"수면제"},{"wordId":21119,"answer":"recharges","form":"3인칭 단수형","example":"My sister usually recharges by reading in a quiet cafe on weekends.","exampleTranslation":"언니는 주말이면 보통 조용한 카페에서 책을 읽으며 재충전한다.","sense":"재충전하다"},{"wordId":21120,"answer":"yawned","form":"과거형","example":"The student yawned loudly in the middle of the history class yesterday.","exampleTranslation":"그 학생은 어제 역사 수업 도중에 크게 하품을 했다.","sense":"하품하다"},{"wordId":21121,"answer":"bags under my eyes","form":"원형","example":"I put a cold spoon on the bags under my eyes before the interview.","exampleTranslation":"나는 면접 전에 눈 밑 다크서클에 차가운 숟가락을 댔다.","sense":"다크서클"},{"wordId":21122,"answer":"all-nighters","form":"복수형","example":"My roommate pulled three all-nighters during exam week and got sick.","exampleTranslation":"룸메이트는 시험 주간에 세 번이나 밤을 새우다가 병이 났다.","sense":"밤샘"},{"wordId":21123,"answer":"catch up on sleep","form":"원형","example":"After the night shift, nurses often go straight home to catch up on sleep.","exampleTranslation":"간호사들은 야간 근무가 끝나면 밀린 잠을 자러 곧장 집에 가곤 한다.","sense":"밀린 잠 자다"},{"wordId":21124,"answer":"sound asleep","form":"원형","example":"My husband was sound asleep when the fire alarm went off.","exampleTranslation":"화재경보기가 울렸을 때 남편은 깊이 잠들어 있었다.","sense":"깊이 잠든"},{"wordId":21125,"answer":"eye mask","form":"원형","example":"The airline gave every passenger a free eye mask on the night flight.","exampleTranslation":"그 항공사는 야간 비행에서 모든 승객에게 수면 안대를 무료로 주었다.","sense":"수면 안대"},{"wordId":21126,"answer":"white noise","form":"원형","example":"Some parents use white noise to help their babies sleep longer.","exampleTranslation":"어떤 부모들은 아기가 더 오래 자도록 백색 소음을 활용한다.","sense":"백색 소음"},{"wordId":21127,"answer":"groggier","form":"비교급","example":"I feel even groggier when I sleep too late on Sunday mornings.","exampleTranslation":"일요일 아침에 너무 늦게까지 자면 오히려 정신이 더 몽롱하다.","sense":"몽롱한"},{"wordId":21128,"answer":"lights out","form":"원형","example":"At summer camp, lights out was at nine, but nobody fell asleep that early.","exampleTranslation":"여름 캠프에서 소등은 아홉 시였지만 그렇게 일찍 잠든 사람은 없었다.","sense":"소등"},{"wordId":21129,"answer":"sleep tracker","form":"원형","example":"My wife bought a sleep tracker to find out why she wakes up tired.","exampleTranslation":"아내는 왜 피곤한 채로 깨는지 알아보려고 수면 측정기를 샀다.","sense":"수면 측정기"},{"wordId":21130,"answer":"alarm clock","form":"원형","example":"My grandfather still uses an old alarm clock instead of his phone.","exampleTranslation":"할아버지는 아직도 휴대폰 대신 오래된 알람 시계를 쓰신다.","sense":"알람 시계"},{"wordId":21131,"answer":"hit snooze","form":"원형","example":"On cold winter mornings, I always want to hit snooze and stay in bed.","exampleTranslation":"추운 겨울 아침이면 나는 늘 알람을 미루고 침대에 더 있고 싶다.","sense":"알람 미루다"},{"wordId":21132,"answer":"pajamas","form":"원형","example":"The kids wore their pajamas to the movie night at school.","exampleTranslation":"아이들은 학교 영화의 밤에 잠옷을 입고 갔다.","sense":"잠옷"},{"wordId":21133,"answer":"blackout curtains","form":"원형","example":"We hung blackout curtains in the baby's room so she could nap during the day.","exampleTranslation":"아기가 낮에 낮잠을 잘 수 있도록 아기 방에 암막 커튼을 달았다.","sense":"암막 커튼"},{"wordId":21134,"answer":"sleep debt","form":"원형","example":"Doctors say you cannot fully pay back your sleep debt on the weekend.","exampleTranslation":"의사들은 쌓인 수면 부족을 주말에 다 갚을 수는 없다고 말한다.","sense":"수면 빚"},{"wordId":21135,"answer":"bad dream","form":"원형","example":"I woke up in the middle of the night from a bad dream about falling.","exampleTranslation":"나는 떨어지는 나쁜 꿈을 꾸다가 한밤중에 깼다.","sense":"나쁜 꿈"},{"wordId":21136,"answer":"sleep talking","form":"원형","example":"My wife says my sleep talking keeps her awake some nights.","exampleTranslation":"아내는 내 잠꼬대 때문에 가끔 밤에 잠을 못 잔다고 한다.","sense":"잠꼬대"},{"wordId":21137,"answer":"siestas","form":"복수형","example":"Long afternoon siestas are still common in some small towns in Mexico.","exampleTranslation":"멕시코의 일부 작은 마을에서는 오후에 긴 낮잠을 자는 일이 여전히 흔하다.","sense":"낮잠 시간"},{"wordId":21138,"answer":"rest day","form":"원형","example":"Our coach gives us one rest day after every big race.","exampleTranslation":"코치님은 큰 경기가 끝날 때마다 우리에게 휴식일을 하루 주신다.","sense":"휴식일"},{"wordId":21139,"answer":"put my feet up","form":"원형","example":"When my kids are finally asleep, I love to put my feet up with a book.","exampleTranslation":"아이들이 드디어 잠들면 나는 책을 들고 편히 쉬는 것을 좋아한다.","sense":"편히 쉬다"},{"wordId":21140,"answer":"breather","form":"원형","example":"The hike was steep, so we stopped halfway up for a breather.","exampleTranslation":"등산로가 가팔라서 우리는 중간쯤에서 멈춰 잠깐 숨을 돌렸다.","sense":"잠깐의 휴식"},{"wordId":21141,"answer":"more refreshed","form":"비교급","example":"A short walk outside made me feel more refreshed than another cup of coffee.","exampleTranslation":"밖에서 잠깐 걷는 것이 커피 한 잔 더 마시는 것보다 나를 더 개운하게 해 주었다.","sense":"개운한"},{"wordId":21142,"answer":"dead tired","form":"원형","example":"The movers were dead tired after carrying our piano up four floors.","exampleTranslation":"이삿짐센터 직원들은 우리 피아노를 4층까지 옮기고 나서 녹초가 되었다.","sense":"몹시 피곤한"},{"wordId":21143,"answer":"sleep-deprived","form":"원형","example":"Many sleep-deprived students fall asleep during their morning classes.","exampleTranslation":"잠이 부족한 학생들 중 상당수가 아침 수업 시간에 존다.","sense":"잠이 부족한"},{"wordId":21144,"answer":"sweet dreams","form":"원형","example":"My mom always kisses my little sister and says sweet dreams before turning off the light.","exampleTranslation":"엄마는 불을 끄기 전에 늘 여동생에게 뽀뽀하며 좋은 꿈 꾸라고 하신다.","sense":"좋은 꿈 꿔"},{"wordId":21145,"answer":"chamomile tea","form":"원형","example":"My aunt grows her own flowers to make chamomile tea at home.","exampleTranslation":"이모는 집에서 캐모마일 차를 만들려고 꽃을 직접 기른다.","sense":"캐모마일 차"},{"wordId":21146,"answer":"caffeine","form":"원형","example":"Energy drinks have a lot of caffeine and sugar, so I avoid them.","exampleTranslation":"에너지 음료에는 카페인과 설탕이 많아서 나는 마시지 않는다.","sense":"카페인"},{"wordId":21147,"answer":"counting sheep","form":"원형","example":"My son tried counting sheep last night, but he stopped at twenty.","exampleTranslation":"아들은 어젯밤 양을 세어 보았지만 스무 마리에서 그만두었다.","sense":"양 세기"},{"wordId":21148,"answer":"fall back asleep","form":"원형","example":"The thunder woke me up, and it took an hour to fall back asleep.","exampleTranslation":"천둥소리에 잠이 깼고 다시 잠드는 데 한 시간이 걸렸다.","sense":"다시 잠들다"},{"wordId":21149,"answer":"early riser","form":"원형","example":"As an early riser, my mom finishes her morning walk before sunrise.","exampleTranslation":"일찍 일어나는 엄마는 해가 뜨기 전에 아침 산책을 마치신다.","sense":"아침형 인간"},{"wordId":21150,"answer":"sleepless","form":"원형","example":"The neighbor's barking dog gave us a sleepless night.","exampleTranslation":"이웃집 개가 짖어 대는 바람에 우리는 잠 못 이루는 밤을 보냈다.","sense":"잠 못 이루는"},{"wordId":21151,"answer":"restarts","form":"3인칭 단수형","example":"My phone usually restarts by itself at night to finish its updates.","exampleTranslation":"내 휴대폰은 보통 밤에 업데이트를 마치려고 저절로 다시 켜진다.","sense":"다시 켜다"},{"wordId":21152,"answer":"toner","form":"원형","example":"Our office orders a new box of toner at the start of every month.","exampleTranslation":"우리 사무실은 매달 초에 토너를 한 상자씩 새로 주문한다.","sense":"토너"},{"wordId":21153,"answer":"ink cartridge","form":"원형","example":"The color ink cartridge for this printer costs more than the printer itself.","exampleTranslation":"이 프린터의 컬러 잉크 카트리지는 프린터 본체보다 비싸다.","sense":"잉크 카트리지"},{"wordId":21154,"answer":"viruses","form":"복수형","example":"The store will check your old computer for viruses for a small fee.","exampleTranslation":"그 가게에서는 적은 비용으로 오래된 컴퓨터에 바이러스가 있는지 검사해 준다.","sense":"컴퓨터 바이러스"},{"wordId":21155,"answer":"malware","form":"원형","example":"The bank warned customers about fake emails that install malware on their phones.","exampleTranslation":"은행은 휴대폰에 악성 소프트웨어를 설치하는 가짜 이메일에 대해 고객들에게 경고했다.","sense":"악성 프로그램"},{"wordId":21156,"answer":"backups","form":"복수형","example":"Our company makes backups of all customer data every night.","exampleTranslation":"우리 회사는 매일 밤 모든 고객 데이터를 백업해 둔다.","sense":"예비 사본"},{"wordId":21157,"answer":"cloud storage","form":"원형","example":"My wife pays for extra cloud storage because she takes so many photos of the kids.","exampleTranslation":"아내는 아이들 사진을 워낙 많이 찍어서 클라우드 저장 공간을 추가로 구매한다.","sense":"클라우드 저장"},{"wordId":21158,"answer":"hard drive","form":"원형","example":"My brother bought a bigger hard drive to store all his video games.","exampleTranslation":"형은 비디오 게임을 전부 저장하려고 더 큰 하드 드라이브를 샀다.","sense":"하드 드라이브"},{"wordId":21159,"answer":"chargers","form":"복수형","example":"The hotel front desk keeps spare phone chargers for guests to borrow.","exampleTranslation":"그 호텔 프런트에는 손님들이 빌려 쓸 수 있는 여분의 휴대폰 충전기가 있다.","sense":"충전기"},{"wordId":21160,"answer":"keyboards","form":"복수형","example":"The school bought new keyboards for every computer in the library.","exampleTranslation":"학교는 도서관의 모든 컴퓨터에 쓸 새 자판을 샀다.","sense":"자판"},{"wordId":21161,"answer":"printers","form":"복수형","example":"The library has two printers that students can use for free.","exampleTranslation":"그 도서관에는 학생들이 무료로 쓸 수 있는 인쇄기가 두 대 있다.","sense":"인쇄기"},{"wordId":21162,"answer":"scanners","form":"복수형","example":"At the airport, every bag goes through one of the big scanners.","exampleTranslation":"공항에서는 모든 가방이 대형 스캐너 중 하나를 통과한다.","sense":"스캐너"},{"wordId":21163,"answer":"error message","form":"원형","example":"My grandmother called me because an error message appeared on her new tablet.","exampleTranslation":"할머니는 새 태블릿에 오류 메시지가 떠서 나에게 전화하셨다.","sense":"오류 메시지"},{"wordId":21164,"answer":"pop-ups","form":"복수형","example":"This website has so many pop-ups that I cannot read the article.","exampleTranslation":"이 웹사이트는 팝업 창이 너무 많아서 기사를 읽을 수가 없다.","sense":"팝업 창"},{"wordId":21165,"answer":"browsers","form":"복수형","example":"Our online store works on all major browsers, including mobile ones.","exampleTranslation":"우리 온라인 쇼핑몰은 모바일을 포함한 모든 주요 브라우저에서 작동한다.","sense":"브라우저"},{"wordId":21166,"answer":"installing","form":"-ing형","example":"Installing the new washing machine took the plumber about two hours.","exampleTranslation":"배관공이 새 세탁기를 설치하는 데 두 시간쯤 걸렸다.","sense":"설치하다"},{"wordId":21167,"answer":"signals","form":"복수형","example":"Thick concrete walls can block phone signals inside the building.","exampleTranslation":"두꺼운 콘크리트 벽은 건물 안에서 휴대폰 신호를 막을 수 있다.","sense":"신호","alts":["cues"]},{"wordId":21168,"answer":"paired","form":"과거형","example":"I paired my new speaker with my phone yesterday in less than a minute.","exampleTranslation":"나는 어제 새 스피커를 휴대폰에 일 분도 안 걸려 연결했다.","sense":"연결하다","alts":["connected"]},{"wordId":21169,"answer":"tech support","form":"원형","example":"My dad treats me like free tech support whenever his phone acts strange.","exampleTranslation":"아빠는 휴대폰이 이상해질 때마다 나를 무료 기술 지원팀처럼 대하신다.","sense":"기술 지원"},{"wordId":21170,"answer":"IT department","form":"원형","example":"The new employee spent her first morning with the IT department setting up her laptop.","exampleTranslation":"신입 사원은 첫날 오전을 전산팀과 함께 노트북을 설정하며 보냈다.","sense":"전산팀"},{"wordId":21171,"answer":"help desk","form":"원형","example":"The library help desk can show you how to print from your phone.","exampleTranslation":"도서관 지원 창구에서 휴대폰으로 인쇄하는 방법을 알려 줄 수 있다.","sense":"지원 창구"},{"wordId":21172,"answer":"glitches","form":"복수형","example":"The new video game had so many glitches that players asked for refunds.","exampleTranslation":"그 새 비디오 게임은 오류가 너무 많아서 플레이어들이 환불을 요구했다.","sense":"오작동"},{"wordId":21173,"answer":"overheating","form":"-ing형","example":"On long summer drives, overheating can be a real problem for old cars.","exampleTranslation":"여름에 오래 운전하면 오래된 차에는 과열이 정말 문제가 될 수 있다.","sense":"과열되다"},{"wordId":21174,"answer":"software","form":"원형","example":"My cousin writes software for a company that makes medical equipment.","exampleTranslation":"사촌은 의료 장비를 만드는 회사에서 소프트웨어를 만든다.","sense":"소프트웨어"},{"wordId":21175,"answer":"laptops","form":"복수형","example":"Students may bring their laptops to the exam, but the internet will be off.","exampleTranslation":"학생들은 시험에 노트북을 가져와도 되지만 인터넷은 꺼져 있을 것이다.","sense":"노트북"},{"wordId":21176,"answer":"troubleshooting","form":"-ing형","example":"My brother spent all evening troubleshooting the printer in my home office.","exampleTranslation":"형은 저녁 내내 내 재택 사무실 프린터의 고장 원인을 찾았다.","sense":"원인을 찾다"},{"wordId":21177,"answer":"unresponsive","form":"원형","example":"The old man on the bench was unresponsive, so we called an ambulance right away.","exampleTranslation":"벤치에 있던 노인이 반응이 없어서 우리는 바로 구급차를 불렀다.","sense":"반응이 없는"},{"wordId":21179,"answer":"black screen","form":"원형","example":"The movie suddenly stopped, and the TV showed only a black screen.","exampleTranslation":"영화가 갑자기 멈추더니 텔레비전에 검은 화면만 나왔다.","sense":"검은 화면"},{"wordId":21180,"answer":"force quit","form":"원형","example":"My son had to force quit the game because it froze during the final level.","exampleTranslation":"아들은 마지막 단계에서 게임이 멈춰서 강제 종료해야 했다.","sense":"강제 종료하다"},{"wordId":21181,"answer":"power button","form":"원형","example":"The power button on my old phone is broken, so I cannot turn it on.","exampleTranslation":"내 옛날 휴대폰은 전원 버튼이 고장 나서 켤 수가 없다.","sense":"전원 버튼"},{"wordId":21182,"answer":"factory reset","form":"원형","example":"Before I sold my old phone, I did a factory reset to delete my data.","exampleTranslation":"나는 옛 휴대폰을 팔기 전에 데이터를 지우려고 공장 초기화를 했다.","sense":"공장 초기화"},{"wordId":21183,"answer":"operating system","form":"원형","example":"My new computer came with the latest operating system already installed.","exampleTranslation":"새 컴퓨터에는 최신 운영 체제가 이미 깔려 있었다.","sense":"운영 체제"},{"wordId":21184,"answer":"software update","form":"원형","example":"My car needed a software update before the new map would work.","exampleTranslation":"새 지도가 작동하려면 내 차에 소프트웨어 업데이트가 필요했다.","sense":"업데이트"},{"wordId":21185,"answer":"reinstalling","form":"-ing형","example":"Reinstalling the game fixed the sound problem on my son's computer.","exampleTranslation":"게임을 다시 설치하자 아들 컴퓨터의 소리 문제가 해결됐다.","sense":"재설치하다"},{"wordId":21186,"answer":"more compatible","form":"비교급","example":"The new version of the app is more compatible with older phones.","exampleTranslation":"그 앱의 새 버전은 오래된 휴대폰과 더 잘 호환된다.","sense":"호환되는"},{"wordId":21187,"answer":"print queue","form":"원형","example":"My long report is still waiting in the print queue behind everyone else's.","exampleTranslation":"내 긴 보고서는 아직 다른 사람들 것 뒤에서 인쇄 대기열에 걸려 있다.","sense":"인쇄 대기열"},{"wordId":21188,"answer":"out of paper","form":"원형","example":"The copier on the second floor is out of paper again, so please refill it.","exampleTranslation":"2층 복사기에 또 용지가 떨어졌으니 채워 주세요.","sense":"용지가 떨어진"},{"wordId":21189,"answer":"double-sided","form":"원형","example":"Please bring a double-sided copy of the form to your first appointment.","exampleTranslation":"첫 진료 때 그 서류를 양면으로 복사해서 가져오세요.","sense":"양면의"},{"wordId":21190,"answer":"hotspots","form":"복수형","example":"Many cafes and libraries in the city offer free Wi-Fi hotspots.","exampleTranslation":"시내의 많은 카페와 도서관이 무료 무선 인터넷 공유 지점을 제공한다.","sense":"무선 공유"},{"wordId":21191,"answer":"extenders","form":"복수형","example":"Our house is so big that we need two Wi-Fi extenders upstairs.","exampleTranslation":"우리 집은 너무 넓어서 위층에 무선 인터넷 증폭기가 두 개 필요하다.","sense":"증폭기"},{"wordId":21192,"answer":"disconnected","form":"과거형","example":"The video call disconnected twice during my job interview this morning.","exampleTranslation":"오늘 아침 취업 면접 도중에 화상 통화가 두 번이나 끊겼다.","sense":"연결이 끊기다"},{"wordId":21193,"answer":"surge protector","form":"원형","example":"My dad keeps the television and game console plugged into one surge protector.","exampleTranslation":"아빠는 텔레비전과 게임기를 과전압 방지 멀티탭 하나에 꽂아 두신다.","sense":"과전압 방지 탭"},{"wordId":21194,"answer":"extension cord","form":"원형","example":"We ran an extension cord to the backyard for the party lights.","exampleTranslation":"우리는 파티 조명을 달려고 뒷마당까지 연장선을 끌어왔다.","sense":"연장선"},{"wordId":21195,"answer":"flash drive","form":"원형","example":"The teacher asked us to bring our projects to class on a flash drive.","exampleTranslation":"선생님은 과제를 휴대용 메모리에 담아 수업에 가져오라고 하셨다.","sense":"휴대용 메모리"},{"wordId":21196,"answer":"adapters","form":"복수형","example":"Remember to pack power adapters for your trip to Europe.","exampleTranslation":"유럽 여행에 전원 변환 어댑터를 챙기는 것을 잊지 마세요.","sense":"어댑터"},{"wordId":21197,"answer":"corrupted file","form":"원형","example":"My best photo from the trip turned into a corrupted file that I cannot open.","exampleTranslation":"여행에서 찍은 가장 좋은 사진이 열리지 않는 손상된 파일이 되어 버렸다.","sense":"손상된 파일"},{"wordId":21198,"answer":"auto-save","form":"원형","example":"The game has an auto-save feature, so you can turn it off at any time.","exampleTranslation":"그 게임에는 자동 저장 기능이 있어서 언제든지 꺼도 된다.","sense":"자동 저장"},{"wordId":21199,"answer":"webcams","form":"복수형","example":"Some parents use small webcams to watch their babies from another room.","exampleTranslation":"어떤 부모들은 작은 웹캠으로 다른 방에서 아기를 지켜본다.","sense":"웹캠"},{"wordId":21200,"answer":"locked out","form":"원형","example":"My sister forgot her password and got locked out of her bank account.","exampleTranslation":"여동생은 비밀번호를 잊어버려서 은행 계정이 잠겨 버렸다.","sense":"계정이 잠긴"},{"wordId":21201,"answer":"freelancers","form":"복수형","example":"Many freelancers work from coffee shops because they do not have an office.","exampleTranslation":"많은 프리랜서들이 사무실이 없어서 카페에서 일한다.","sense":"프리랜서"},{"wordId":21202,"answer":"hourly rate","form":"원형","example":"The plumber's hourly rate is high, but he fixed the leak in twenty minutes.","exampleTranslation":"그 배관공은 시간당 요금이 비싸지만 이십 분 만에 누수를 고쳤다.","sense":"시간당 요금"},{"wordId":21203,"answer":"startups","form":"복수형","example":"Many young people in this city dream of working at tech startups.","exampleTranslation":"이 도시의 많은 젊은이들이 기술 신생 기업에서 일하기를 꿈꾼다.","sense":"신생 기업"},{"wordId":21204,"answer":"founders","form":"복수형","example":"The two founders of the bakery were best friends in high school.","exampleTranslation":"그 빵집의 두 창업자는 고등학교 시절 단짝이었다.","sense":"창업자"},{"wordId":21205,"answer":"co-founders","form":"복수형","example":"The three co-founders still eat lunch together every Friday.","exampleTranslation":"세 명의 공동 창업자는 지금도 매주 금요일에 함께 점심을 먹는다.","sense":"공동 창업자"},{"wordId":21206,"answer":"business plan","form":"원형","example":"For our final project, each team had to write a business plan for a cafe.","exampleTranslation":"기말 과제로 각 팀은 카페 사업 계획서를 써야 했다.","sense":"사업 계획서"},{"wordId":21207,"answer":"investors","form":"복수형","example":"The company invited its investors to a dinner to share good news.","exampleTranslation":"그 회사는 좋은 소식을 전하려고 투자자들을 저녁 식사에 초대했다.","sense":"투자자"},{"wordId":21208,"answer":"funding","form":"원형","example":"The animal shelter lost its government funding and now depends on donations.","exampleTranslation":"그 동물 보호소는 정부 지원금이 끊겨 이제 기부금에 의존한다.","sense":"자금"},{"wordId":21209,"answer":"pitches","form":"복수형","example":"The judges listened to ten short pitches from student teams.","exampleTranslation":"심사위원들은 학생 팀들의 짧은 발표 열 개를 들었다.","sense":"제안 발표"},{"wordId":21210,"answer":"revenue","form":"원형","example":"The museum gets most of its revenue from ticket sales and the cafe.","exampleTranslation":"그 박물관은 수익 대부분을 입장권 판매와 카페에서 얻는다.","sense":"수익"},{"wordId":21211,"answer":"profits","form":"복수형","example":"The farmers share their profits equally at the end of each season.","exampleTranslation":"농부들은 매 시즌이 끝나면 이익을 똑같이 나눈다.","sense":"이익"},{"wordId":21212,"answer":"self-employed","form":"원형","example":"My father has been self-employed as a carpenter for twenty years.","exampleTranslation":"아버지는 20년 동안 목수로 자영업을 해 오셨다.","sense":"자영업의"},{"wordId":21213,"answer":"side hustle","form":"원형","example":"My teacher has a side hustle as a wedding photographer on weekends.","exampleTranslation":"우리 선생님은 주말마다 결혼식 사진작가로 부업을 하신다.","sense":"부업"},{"wordId":21214,"answer":"logos","form":"복수형","example":"Most kids can recognize the logos of fast food restaurants.","exampleTranslation":"대부분의 아이들은 패스트푸드점 상징 마크를 알아본다.","sense":"로고"},{"wordId":21215,"answer":"market research","form":"원형","example":"The company did market research to find out what teenagers want in a phone.","exampleTranslation":"그 회사는 십 대들이 휴대폰에서 무엇을 원하는지 알아보려고 시장 조사를 했다.","sense":"시장 조사"},{"wordId":21216,"answer":"competitors","form":"복수형","example":"The two pizza shops on our street have been competitors for years.","exampleTranslation":"우리 동네 거리의 두 피자 가게는 여러 해 동안 경쟁 업체였다.","sense":"경쟁 업체"},{"wordId":21217,"answer":"niches","form":"복수형","example":"Small bookstores survive by finding niches like comics or travel guides.","exampleTranslation":"작은 서점들은 만화나 여행 안내서 같은 틈새시장을 찾아 살아남는다.","sense":"틈새시장"},{"wordId":21218,"answer":"scale up","form":"원형","example":"The bakery plans to scale up and open three more shops next year.","exampleTranslation":"그 빵집은 규모를 키워 내년에 매장을 세 곳 더 열 계획이다.","sense":"규모를 키우다"},{"wordId":21219,"answer":"equity","form":"원형","example":"Early employees at the company received some equity instead of a higher salary.","exampleTranslation":"그 회사의 초기 직원들은 더 높은 월급 대신 지분을 조금 받았다.","sense":"지분"},{"wordId":21220,"answer":"bootstrapped","form":"과거형","example":"My parents bootstrapped their flower shop in 1998 with only their savings.","exampleTranslation":"부모님은 1998년에 저축한 돈만으로 꽃집을 시작하셨다.","sense":"자력 창업하다"},{"wordId":21221,"answer":"cash flow","form":"원형","example":"The restaurant had good reviews, but poor cash flow forced it to close.","exampleTranslation":"그 식당은 평이 좋았지만 현금 흐름이 나빠서 문을 닫아야 했다.","sense":"현금 흐름"},{"wordId":21222,"answer":"coworking space","form":"원형","example":"The new coworking space downtown has free coffee and a quiet phone room.","exampleTranslation":"시내에 새로 생긴 공유 오피스에는 무료 커피와 조용한 통화실이 있다.","sense":"공유 오피스"},{"wordId":21223,"answer":"be my own boss","form":"원형","example":"After ten years in a big company, I finally decided to be my own boss.","exampleTranslation":"대기업에서 10년을 일한 뒤 나는 마침내 내 사업을 하기로 결심했다.","sense":"직접 사업하다"},{"wordId":21224,"answer":"entrepreneurs","form":"복수형","example":"The city offers free classes for young entrepreneurs who want to open shops.","exampleTranslation":"시는 가게를 열고 싶은 젊은 창업가들을 위해 무료 강좌를 제공한다.","sense":"창업가"},{"wordId":21225,"answer":"small business","form":"원형","example":"My aunt runs a small business that repairs bicycles near the river.","exampleTranslation":"이모는 강 근처에서 자전거를 고치는 작은 가게를 운영한다.","sense":"소규모 사업체"},{"wordId":21226,"answer":"business license","form":"원형","example":"The food truck owner got a fine because his business license had expired.","exampleTranslation":"그 푸드트럭 주인은 영업 허가가 만료되어 벌금을 물었다.","sense":"영업 허가"},{"wordId":21227,"answer":"seed money","form":"원형","example":"We used our wedding gifts as seed money for our small restaurant.","exampleTranslation":"우리는 결혼 축의금을 작은 식당의 종잣돈으로 썼다.","sense":"종잣돈"},{"wordId":21228,"answer":"angel investor","form":"원형","example":"A retired doctor became the angel investor for our health app.","exampleTranslation":"은퇴한 의사 한 분이 우리 건강 앱의 엔젤 투자자가 되었다.","sense":"엔젤 투자자"},{"wordId":21229,"answer":"pitch deck","form":"원형","example":"Our team spent the whole weekend making a pitch deck for the competition.","exampleTranslation":"우리 팀은 대회에 낼 투자 설명 자료를 만드느라 주말 내내 매달렸다.","sense":"투자 설명 자료"},{"wordId":21230,"answer":"target market","form":"원형","example":"The new toy company chose grandparents as its target market.","exampleTranslation":"그 신생 장난감 회사는 조부모를 주요 고객층으로 정했다.","sense":"목표 시장"},{"wordId":21231,"answer":"online store","form":"원형","example":"My mother opened an online store to sell her homemade kimchi.","exampleTranslation":"어머니는 직접 만든 김치를 팔려고 온라인 상점을 여셨다.","sense":"온라인 상점"},{"wordId":21232,"answer":"repeat customer","form":"원형","example":"The coffee shop owner remembers the name of every repeat customer.","exampleTranslation":"그 카페 주인은 단골손님 한 명 한 명의 이름을 다 기억한다.","sense":"단골 고객"},{"wordId":21233,"answer":"cold email","form":"원형","example":"My brother got his first job after sending a cold email to the manager.","exampleTranslation":"형은 그 관리자에게 무작정 이메일을 보낸 뒤 첫 일자리를 얻었다.","sense":"영업 이메일"},{"wordId":21234,"answer":"scope creep","form":"원형","example":"Our kitchen remodel went over budget because of scope creep.","exampleTranslation":"우리 부엌 리모델링은 작업 범위가 계속 늘어나서 예산을 초과했다.","sense":"범위 확대"},{"wordId":21235,"answer":"rush fee","form":"원형","example":"The print shop added a rush fee because we needed the posters the same day.","exampleTranslation":"우리가 포스터를 당일에 받아야 해서 인쇄소가 급행 요금을 붙였다.","sense":"급행 요금"},{"wordId":21236,"answer":"late payment","form":"원형","example":"The phone company charged me five dollars for a late payment last month.","exampleTranslation":"통신사가 지난달 연체 요금으로 나에게 5달러를 청구했다.","sense":"지급 지연"},{"wordId":21237,"answer":"upfront payment","form":"원형","example":"The wedding photographer asked for an upfront payment to hold the date.","exampleTranslation":"그 결혼식 사진작가는 날짜를 잡아 두려고 선금을 요청했다.","sense":"선금"},{"wordId":21238,"answer":"flat fee","form":"원형","example":"The airport taxi charges a flat fee to any hotel downtown.","exampleTranslation":"공항 택시는 시내 어느 호텔이든 정액 요금을 받는다.","sense":"정액 요금"},{"wordId":21239,"answer":"raise my rates","form":"원형","example":"My clients were very understanding when I had to raise my rates this spring.","exampleTranslation":"올봄 내가 요금을 올려야 했을 때 고객들은 충분히 이해해 주었다.","sense":"요금을 올리다"},{"wordId":21240,"answer":"overhead","form":"원형","example":"The restaurant moved to a smaller building to cut its overhead.","exampleTranslation":"그 식당은 운영비를 줄이려고 더 작은 건물로 이사했다.","sense":"간접비"},{"wordId":21241,"answer":"tax deduction","form":"원형","example":"Donations to the children's hospital can count as a tax deduction.","exampleTranslation":"어린이 병원에 낸 기부금은 세금 공제 대상이 될 수 있다.","sense":"세금 공제"},{"wordId":21242,"answer":"accountants","form":"복수형","example":"Most accountants work very long hours in the weeks before tax day.","exampleTranslation":"대부분의 회계사들은 세금 신고 마감 전 몇 주 동안 아주 오래 일한다.","sense":"회계사"},{"wordId":21243,"answer":"bookkeeping","form":"원형","example":"My mother does the bookkeeping for my father's small repair shop.","exampleTranslation":"어머니는 아버지의 작은 수리점 장부 정리를 맡고 계신다.","sense":"장부 정리"},{"wordId":21244,"answer":"profit margin","form":"원형","example":"Selling coffee has a much higher profit margin than selling sandwiches.","exampleTranslation":"커피를 파는 것은 샌드위치를 파는 것보다 이윤 폭이 훨씬 크다.","sense":"이윤 폭"},{"wordId":21245,"answer":"irregular income","form":"원형","example":"Many artists live on an irregular income and save money during good months.","exampleTranslation":"많은 예술가들은 수입이 불규칙해서 벌이가 좋은 달에 돈을 모아 둔다.","sense":"불규칙한 수입"},{"wordId":21246,"answer":"slow season","form":"원형","example":"Hotels near the beach offer big discounts during the slow season in winter.","exampleTranslation":"해변 근처 호텔들은 겨울 비수기에 큰 폭으로 할인을 해 준다.","sense":"비수기"},{"wordId":21247,"answer":"long-term client","form":"원형","example":"My mother has cut hair for one long-term client since 2005.","exampleTranslation":"어머니는 2005년부터 한 장기 고객의 머리를 잘라 오셨다.","sense":"장기 고객"},{"wordId":21248,"answer":"testimonials","form":"복수형","example":"The dentist put happy patient testimonials on the wall of the waiting room.","exampleTranslation":"그 치과 의사는 만족한 환자들의 추천 후기를 대기실 벽에 붙여 두었다.","sense":"추천 후기"},{"wordId":21249,"answer":"pivoting","form":"-ing형","example":"Pivoting to online classes helped the small yoga studio survive the long winter.","exampleTranslation":"온라인 수업으로 방향을 바꾼 덕분에 그 작은 요가원은 긴 겨울을 버텼다.","sense":"방향을 전환하다"},{"wordId":21250,"answer":"outsourcing","form":"-ing형","example":"Outsourcing the cleaning work gave the hotel staff more time for guests.","exampleTranslation":"청소 업무를 외주로 맡기자 호텔 직원들은 손님에게 쓸 시간이 늘었다.","sense":"외주를 주다"},{"wordId":21251,"answer":"split the bills","form":"원형","example":"My roommates and I split the bills, but we each buy our own food.","exampleTranslation":"룸메이트들과 나는 공과금을 나눠 내지만 식료품은 각자 산다.","sense":"공과금 나누다"},{"wordId":21252,"answer":"roommate agreement","form":"원형","example":"My new landlord gave me a sample roommate agreement to fill out with my friend.","exampleTranslation":"새 집주인은 친구와 함께 작성하라며 룸메이트 생활 규칙 합의서 견본을 주었다.","sense":"생활 합의서"},{"wordId":21253,"answer":"shared space","form":"원형","example":"The office lounge is a shared space, so please wash your cups after using them.","exampleTranslation":"사무실 휴게실은 함께 쓰는 공간이니 컵을 쓰고 나면 꼭 씻어 주세요.","sense":"공용 공간"},{"wordId":21254,"answer":"utilities","form":"원형","example":"The rent for this apartment includes utilities, so we only pay for the internet.","exampleTranslation":"이 아파트 월세에는 공과금이 포함되어 있어서 우리는 인터넷 요금만 낸다.","sense":"공과금"},{"wordId":21255,"answer":"rent split","form":"원형","example":"My roommate works from home, so we changed our rent split last month.","exampleTranslation":"룸메이트가 재택근무를 해서 우리는 지난달 월세 분담 방식을 바꿨다.","sense":"월세 분담"},{"wordId":21256,"answer":"clean up after yourself","form":"원형","example":"At the campsite, you must clean up after yourself before you leave.","exampleTranslation":"캠핑장에서는 떠나기 전에 자기가 어지른 것을 직접 치워야 한다.","sense":"직접 치우다"},{"wordId":21257,"answer":"dirty dishes","form":"원형","example":"After the big family dinner, my brother and I washed all the dirty dishes.","exampleTranslation":"성대한 가족 저녁 식사가 끝난 뒤 형과 나는 설거지거리를 전부 씻었다.","sense":"설거지거리"},{"wordId":21258,"answer":"label food","form":"원형","example":"At our office, workers label food in the fridge with their names and the date.","exampleTranslation":"우리 회사에서는 직원들이 냉장고 음식에 이름과 날짜를 적은 이름표를 붙인다.","sense":"이름표 붙이다"},{"wordId":21259,"answer":"borrow without asking","form":"원형","example":"My little sister likes to borrow without asking, especially my favorite sweaters.","exampleTranslation":"여동생은 내 물건을 묻지도 않고 빌려 가는데 특히 내가 아끼는 스웨터를 좋아한다.","sense":"말없이 빌리다"},{"wordId":21260,"answer":"personal space","form":"원형","example":"On a crowded subway, it is almost impossible to have any personal space.","exampleTranslation":"붐비는 지하철에서는 개인 공간을 갖기가 거의 불가능하다.","sense":"개인 공간"},{"wordId":21261,"answer":"more passive-aggressive","form":"비교급","example":"My sister gets more passive-aggressive when she is tired after work.","exampleTranslation":"언니는 퇴근하고 피곤하면 불만을 더 은근히 돌려서 드러낸다.","sense":"은근히 공격적인"},{"wordId":21262,"answer":"household supplies","form":"원형","example":"The supermarket has a big sale on household supplies like detergent this week.","exampleTranslation":"그 슈퍼마켓은 이번 주에 세제 같은 생활용품을 크게 할인한다.","sense":"생활용품"},{"wordId":21263,"answer":"toilet paper","form":"원형","example":"During the storm, every store in town ran out of toilet paper and water.","exampleTranslation":"폭풍이 오는 동안 동네 모든 가게에서 화장지와 물이 동났다.","sense":"화장지"},{"wordId":21264,"answer":"hog the bathroom","form":"원형","example":"My teenage daughters always hog the bathroom before school.","exampleTranslation":"십 대인 딸들은 학교 가기 전에 늘 화장실을 독차지한다.","sense":"화장실 독차지"},{"wordId":21265,"answer":"find a replacement","form":"원형","example":"Our coach got sick, so the school had to find a replacement for the season.","exampleTranslation":"코치님이 아프셔서 학교는 이번 시즌 동안 대신할 사람을 구해야 했다.","sense":"후임 구하다"},{"wordId":21266,"answer":"communal","form":"원형","example":"The students share a communal bathroom at the end of the hallway.","exampleTranslation":"학생들은 복도 끝에 있는 공동 화장실을 함께 쓴다.","sense":"공동의"},{"wordId":21267,"answer":"dorm room","form":"원형","example":"My son decorated his dorm room with photos from home.","exampleTranslation":"아들은 집에서 가져온 사진들로 기숙사 방을 꾸몄다.","sense":"기숙사 방"},{"wordId":21268,"answer":"resident advisor","form":"원형","example":"The resident advisor knocked on our door because our music was too loud.","exampleTranslation":"우리 음악 소리가 너무 커서 기숙사 생활 지도 학생이 문을 두드렸다.","sense":"생활 지도 학생"},{"wordId":21269,"answer":"neat freak","form":"원형","example":"My dad is a neat freak who washes his car every single weekend.","exampleTranslation":"아빠는 주말마다 빠짐없이 세차를 하시는 깔끔쟁이다.","sense":"깔끔쟁이"},{"wordId":21270,"answer":"slobs","form":"복수형","example":"My brothers are total slobs, and their room always smells like old socks.","exampleTranslation":"우리 형들은 완전히 지저분해서 방에서 늘 오래된 양말 냄새가 난다.","sense":"지저분한 사람"},{"wordId":21271,"answer":"leave the door unlocked","form":"원형","example":"In my small hometown, many families leave the door unlocked during the day.","exampleTranslation":"내 작은 고향 마을에서는 많은 가정이 낮에 문을 잠그지 않고 둔다.","sense":"문 안 잠그다"},{"wordId":21272,"answer":"thermostat setting","form":"원형","example":"My husband always changes the thermostat setting when I am not looking.","exampleTranslation":"남편은 내가 안 볼 때 늘 실내 온도 설정을 바꾼다.","sense":"실내 온도 설정"},{"wordId":21273,"answer":"turn the music down","form":"원형","example":"The neighbors asked us to turn the music down after ten at night.","exampleTranslation":"이웃들이 밤 열 시 이후에는 음악 소리를 줄여 달라고 부탁했다.","sense":"소리 줄이다"},{"wordId":21274,"answer":"share a room","form":"원형","example":"On the school trip, students will share a room with three classmates.","exampleTranslation":"수학여행에서 학생들은 반 친구 세 명과 방을 같이 쓰게 된다.","sense":"방을 같이 쓰다"},{"wordId":21275,"answer":"split the groceries","form":"원형","example":"My sister and I split the groceries when we cook together on weekends.","exampleTranslation":"언니와 나는 주말에 같이 요리할 때 장보기 비용을 나눈다.","sense":"식비 나누다"},{"wordId":21276,"answer":"my turn","form":"원형","example":"I waited for an hour at the bank before it was finally my turn.","exampleTranslation":"은행에서 한 시간을 기다린 끝에 마침내 내 차례가 되었다.","sense":"내 차례"},{"wordId":21277,"answer":"laundry schedule","form":"원형","example":"The hotel staff follow a strict laundry schedule for towels and sheets.","exampleTranslation":"호텔 직원들은 수건과 침대 시트에 대해 엄격한 세탁 일정을 따른다.","sense":"세탁 일정"},{"wordId":21278,"answer":"sound travels","form":"원형","example":"In this old library, sound travels so well that you must whisper.","exampleTranslation":"이 오래된 도서관에서는 소리가 아주 잘 울려서 속삭여야 한다.","sense":"소리가 울리다"},{"wordId":21280,"answer":"respect boundaries","form":"원형","example":"Good parents respect boundaries and knock before they enter a teenager's room.","exampleTranslation":"좋은 부모는 서로의 선을 지켜서 십 대 자녀의 방에 들어가기 전에 노크를 한다.","sense":"선을 지키다"},{"wordId":21281,"answer":"leave a note","form":"원형","example":"If the neighbor is not home, just leave a note under the door.","exampleTranslation":"이웃이 집에 없으면 문 밑에 쪽지를 남겨 두세요.","sense":"쪽지를 남기다"},{"wordId":21282,"answer":"roommate wanted","form":"원형","example":"My friend put up a roommate wanted sign at the coffee shop near campus.","exampleTranslation":"친구는 학교 근처 카페에 룸메이트 구함 안내문을 붙였다.","sense":"룸메이트 구함"},{"wordId":21283,"answer":"do my share","form":"원형","example":"At family dinners, I always try to do my share of the cooking.","exampleTranslation":"가족 식사 때 나는 늘 요리에서 내 몫을 하려고 노력한다.","sense":"내 몫을 하다"},{"wordId":21284,"answer":"ground rules","form":"원형","example":"The teacher set some ground rules for the class discussion on the first day.","exampleTranslation":"선생님은 첫날 수업 토론을 위한 기본 규칙을 몇 가지 정하셨다.","sense":"기본 규칙"},{"wordId":21285,"answer":"house meeting","form":"원형","example":"We called a house meeting after someone broke the washing machine.","exampleTranslation":"누군가 세탁기를 고장 내자 우리는 집 회의를 소집했다.","sense":"집 회의"},{"wordId":21286,"answer":"roommate finder","form":"원형","example":"My university has a free roommate finder for new students who need housing.","exampleTranslation":"우리 대학에는 집이 필요한 신입생을 위한 무료 룸메이트 찾기 서비스가 있다.","sense":"룸메이트 찾기"},{"wordId":21287,"answer":"live-in","form":"원형","example":"My grandmother has a live-in nurse who helps her during the day and night.","exampleTranslation":"할머니에게는 밤낮으로 돌봐 주는 상주 간호사가 있다.","sense":"상주하는"},{"wordId":21288,"answer":"messes","form":"복수형","example":"The kids made huge messes with paint during the art class.","exampleTranslation":"아이들은 미술 시간에 물감으로 온통 엉망을 만들었다.","sense":"엉망"},{"wordId":21289,"answer":"coexisting","form":"-ing형","example":"Coexisting with a noisy neighbor taught me a lot of patience.","exampleTranslation":"시끄러운 이웃과 어울려 지내면서 나는 인내심을 많이 배웠다.","sense":"어울려 지내다"},{"wordId":21290,"answer":"borrow my stuff","form":"원형","example":"My younger cousins always ask to borrow my stuff when they visit.","exampleTranslation":"어린 사촌들은 놀러 올 때마다 내 물건을 빌려 달라고 한다.","sense":"내 물건 빌리다"},{"wordId":21291,"answer":"wifi password","form":"원형","example":"The cafe writes the wifi password on the receipt for every customer.","exampleTranslation":"그 카페는 모든 손님의 영수증에 와이파이 비밀번호를 적어 준다.","sense":"와이파이 암호"},{"wordId":21292,"answer":"fridge shelf","form":"원형","example":"My mom saves the top fridge shelf for drinks and sauces.","exampleTranslation":"엄마는 냉장고 맨 위 칸을 음료와 소스용으로 비워 두신다.","sense":"냉장고 칸"},{"wordId":21293,"answer":"kitchen duty","form":"원형","example":"At summer camp, each cabin takes kitchen duty for one day.","exampleTranslation":"여름 캠프에서는 숙소마다 하루씩 부엌 당번을 맡는다.","sense":"부엌 당번"},{"wordId":21294,"answer":"bathroom schedule","form":"원형","example":"With six people in the house, we need a bathroom schedule on school days.","exampleTranslation":"집에 여섯 명이 살아서 학교 가는 날에는 화장실 사용 순서가 필요하다.","sense":"화장실 순서"},{"wordId":21295,"answer":"take out the recycling","form":"원형","example":"My son has to take out the recycling every Tuesday night.","exampleTranslation":"아들은 매주 화요일 밤에 재활용 쓰레기를 내놓아야 한다.","sense":"재활용 내놓다"},{"wordId":21296,"answer":"pay my share","form":"원형","example":"I always pay my share when my friends and I eat out together.","exampleTranslation":"친구들과 함께 외식할 때 나는 늘 내 몫을 낸다.","sense":"내 몫을 내다"},{"wordId":21297,"answer":"roommate drama","form":"원형","example":"My daughter calls me every week to tell me about the roommate drama in her dorm.","exampleTranslation":"딸은 매주 전화해서 기숙사 룸메이트 사이의 갈등 이야기를 한다.","sense":"룸메이트 갈등"},{"wordId":21298,"answer":"living arrangement","form":"원형","example":"My grandparents moved in with us, and the new living arrangement works well.","exampleTranslation":"조부모님이 우리와 함께 살게 되셨는데 새 주거 형태가 잘 맞는다.","sense":"주거 형태"},{"wordId":21299,"answer":"shared kitchen","form":"원형","example":"The hostel has a shared kitchen where guests can cook their own meals.","exampleTranslation":"그 호스텔에는 손님들이 직접 요리할 수 있는 공용 부엌이 있다.","sense":"공용 부엌"},{"wordId":21300,"answer":"housemates","form":"복수형","example":"My housemates and I take turns cooking dinner on weekdays.","exampleTranslation":"나와 한집에 사는 사람들은 평일에 돌아가며 저녁을 만든다.","sense":"한집 사람"},{"wordId":21301,"answer":"stressed out","form":"원형","example":"My students are stressed out because final exams start next Monday.","exampleTranslation":"기말고사가 다음 주 월요일에 시작해서 학생들이 스트레스를 잔뜩 받고 있다.","sense":"스트레스 받은"},{"wordId":21302,"answer":"take a breather","form":"원형","example":"After two hours of moving boxes, we sat down to take a breather.","exampleTranslation":"두 시간 동안 상자를 옮긴 뒤 우리는 앉아서 잠깐 숨을 돌렸다.","sense":"숨을 돌리다"},{"wordId":21303,"answer":"decompresses","form":"3인칭 단수형","example":"My husband usually decompresses by playing the guitar after dinner.","exampleTranslation":"남편은 보통 저녁을 먹은 뒤 기타를 치면서 긴장을 푼다.","sense":"긴장을 풀다","alts":["relaxes"]},{"wordId":21304,"answer":"self-care","form":"원형","example":"The school counselor taught the students simple ways to practice self-care during exams.","exampleTranslation":"학교 상담 선생님은 학생들에게 시험 기간에 자기 돌봄을 실천하는 간단한 방법을 알려 주셨다.","sense":"자기 돌봄"},{"wordId":21305,"answer":"mental health day","form":"원형","example":"Our company gives every worker one mental health day each month.","exampleTranslation":"우리 회사는 모든 직원에게 매달 하루씩 마음을 쉬게 하는 휴가를 준다.","sense":"마음 휴가"},{"wordId":21306,"answer":"more drained","form":"비교급","example":"I always feel more drained after a big party than after a long workday.","exampleTranslation":"나는 긴 근무일보다 큰 파티를 마치고 나면 늘 더 진이 빠진다.","sense":"진이 빠진"},{"wordId":21307,"answer":"breathing exercise","form":"원형","example":"The swimming coach taught us a breathing exercise to use before each race.","exampleTranslation":"수영 코치님은 경기 전마다 할 호흡 운동을 가르쳐 주셨다.","sense":"호흡 운동"},{"wordId":21308,"answer":"meditated","form":"과거형","example":"My grandmother meditated in her garden every morning last summer.","exampleTranslation":"할머니는 지난여름 매일 아침 정원에서 명상하셨다.","sense":"명상하다"},{"wordId":21309,"answer":"mindfulness","form":"원형","example":"Some schools now teach mindfulness to help children handle strong feelings.","exampleTranslation":"요즘 일부 학교는 아이들이 강한 감정을 다루도록 마음챙김을 가르친다.","sense":"마음챙김"},{"wordId":21310,"answer":"stress relief","form":"원형","example":"For my father, fishing on the lake is the best kind of stress relief.","exampleTranslation":"아버지에게는 호수에서 낚시하는 것이 최고의 스트레스 해소법이다.","sense":"스트레스 해소"},{"wordId":21311,"answer":"stress ball","form":"원형","example":"The dentist gave my nervous son a stress ball to squeeze during the checkup.","exampleTranslation":"치과 의사는 긴장한 아들에게 검진 중에 쥐고 있으라며 스트레스 볼을 주었다.","sense":"스트레스 볼"},{"wordId":21312,"answer":"me time","form":"원형","example":"My wife takes the kids out on Sundays so I can have some me time.","exampleTranslation":"아내는 내가 나만의 시간을 가질 수 있도록 일요일마다 아이들을 데리고 외출한다.","sense":"나만의 시간"},{"wordId":21313,"answer":"journaling","form":"원형","example":"My therapist suggested journaling as a way to understand my feelings better.","exampleTranslation":"상담 선생님은 내 감정을 더 잘 이해하는 방법으로 일기 쓰기를 권하셨다.","sense":"일기 쓰기"},{"wordId":21314,"answer":"gratitude journal","form":"원형","example":"My daughter started a gratitude journal for her school project on happiness.","exampleTranslation":"딸은 행복을 주제로 한 학교 과제를 위해 감사 일기를 쓰기 시작했다.","sense":"감사 일기"},{"wordId":21315,"answer":"most tense","form":"최상급","example":"The last five minutes of the final game were the most tense of the season.","exampleTranslation":"결승전의 마지막 5분은 이번 시즌에서 가장 긴장된 순간이었다.","sense":"긴장한"},{"wordId":21316,"answer":"tight shoulders","form":"원형","example":"The massage therapist said my tight shoulders come from carrying a heavy bag.","exampleTranslation":"마사지사는 내 뭉친 어깨가 무거운 가방을 메고 다녀서 생긴 거라고 했다.","sense":"뭉친 어깨"},{"wordId":21317,"answer":"overthinking","form":"-ing형","example":"Overthinking small decisions can waste a lot of your time and energy.","exampleTranslation":"사소한 결정을 지나치게 고민하면 시간과 에너지를 많이 낭비할 수 있다.","sense":"과하게 생각하다"},{"wordId":21318,"answer":"racing thoughts","form":"원형","example":"Writing a to-do list before bed helps me slow down my racing thoughts.","exampleTranslation":"자기 전에 할 일 목록을 쓰면 꼬리에 꼬리를 무는 생각이 잦아든다.","sense":"꼬리 무는 생각"},{"wordId":21319,"answer":"coping strategy","form":"원형","example":"Taking deep breaths is a simple coping strategy for nervous students before exams.","exampleTranslation":"깊게 숨을 쉬는 것은 시험 전 긴장한 학생들을 위한 간단한 대처 방법이다.","sense":"대처 방법"},{"wordId":21320,"answer":"set boundaries","form":"원형","example":"Parents need to set boundaries about how much time kids spend on screens.","exampleTranslation":"부모는 아이들이 화면을 보는 시간에 대해 선을 정해 줄 필요가 있다.","sense":"선을 정하다"},{"wordId":21321,"answer":"say no","form":"원형","example":"My sister finally learned to say no when friends ask her for money.","exampleTranslation":"언니는 친구들이 돈을 빌려 달라고 할 때 거절하는 법을 마침내 배웠다.","sense":"거절하다"},{"wordId":21322,"answer":"snap at","form":"원형","example":"I try not to snap at my kids when I come home tired.","exampleTranslation":"나는 피곤하게 집에 와도 아이들에게 쏘아붙이지 않으려고 노력한다.","sense":"쏘아붙이다"},{"wordId":21323,"answer":"talk it out","form":"원형","example":"My two sons had a fight, so I made them sit down and talk it out.","exampleTranslation":"두 아들이 싸워서 나는 둘을 앉혀 놓고 이야기로 풀게 했다.","sense":"이야기로 풀다"},{"wordId":21324,"answer":"support system","form":"원형","example":"Moving to a new country is hard without a support system nearby.","exampleTranslation":"가까이에 기댈 사람이 없으면 새로운 나라로 이사하는 것은 힘들다.","sense":"지지 기반"},{"wordId":21325,"answer":"digital detox","form":"원형","example":"Our family tried a digital detox during our camping trip in the mountains.","exampleTranslation":"우리 가족은 산으로 캠핑을 갔을 때 전자기기를 끊어 보았다.","sense":"전자기기 끊기"},{"wordId":21326,"answer":"bubble bath","form":"원형","example":"My little daughter loves a bubble bath with her rubber duck.","exampleTranslation":"어린 딸은 고무 오리 인형과 함께 하는 거품 목욕을 아주 좋아한다.","sense":"거품 목욕"},{"wordId":21327,"answer":"scented candle","form":"원형","example":"I bought my mom a scented candle that smells like fresh lemons.","exampleTranslation":"나는 엄마께 신선한 레몬 향이 나는 향초를 사 드렸다.","sense":"향초"},{"wordId":21328,"answer":"check in on","form":"원형","example":"Our neighbor asked us to check in on her cat while she is away.","exampleTranslation":"이웃은 자기가 없는 동안 고양이를 좀 살펴봐 달라고 부탁했다.","sense":"안부를 살피다"},{"wordId":21329,"answer":"mood swing","form":"원형","example":"The new medicine gave my father a mood swing for the first few days.","exampleTranslation":"새 약 때문에 아버지는 처음 며칠 동안 감정 기복을 겪으셨다.","sense":"감정 기복"},{"wordId":21330,"answer":"more short-tempered","form":"비교급","example":"My dad gets more short-tempered when he is hungry before dinner.","exampleTranslation":"아빠는 저녁 먹기 전 배가 고프면 더 쉽게 짜증을 내신다.","sense":"화를 잘 내는"},{"wordId":21331,"answer":"most frazzled","form":"최상급","example":"Of all the parents at the birthday party, I was the most frazzled.","exampleTranslation":"생일 파티에 온 부모들 가운데 내가 가장 기진맥진했다.","sense":"기진맥진한"},{"wordId":21332,"answer":"positive self-talk","form":"원형","example":"The tennis coach taught her players to use positive self-talk after losing a point.","exampleTranslation":"테니스 코치는 선수들에게 점수를 잃은 뒤 긍정적인 혼잣말을 하도록 가르쳤다.","sense":"긍정적 혼잣말"},{"wordId":21333,"answer":"one thing at a time","form":"원형","example":"When I clean the whole house, I try to focus on one thing at a time.","exampleTranslation":"집 전체를 청소할 때 나는 한 번에 하나씩 집중하려고 한다.","sense":"한 번에 하나씩"},{"wordId":21334,"answer":"nature walk","form":"원형","example":"Our class went on a nature walk to collect leaves for an art project.","exampleTranslation":"우리 반은 미술 과제에 쓸 나뭇잎을 모으려고 자연 속 산책을 나갔다.","sense":"자연 산책"},{"wordId":21335,"answer":"relaxation technique","form":"원형","example":"The nurse showed me a relaxation technique to use before the blood test.","exampleTranslation":"간호사는 혈액 검사 전에 쓸 긴장 이완법을 알려 주었다.","sense":"긴장 이완법"},{"wordId":21336,"answer":"stretch break","form":"원형","example":"On long bus tours, the driver stops for a stretch break every two hours.","exampleTranslation":"장거리 버스 여행에서는 운전기사가 두 시간마다 스트레칭 휴식을 위해 차를 세운다.","sense":"스트레칭 휴식"},{"wordId":21337,"answer":"mentally exhausted","form":"원형","example":"After the long chess tournament, my son was mentally exhausted but happy.","exampleTranslation":"긴 체스 대회가 끝난 뒤 아들은 정신적으로 지쳤지만 행복해했다.","sense":"정신적으로 지친"},{"wordId":21338,"answer":"emotional exhaustion","form":"원형","example":"Many new teachers quit because of emotional exhaustion in their first few years.","exampleTranslation":"많은 신규 교사가 처음 몇 년 사이에 감정적 소진 때문에 그만둔다.","sense":"감정적 소진"},{"wordId":21339,"answer":"keep things in perspective","form":"원형","example":"My grandfather always helps me keep things in perspective when I fail a test.","exampleTranslation":"할아버지는 내가 시험에 떨어질 때마다 상황을 넓게 보도록 도와주신다.","sense":"넓게 보다"},{"wordId":21340,"answer":"stress level","form":"원형","example":"My stress level goes up every time my boss sends emails on Sunday.","exampleTranslation":"사장님이 일요일에 이메일을 보낼 때마다 내 스트레스 수준이 올라간다.","sense":"스트레스 수준"},{"wordId":21341,"answer":"pamper myself","form":"원형","example":"On my birthday, I like to pamper myself with a nice dinner and a new book.","exampleTranslation":"생일에는 근사한 저녁과 새 책으로 나 자신에게 호사를 누리게 해 주는 것을 좋아한다.","sense":"호사를 누리다"},{"wordId":21342,"answer":"breaking point","form":"원형","example":"With three crying babies on the plane, the flight attendant reached her breaking point.","exampleTranslation":"비행기에서 아기 셋이 울어 대자 승무원은 한계에 다다랐다.","sense":"한계점"},{"wordId":21343,"answer":"stress eating","form":"원형","example":"My roommate turns to stress eating whenever she has a big exam.","exampleTranslation":"룸메이트는 큰 시험이 있을 때마다 스트레스를 받아 폭식을 한다.","sense":"스트레스성 폭식"},{"wordId":21344,"answer":"under a lot of stress","form":"원형","example":"Nurses were under a lot of stress during the busy flu season last winter.","exampleTranslation":"지난겨울 독감이 유행하던 바쁜 시기에 간호사들은 스트레스를 많이 받았다.","sense":"스트레스 많은"},{"wordId":21345,"answer":"take things slow","form":"원형","example":"After moving to a new city, I decided to take things slow and make friends gradually.","exampleTranslation":"새 도시로 이사한 뒤 나는 서두르지 않고 천천히 친구를 사귀기로 했다.","sense":"천천히 하다"},{"wordId":21346,"answer":"clear my head","form":"원형","example":"I often ride my bike along the river to clear my head after work.","exampleTranslation":"나는 퇴근 후 머리를 식히려고 강을 따라 자전거를 자주 탄다.","sense":"머리를 식히다"},{"wordId":21347,"answer":"lose sleep over","form":"원형","example":"The test is only a small quiz, so do not lose sleep over it.","exampleTranslation":"그 시험은 작은 쪽지 시험일 뿐이니 그것 때문에 잠 못 이룰 필요 없다.","sense":"크게 걱정하다"},{"wordId":21348,"answer":"pressure cooker","form":"원형","example":"The restaurant kitchen becomes a pressure cooker on busy Saturday nights.","exampleTranslation":"바쁜 토요일 밤이면 그 식당 주방은 압박이 극심한 곳이 된다.","sense":"압박 심한 환경"},{"wordId":21349,"answer":"worry too much","form":"원형","example":"Parents often worry too much when their children travel alone for the first time.","exampleTranslation":"부모들은 자녀가 처음 혼자 여행을 떠나면 너무 걱정하곤 한다.","sense":"너무 걱정하다"},{"wordId":21350,"answer":"feel better","form":"원형","example":"A phone call from an old friend always makes me feel better on hard days.","exampleTranslation":"힘든 날에는 오랜 친구의 전화 한 통이 늘 내 기분을 나아지게 한다.","sense":"기분 나아지다"},{"wordId":21351,"answer":"sleeper car","form":"원형","example":"My grandparents rode in a sleeper car across the country for their anniversary.","exampleTranslation":"조부모님은 결혼기념일에 침대칸을 타고 전국을 횡단하셨다.","sense":"침대칸"},{"wordId":21352,"answer":"dining car","form":"원형","example":"The dining car on this train serves hot breakfast until ten in the morning.","exampleTranslation":"이 기차의 식당칸은 오전 열 시까지 따뜻한 아침 식사를 제공한다.","sense":"식당칸"},{"wordId":21353,"answer":"quiet car","form":"원형","example":"I always sit in the quiet car so I can read on my way to work.","exampleTranslation":"나는 출근길에 책을 읽으려고 늘 정숙 객차에 앉는다.","sense":"정숙 객차"},{"wordId":21354,"answer":"seat reservation","form":"원형","example":"During the holidays, you cannot board the fast train without a seat reservation.","exampleTranslation":"연휴 기간에는 좌석 예약 없이 고속 열차에 탈 수 없다.","sense":"좌석 예약"},{"wordId":21355,"answer":"reserved seat","form":"원형","example":"My grandfather had a reserved seat near the window for the long trip home.","exampleTranslation":"할아버지는 집으로 가는 긴 여정을 위해 창가 쪽 지정석을 잡아 두셨다.","sense":"지정석"},{"wordId":21356,"answer":"unreserved seat","form":"원형","example":"We bought the tickets late, so we had to look for an unreserved seat.","exampleTranslation":"우리는 표를 늦게 사서 자유석을 찾아다녀야 했다.","sense":"자유석"},{"wordId":21357,"answer":"departure board","form":"원형","example":"The departure board at the airport showed that our flight was delayed.","exampleTranslation":"공항 출발 안내판에 우리 항공편이 지연되었다고 나와 있었다.","sense":"출발 안내판"},{"wordId":21358,"answer":"connecting train","form":"원형","example":"The conductor told us the connecting train would wait for our late train.","exampleTranslation":"차장은 갈아탈 기차가 우리의 늦은 기차를 기다려 줄 거라고 말했다.","sense":"갈아탈 기차"},{"wordId":21359,"answer":"express train","form":"원형","example":"My dad takes the express train to the city because it saves him twenty minutes.","exampleTranslation":"아빠는 이십 분을 아낄 수 있어서 시내까지 급행열차를 타신다.","sense":"급행열차"},{"wordId":21360,"answer":"local train","form":"원형","example":"We took the local train so we could visit the small villages along the way.","exampleTranslation":"우리는 가는 길에 작은 마을들을 들르려고 완행열차를 탔다.","sense":"완행열차"},{"wordId":21361,"answer":"high-speed rail","form":"원형","example":"The government plans to build high-speed rail between the two biggest cities.","exampleTranslation":"정부는 두 대도시 사이에 고속철도를 놓을 계획이다.","sense":"고속철도"},{"wordId":21362,"answer":"overnight bus","form":"원형","example":"The students took an overnight bus to the mountains and arrived at sunrise.","exampleTranslation":"학생들은 산으로 가는 야간 버스를 타고 해 뜰 무렵 도착했다.","sense":"야간 버스"},{"wordId":21363,"answer":"long-distance bus","form":"원형","example":"My aunt prefers the long-distance bus because she gets nervous on planes.","exampleTranslation":"이모는 비행기를 타면 불안해져서 장거리 버스를 더 좋아한다.","sense":"장거리 버스"},{"wordId":21364,"answer":"bus terminal","form":"원형","example":"The new bus terminal has a food court and a large waiting room.","exampleTranslation":"새 버스 터미널에는 푸드 코트와 넓은 대합실이 있다.","sense":"버스 터미널"},{"wordId":21365,"answer":"luggage rack","form":"원형","example":"The old man could not reach the luggage rack, so I lifted his bag for him.","exampleTranslation":"노인이 짐 선반에 손이 닿지 않아서 내가 가방을 올려 드렸다.","sense":"짐 선반"},{"wordId":21366,"answer":"train car","form":"원형","example":"The first train car was so crowded that we walked to the back.","exampleTranslation":"첫 번째 열차 칸이 너무 붐벼서 우리는 뒤쪽으로 걸어갔다.","sense":"열차 칸"},{"wordId":21367,"answer":"car number","form":"원형","example":"Your car number is printed in the top corner of the ticket.","exampleTranslation":"호차 번호는 표 위쪽 모서리에 인쇄되어 있다.","sense":"호차 번호"},{"wordId":21368,"answer":"rail pass","form":"원형","example":"My cousin used a rail pass to travel around Europe for a month.","exampleTranslation":"사촌은 철도 패스로 한 달 동안 유럽을 여행했다.","sense":"철도 패스"},{"wordId":21369,"answer":"train schedule","form":"원형","example":"The train schedule changes in winter, so check the times before you leave home.","exampleTranslation":"겨울에는 열차 시간표가 바뀌니 집을 나서기 전에 시간을 확인하세요.","sense":"열차 시간표"},{"wordId":21370,"answer":"miss the train","form":"원형","example":"If you stop for coffee now, you will miss the train to the airport.","exampleTranslation":"지금 커피를 사러 들르면 공항 가는 기차를 놓칠 것이다.","sense":"기차를 놓치다"},{"wordId":21371,"answer":"catch the train","form":"원형","example":"My brother left work early yesterday to catch the train home for the holiday.","exampleTranslation":"형은 명절에 집에 가는 기차를 타려고 어제 일찍 퇴근했다.","sense":"기차를 타다"},{"wordId":21372,"answer":"all aboard","form":"원형","example":"The captain shouted all aboard, and the passengers hurried onto the ferry.","exampleTranslation":"선장이 모두 승선하라고 외치자 승객들이 서둘러 여객선에 올랐다.","sense":"모두 승차하세요"},{"wordId":21373,"answer":"ticket gate","form":"원형","example":"My card did not work, so the ticket gate would not open for me.","exampleTranslation":"카드가 작동하지 않아서 개찰구가 열리지 않았다.","sense":"개찰구"},{"wordId":21374,"answer":"ticket machine","form":"원형","example":"A station worker helped the tourists buy tickets from the ticket machine.","exampleTranslation":"역 직원이 관광객들이 승차권 발매기에서 표 사는 것을 도와주었다.","sense":"승차권 발매기"},{"wordId":21375,"answer":"validate my ticket","form":"원형","example":"Before I get on the tram, I always validate my ticket at the yellow box.","exampleTranslation":"나는 트램에 타기 전에 늘 노란 기계에서 승차권을 개시한다.","sense":"승차권 개시하다"},{"wordId":21376,"answer":"fold-down table","form":"원형","example":"My son ate his sandwich on the fold-down table during the flight.","exampleTranslation":"아들은 비행 중에 접이식 테이블 위에서 샌드위치를 먹었다.","sense":"접이식 테이블"},{"wordId":21377,"answer":"make a stop","form":"원형","example":"On the way to the beach, we will make a stop at my aunt's house.","exampleTranslation":"해변으로 가는 길에 우리는 이모 댁에 들를 것이다.","sense":"들르다"},{"wordId":21378,"answer":"pull into","form":"원형","example":"We watched the old steam train pull into the small station at noon.","exampleTranslation":"우리는 오래된 증기 기관차가 정오에 작은 역으로 들어오는 것을 지켜보았다.","sense":"들어오다"},{"wordId":21379,"answer":"baggage compartment","form":"원형","example":"The tour guide reminded us to take our bags from the baggage compartment.","exampleTranslation":"여행 가이드가 짐칸에서 가방을 꼭 챙기라고 일러 주었다.","sense":"짐칸"},{"wordId":21380,"answer":"onboard restroom","form":"원형","example":"The onboard restroom on our bus was out of order during the whole trip.","exampleTranslation":"우리 버스의 차내 화장실은 여행 내내 고장 나 있었다.","sense":"차내 화장실"},{"wordId":21381,"answer":"snack cart","form":"원형","example":"My kids got very excited when they saw the snack cart coming down the aisle.","exampleTranslation":"아이들은 간식 카트가 통로로 다가오는 것을 보고 무척 신이 났다.","sense":"간식 카트"},{"wordId":21382,"answer":"standing ticket","form":"원형","example":"My friend rode for three hours on a standing ticket during the busy holiday.","exampleTranslation":"친구는 붐비는 명절에 입석표로 세 시간을 서서 갔다.","sense":"입석표"},{"wordId":21383,"answer":"change trains","form":"원형","example":"Tourists going to the old town have to change trains at the central station.","exampleTranslation":"구시가지로 가는 관광객들은 중앙역에서 기차를 갈아타야 한다.","sense":"기차를 갈아타다"},{"wordId":21384,"answer":"wrong train","form":"원형","example":"My grandmother got on the wrong train, so a kind stranger helped her get home.","exampleTranslation":"할머니가 기차를 잘못 타셔서 친절한 낯선 사람이 집에 가시는 걸 도와드렸다.","sense":"잘못 탄 기차"},{"wordId":21385,"answer":"station announcement","form":"원형","example":"A station announcement said that the last train would leave ten minutes late.","exampleTranslation":"역 안내 방송에서 마지막 기차가 십 분 늦게 출발한다고 했다.","sense":"역 안내 방송"},{"wordId":21386,"answer":"sleeper berth","form":"원형","example":"The kids fought over who would get the sleeper berth next to the window.","exampleTranslation":"아이들은 창가 옆 침대칸 침대를 누가 차지할지를 두고 다퉜다.","sense":"침대칸 침대"},{"wordId":21387,"answer":"upper berth","form":"원형","example":"My little brother climbed up to the upper berth and fell asleep right away.","exampleTranslation":"남동생은 위 칸 침대로 올라가더니 곧바로 잠들었다.","sense":"위 칸 침대"},{"wordId":21388,"answer":"next stop","form":"원형","example":"The bus driver forgot to announce the next stop, so I missed my station.","exampleTranslation":"버스 기사가 다음 정류장을 안내하는 것을 잊어서 나는 내릴 곳을 지나쳤다.","sense":"다음 정차역"},{"wordId":21389,"answer":"round trip","form":"원형","example":"The round trip to the island takes about four hours by ferry.","exampleTranslation":"그 섬까지 배로 왕복하는 데 네 시간쯤 걸린다.","sense":"왕복 여행"},{"wordId":21390,"answer":"boarding time","form":"원형","example":"The airline sent a text to remind us that the boarding time had changed.","exampleTranslation":"항공사는 탑승 시간이 바뀌었다고 알려 주는 문자를 보냈다.","sense":"탑승 시간"},{"wordId":21391,"answer":"departure time","form":"원형","example":"Our school trip has an early departure time of six in the morning.","exampleTranslation":"우리 수학여행은 출발 시간이 아침 여섯 시로 이르다.","sense":"출발 시간"},{"wordId":21392,"answer":"platform number","form":"원형","example":"The station worker told us the platform number for the train to the airport.","exampleTranslation":"역 직원이 공항 가는 기차의 승강장 번호를 알려 주었다.","sense":"승강장 번호"},{"wordId":21393,"answer":"stretch my legs","form":"원형","example":"During the long meeting, I stood up for a minute to stretch my legs.","exampleTranslation":"긴 회의 도중에 나는 다리를 펴려고 잠깐 일어났다.","sense":"다리를 펴다"},{"wordId":21394,"answer":"long ride","form":"원형","example":"The drive to my grandparents' farm is a long ride, so the kids usually sleep.","exampleTranslation":"조부모님 농장까지는 차로 오래 가야 해서 아이들은 보통 잠을 잔다.","sense":"오래 타는 길"},{"wordId":21395,"answer":"train ride","form":"원형","example":"My son talked about his first train ride for weeks after we got home.","exampleTranslation":"아들은 집에 돌아온 뒤 몇 주 동안이나 첫 기차 여행 이야기를 했다.","sense":"기차 여행"},{"wordId":21396,"answer":"reclining seat","form":"원형","example":"The new movie theater has a large reclining seat for every guest.","exampleTranslation":"새 영화관에는 관객마다 등받이가 젖혀지는 넓은 좌석이 있다.","sense":"젖혀지는 좌석"},{"wordId":21397,"answer":"bus ticket","form":"원형","example":"My little sister lost her bus ticket, so the driver let her ride for free.","exampleTranslation":"여동생이 버스표를 잃어버렸는데 기사님이 그냥 공짜로 태워 주셨다.","sense":"버스표"},{"wordId":21398,"answer":"train station","form":"원형","example":"The old train station in our town is now a popular cafe and bookstore.","exampleTranslation":"우리 동네의 옛 기차역은 이제 인기 있는 카페 겸 서점이 되었다.","sense":"기차역"},{"wordId":21399,"answer":"get off at","form":"원형","example":"Tell the driver that you want to get off at the city hospital.","exampleTranslation":"기사님께 시립 병원에서 내리고 싶다고 말씀하세요.","sense":"~에서 내리다"},{"wordId":21400,"answer":"arrive early","form":"원형","example":"Guests should arrive early because the wedding starts exactly at noon.","exampleTranslation":"결혼식이 정확히 정오에 시작하니 하객들은 일찍 도착해야 한다.","sense":"일찍 도착하다"},{"wordId":21401,"answer":"level up","form":"원형","example":"My son plays every evening because he wants to level up before his friends.","exampleTranslation":"아들은 친구들보다 먼저 레벨을 올리고 싶어서 매일 저녁 게임을 한다.","sense":"레벨을 올리다"},{"wordId":21402,"answer":"respawning","form":"-ing형","example":"In this game, enemies keep respawning every few minutes, so you must move quickly.","exampleTranslation":"이 게임에서는 적들이 몇 분마다 계속 다시 나타나니 빨리 움직여야 한다.","sense":"다시 등장하다"},{"wordId":21403,"answer":"save point","form":"원형","example":"The battery died before my son reached a save point, so he lost everything.","exampleTranslation":"아들은 저장 지점에 닿기 전에 배터리가 나가서 전부 날렸다.","sense":"저장 지점"},{"wordId":21404,"answer":"side quest","form":"원형","example":"In this game, every side quest gives you a little more of the hero's story.","exampleTranslation":"이 게임에서는 부가 임무를 할 때마다 주인공의 이야기를 조금씩 더 알게 된다.","sense":"부가 임무"},{"wordId":21405,"answer":"main quest","form":"원형","example":"My daughter ignored the main quest and spent hours decorating her house in the game.","exampleTranslation":"딸은 주 임무는 제쳐 두고 게임 속 집을 꾸미는 데 몇 시간을 보냈다.","sense":"주 임무"},{"wordId":21406,"answer":"cutscenes","form":"복수형","example":"The cutscenes in this game look as good as a real movie.","exampleTranslation":"이 게임의 중간 영상은 진짜 영화만큼 멋지다.","sense":"중간 영상"},{"wordId":21407,"answer":"controllers","form":"복수형","example":"We bought two extra controllers so the whole family could play at the party.","exampleTranslation":"우리는 파티에서 온 가족이 함께 게임할 수 있도록 게임 컨트롤러를 두 개 더 샀다.","sense":"게임 컨트롤러"},{"wordId":21408,"answer":"game console","form":"원형","example":"My grandparents bought the kids a game console for the holidays.","exampleTranslation":"조부모님은 명절 선물로 아이들에게 게임기를 사 주셨다.","sense":"게임기"},{"wordId":21409,"answer":"multiplayer","form":"원형","example":"My son is not allowed to play multiplayer games with strangers online.","exampleTranslation":"아들은 온라인에서 낯선 사람과 여럿이 함께하는 게임을 하는 것이 허락되지 않는다.","sense":"여럿이 하는"},{"wordId":21410,"answer":"single-player","form":"원형","example":"This puzzle game has a single-player story mode for people who like to play alone.","exampleTranslation":"이 퍼즐 게임에는 혼자 즐기는 사람들을 위한 1인용 이야기 모드가 있다.","sense":"혼자 하는"},{"wordId":21411,"answer":"co-op mode","form":"원형","example":"We finished the hardest level together because co-op mode lets us share lives.","exampleTranslation":"협동 모드에서는 목숨을 나눠 쓸 수 있어서 우리는 가장 어려운 단계를 함께 깼다.","sense":"협동 모드"},{"wordId":21412,"answer":"matchmaking","form":"원형","example":"The new update made matchmaking faster, so players wait less before each game.","exampleTranslation":"새 업데이트로 매칭이 빨라져서 플레이어들은 게임마다 덜 기다린다.","sense":"상대 매칭"},{"wordId":21413,"answer":"ranked match","form":"원형","example":"My brother lost his first ranked match and practiced all weekend after that.","exampleTranslation":"형은 첫 순위전에서 진 뒤 주말 내내 연습했다.","sense":"순위 대전"},{"wordId":21414,"answer":"leaderboards","form":"복수형","example":"The running app has weekly leaderboards that show who ran the farthest.","exampleTranslation":"그 달리기 앱에는 누가 가장 멀리 달렸는지 보여 주는 주간 순위표가 있다.","sense":"순위표"},{"wordId":21415,"answer":"high score","form":"원형","example":"The old arcade machine at the pizza place still shows my high score from 2010.","exampleTranslation":"피자 가게에 있는 오래된 오락기에는 아직도 2010년의 내 최고 점수가 나와 있다.","sense":"최고 점수"},{"wordId":21416,"answer":"patch notes","form":"원형","example":"The patch notes say that the update fixes the problem with the sound.","exampleTranslation":"패치 노트에 따르면 이번 업데이트로 소리 문제가 해결된다.","sense":"패치 노트"},{"wordId":21417,"answer":"lag","form":"원형","example":"The video call had so much lag that my mom's voice came a second late.","exampleTranslation":"화상 통화에 지연이 너무 심해서 엄마 목소리가 일 초씩 늦게 들렸다.","sense":"지연 현상"},{"wordId":21418,"answer":"frame rate","form":"원형","example":"The new graphics card doubled the frame rate in my favorite racing game.","exampleTranslation":"새 그래픽 카드 덕분에 내가 좋아하는 레이싱 게임의 프레임 속도가 두 배가 됐다.","sense":"프레임 속도"},{"wordId":21419,"answer":"loading screen","form":"원형","example":"My little brother reads the jokes on the loading screen while he waits.","exampleTranslation":"남동생은 기다리는 동안 로딩 화면에 나오는 농담을 읽는다.","sense":"로딩 화면"},{"wordId":21420,"answer":"cheat code","form":"원형","example":"My dad still remembers a cheat code from a game he played as a boy.","exampleTranslation":"아빠는 어릴 때 하던 게임의 치트 코드를 아직도 기억하신다.","sense":"치트 코드"},{"wordId":21421,"answer":"walkthroughs","form":"복수형","example":"My son learned to read English faster by reading game walkthroughs online.","exampleTranslation":"아들은 인터넷에서 게임 공략을 읽으면서 영어를 더 빨리 읽게 되었다.","sense":"게임 공략"},{"wordId":21422,"answer":"difficulty setting","form":"원형","example":"My grandmother chose the easiest difficulty setting and still had a lot of fun.","exampleTranslation":"할머니는 가장 쉬운 난이도 설정을 고르셨는데도 아주 재미있어하셨다.","sense":"난이도 설정"},{"wordId":21423,"answer":"game over","form":"원형","example":"The cat jumped on the keyboard, and suddenly it was game over for me.","exampleTranslation":"고양이가 키보드 위로 뛰어오르는 바람에 갑자기 내 게임이 끝나 버렸다.","sense":"게임 끝"},{"wordId":21424,"answer":"extra life","form":"원형","example":"My son was so happy when he found an extra life hidden behind the waterfall.","exampleTranslation":"아들은 폭포 뒤에 숨겨진 추가 목숨을 찾고 무척 기뻐했다.","sense":"추가 목숨"},{"wordId":21425,"answer":"power-ups","form":"복수형","example":"In this racing game, you can collect power-ups that make your car faster.","exampleTranslation":"이 레이싱 게임에서는 차를 더 빠르게 해 주는 능력 강화 아이템을 모을 수 있다.","sense":"강화 아이템"},{"wordId":21426,"answer":"in-game purchase","form":"원형","example":"My son asked me before every in-game purchase, which made me proud.","exampleTranslation":"아들이 게임 내 구매를 할 때마다 내게 먼저 물어봐서 뿌듯했다.","sense":"게임 내 구매"},{"wordId":21427,"answer":"skins","form":"복수형","example":"My nephew spent all his birthday money on new skins for his favorite character.","exampleTranslation":"조카는 생일에 받은 돈을 전부 좋아하는 캐릭터의 새 외형 아이템에 썼다.","sense":"외형 아이템"},{"wordId":21428,"answer":"guilds","form":"복수형","example":"Many players join guilds so they can make friends and share tips.","exampleTranslation":"많은 플레이어들이 친구를 사귀고 요령을 나누려고 길드에 가입한다.","sense":"게임 내 모임"},{"wordId":21429,"answer":"noobs","form":"복수형","example":"This server is friendly to noobs, so it is a good place to start.","exampleTranslation":"이 서버는 초보자들에게 친절해서 처음 시작하기 좋은 곳이다.","sense":"초보자","alts":["novices"]},{"wordId":21430,"answer":"pro gamer","form":"원형","example":"My cousin trains eight hours a day because he wants to be a pro gamer.","exampleTranslation":"사촌은 프로게이머가 되고 싶어서 하루에 여덟 시간씩 연습한다.","sense":"프로게이머"},{"wordId":21431,"answer":"esports","form":"원형","example":"Some universities now give scholarships to students who are good at esports.","exampleTranslation":"요즘 일부 대학은 전자 스포츠를 잘하는 학생들에게 장학금을 준다.","sense":"전자 스포츠"},{"wordId":21432,"answer":"streamers","form":"복수형","example":"Many popular streamers started by playing games for just a few friends.","exampleTranslation":"인기 있는 방송인 상당수는 몇몇 친구들 앞에서 게임을 하는 것으로 시작했다.","sense":"방송인"},{"wordId":21433,"answer":"spectator mode","form":"원형","example":"After I lost the round, I watched the rest of the match in spectator mode.","exampleTranslation":"나는 그 판에서 진 뒤 남은 경기를 관전 모드로 지켜보았다.","sense":"관전 모드"},{"wordId":21434,"answer":"gaming chair","form":"원형","example":"My brother sits in his gaming chair even when he is studying for exams.","exampleTranslation":"형은 시험공부를 할 때도 게이밍 의자에 앉아 있다.","sense":"게이밍 의자"},{"wordId":21435,"answer":"rage quit","form":"원형","example":"My little sister is learning not to rage quit when she loses a card game.","exampleTranslation":"여동생은 카드 게임에서 져도 화가 나서 게임을 꺼 버리지 않는 법을 배우고 있다.","sense":"화나서 끄다"},{"wordId":21436,"answer":"good game","form":"원형","example":"At the end of the soccer match, the players shook hands and said good game.","exampleTranslation":"축구 경기가 끝나자 선수들은 악수하며 좋은 경기였다고 인사했다.","sense":"좋은 경기였어"},{"wordId":21437,"answer":"open world","form":"원형","example":"My son spends hours riding horses around the open world in his new game.","exampleTranslation":"아들은 새 게임의 넓은 세계를 말을 타고 돌아다니며 몇 시간을 보낸다.","sense":"오픈 월드"},{"wordId":21438,"answer":"puzzle game","form":"원형","example":"My grandfather plays a puzzle game on his tablet to keep his mind sharp.","exampleTranslation":"할아버지는 정신을 맑게 유지하려고 태블릿으로 퍼즐 게임을 하신다.","sense":"퍼즐 게임"},{"wordId":21439,"answer":"strategy game","form":"원형","example":"Our history teacher used a strategy game to teach us about ancient Rome.","exampleTranslation":"역사 선생님은 고대 로마에 대해 가르치려고 전략 게임을 활용하셨다.","sense":"전략 게임"},{"wordId":21440,"answer":"role-playing game","form":"원형","example":"My friends and I play a role-playing game with dice every Saturday night.","exampleTranslation":"친구들과 나는 매주 토요일 밤 주사위로 롤플레잉 게임을 한다.","sense":"역할 수행 게임"},{"wordId":21441,"answer":"beat the game","form":"원형","example":"My daughter stayed up late to beat the game before her friends did.","exampleTranslation":"딸은 친구들보다 먼저 게임을 끝까지 깨려고 늦게까지 깨어 있었다.","sense":"게임을 깨다"},{"wordId":21442,"answer":"speedruns","form":"복수형","example":"My son watches speedruns online to learn new tricks for his favorite game.","exampleTranslation":"아들은 좋아하는 게임의 새로운 요령을 배우려고 인터넷에서 최단 시간 클리어 영상을 본다.","sense":"최단 클리어"},{"wordId":21443,"answer":"replay value","form":"원형","example":"Games with many different endings usually have high replay value.","exampleTranslation":"결말이 여러 가지인 게임은 보통 다시 할 만한 가치가 높다.","sense":"다시 할 가치"},{"wordId":21444,"answer":"early access","form":"원형","example":"I paid for early access so I could try the new game before my friends.","exampleTranslation":"나는 친구들보다 먼저 새 게임을 해 보려고 앞서 해보기 비용을 냈다.","sense":"앞서 해보기"},{"wordId":21445,"answer":"server maintenance","form":"원형","example":"The bank app was down for server maintenance late last night.","exampleTranslation":"그 은행 앱은 어젯밤 늦게 서버 점검으로 접속이 안 됐다.","sense":"서버 점검"},{"wordId":21446,"answer":"split screen","form":"원형","example":"My kids like to race each other on a split screen after dinner.","exampleTranslation":"우리 아이들은 저녁을 먹은 뒤 화면을 나눠 서로 경주하는 것을 좋아한다.","sense":"화면 분할"},{"wordId":21447,"answer":"casual gamer","form":"원형","example":"My mom is a casual gamer who plays word games during her lunch break.","exampleTranslation":"엄마는 점심시간에 단어 게임을 하시는 가볍게 즐기는 게이머이다.","sense":"가벼운 게이머"},{"wordId":21448,"answer":"free-to-play","form":"원형","example":"My son only downloads free-to-play games because he has no money for apps.","exampleTranslation":"아들은 앱에 쓸 돈이 없어서 무료로 할 수 있는 게임만 내려받는다.","sense":"무료로 하는"},{"wordId":21449,"answer":"cross-play","form":"원형","example":"The new update added cross-play, so phone and computer players can finally meet.","exampleTranslation":"새 업데이트에 크로스 플레이가 추가되어 휴대폰과 컴퓨터 사용자가 드디어 함께할 수 있다.","sense":"크로스 플레이"},{"wordId":21450,"answer":"unlocking","form":"-ing형","example":"Unlocking every secret level in this game took my brother almost a year.","exampleTranslation":"형은 이 게임의 비밀 단계를 전부 해금하는 데 거의 1년이 걸렸다.","sense":"해금하다"},{"wordId":21451,"answer":"vacation day","form":"원형","example":"My boss let me take a vacation day for my daughter's school concert.","exampleTranslation":"사장님은 딸의 학교 음악회에 가라고 휴가를 하루 쓰게 해 주셨다.","sense":"휴가일"},{"wordId":21452,"answer":"annual leave","form":"원형","example":"Most workers in this company take their annual leave in August.","exampleTranslation":"이 회사 직원 대부분은 8월에 연차 휴가를 쓴다.","sense":"연차 휴가"},{"wordId":21453,"answer":"sick leave","form":"원형","example":"My coworker has been on sick leave since March because of a back injury.","exampleTranslation":"내 동료는 허리 부상 때문에 3월부터 병가 중이다.","sense":"병가"},{"wordId":21454,"answer":"day off","form":"원형","example":"On my day off, I like to sleep late and cook a big breakfast.","exampleTranslation":"쉬는 날에는 늦잠을 자고 아침을 푸짐하게 차려 먹는 것을 좋아한다.","sense":"쉬는 날"},{"wordId":21455,"answer":"time-off request","form":"원형","example":"My manager approved my time-off request for my sister's graduation.","exampleTranslation":"관리자가 여동생 졸업식에 가려고 낸 내 휴가 신청을 승인했다.","sense":"휴가 신청"},{"wordId":21456,"answer":"out-of-office message","form":"원형","example":"Her out-of-office message said she would return on the second of June.","exampleTranslation":"그녀의 부재중 자동 응답 메시지에는 6월 2일에 돌아온다고 적혀 있었다.","sense":"부재중 응답"},{"wordId":21457,"answer":"handovers","form":"복수형","example":"Shift handovers at the hospital happen at seven every morning and evening.","exampleTranslation":"그 병원의 근무 교대 인수인계는 매일 아침저녁 일곱 시에 이루어진다.","sense":"인수인계"},{"wordId":21458,"answer":"staycations","form":"복수형","example":"Many families chose staycations last summer because flights were so expensive.","exampleTranslation":"지난여름에는 항공권이 너무 비싸서 많은 가족이 집 근처에서 휴가를 보냈다.","sense":"집 근처 휴가"},{"wordId":21459,"answer":"use it or lose it","form":"원형","example":"My gym points work on a use it or lose it basis, so I visit often.","exampleTranslation":"내 헬스장 포인트는 안 쓰면 사라지는 방식이라서 나는 자주 간다.","sense":"안 쓰면 소멸"},{"wordId":21460,"answer":"blackout dates","form":"원형","example":"My airline miles have blackout dates around the New Year holiday.","exampleTranslation":"내 항공 마일리지는 새해 연휴 전후로 사용 불가 기간이 있다.","sense":"사용 불가 기간"},{"wordId":21461,"answer":"half day","form":"원형","example":"The school has a half day tomorrow, so the kids will be home by noon.","exampleTranslation":"내일은 학교가 반일 수업이라 아이들이 정오까지 집에 올 것이다.","sense":"반일"},{"wordId":21462,"answer":"workations","form":"복수형","example":"More companies now allow workations so employees can work from beautiful places.","exampleTranslation":"직원들이 아름다운 곳에서 일할 수 있도록 워케이션을 허용하는 회사가 늘고 있다.","sense":"워케이션"},{"wordId":21463,"answer":"vacation policy","form":"원형","example":"The hotel has a strict vacation policy for staff during the busy summer months.","exampleTranslation":"그 호텔은 바쁜 여름철에 직원들에게 엄격한 휴가 규정을 적용한다.","sense":"휴가 규정"},{"wordId":21464,"answer":"accrued","form":"과거형","example":"I accrued fifteen vacation days last year because I never took a break.","exampleTranslation":"나는 작년에 한 번도 쉬지 않아서 휴가가 15일 쌓였다.","sense":"적립되다"},{"wordId":21465,"answer":"paternity leave","form":"원형","example":"My brother spent his paternity leave learning how to give the baby a bath.","exampleTranslation":"형은 남성 출산 휴가 동안 아기를 목욕시키는 법을 배웠다.","sense":"남성 출산 휴가"},{"wordId":21466,"answer":"parental leave","form":"원형","example":"Both of my parents took parental leave when my little sister was born.","exampleTranslation":"여동생이 태어났을 때 부모님 두 분 모두 육아 휴직을 하셨다.","sense":"육아 휴직"},{"wordId":21467,"answer":"unpaid leave","form":"원형","example":"My cousin asked for unpaid leave to help at her family's restaurant.","exampleTranslation":"사촌은 가족이 운영하는 식당을 도우려고 무급 휴가를 신청했다.","sense":"무급 휴가"},{"wordId":21468,"answer":"leave of absence","form":"원형","example":"Our math teacher took a leave of absence to finish her studies abroad.","exampleTranslation":"우리 수학 선생님은 해외에서 학업을 마치려고 휴직하셨다.","sense":"휴직"},{"wordId":21469,"answer":"sabbaticals","form":"복수형","example":"Some universities give professors sabbaticals every seven years to do research.","exampleTranslation":"일부 대학은 교수들에게 7년마다 연구를 위한 안식 휴가를 준다.","sense":"안식 휴가"},{"wordId":21470,"answer":"return date","form":"원형","example":"Please write your return date on the form so the team knows when you are back.","exampleTranslation":"팀이 언제 복귀하는지 알 수 있도록 서류에 복귀일을 적어 주세요.","sense":"복귀일"},{"wordId":21471,"answer":"coverage plan","form":"원형","example":"Before the nurse went on vacation, she made a coverage plan for her patients.","exampleTranslation":"그 간호사는 휴가를 떠나기 전에 환자들을 위한 업무 대체 계획을 세웠다.","sense":"업무 대체 계획"},{"wordId":21472,"answer":"vacation balance","form":"원형","example":"My pay slip shows my vacation balance at the bottom of the page.","exampleTranslation":"내 급여 명세서 맨 아래에 남은 휴가 일수가 나와 있다.","sense":"남은 휴가"},{"wordId":21473,"answer":"comp day","form":"원형","example":"The nurses get a comp day after working on a public holiday.","exampleTranslation":"간호사들은 공휴일에 근무하면 대체 휴무일을 하루 받는다.","sense":"대체 휴무일"},{"wordId":21474,"answer":"reachable","form":"원형","example":"Our doctor is reachable by phone at night if a patient has a serious problem.","exampleTranslation":"우리 의사 선생님은 환자에게 심각한 문제가 생기면 밤에도 전화로 연락이 닿는다.","sense":"연락이 닿는"},{"wordId":21475,"answer":"off the grid","form":"원형","example":"My uncle lives off the grid on a farm with no phone or internet.","exampleTranslation":"삼촌은 전화도 인터넷도 없는 농장에서 외부와 단절된 채 산다.","sense":"외부와 단절된"},{"wordId":21476,"answer":"consecutive days","form":"원형","example":"It rained for twelve consecutive days, so the kids could not play outside.","exampleTranslation":"12일 연속으로 비가 와서 아이들은 밖에서 놀 수 없었다.","sense":"연속된 날"},{"wordId":21477,"answer":"team calendar","form":"원형","example":"Our coach shares the game dates on the team calendar at the start of the season.","exampleTranslation":"코치님은 시즌 초에 팀 일정표에 경기 날짜를 공유하신다.","sense":"팀 일정표"},{"wordId":21478,"answer":"manager approval","form":"원형","example":"Refunds over one hundred dollars need manager approval at this store.","exampleTranslation":"이 가게에서는 100달러가 넘는 환불을 하려면 관리자 승인이 필요하다.","sense":"관리자 승인"},{"wordId":21479,"answer":"holiday season","form":"원형","example":"The mall stays open until midnight during the holiday season.","exampleTranslation":"그 쇼핑몰은 연말연시에 자정까지 영업한다.","sense":"연말연시"},{"wordId":21480,"answer":"summer vacation","form":"원형","example":"The kids spent most of their summer vacation at their grandparents' farm.","exampleTranslation":"아이들은 여름 방학의 대부분을 조부모님 농장에서 보냈다.","sense":"여름 방학"},{"wordId":21481,"answer":"back at work","form":"원형","example":"My wife was back at work just two weeks after her surgery.","exampleTranslation":"아내는 수술을 받은 지 겨우 2주 만에 업무에 복귀했다.","sense":"업무에 복귀한"},{"wordId":21482,"answer":"catch up on emails","form":"원형","example":"I usually catch up on emails on the train before I get to the office.","exampleTranslation":"나는 보통 사무실에 도착하기 전에 기차에서 밀린 이메일을 처리한다.","sense":"이메일 처리하다"},{"wordId":21483,"answer":"point of contact","form":"원형","example":"For any questions about the wedding, my sister is the main point of contact.","exampleTranslation":"결혼식에 관해 궁금한 점이 있으면 언니가 주 연락 담당자이다.","sense":"연락 담당자"},{"wordId":21484,"answer":"take some time off","form":"원형","example":"After the baby was born, my brother decided to take some time off.","exampleTranslation":"아기가 태어난 뒤 형은 잠시 쉬기로 했다.","sense":"잠시 쉬다"},{"wordId":21485,"answer":"extend my vacation","form":"원형","example":"The weather was so nice in Hawaii that I wanted to extend my vacation.","exampleTranslation":"하와이 날씨가 너무 좋아서 나는 휴가를 연장하고 싶었다.","sense":"휴가 연장하다"},{"wordId":21486,"answer":"bridge holiday","form":"원형","example":"Many schools close on the bridge holiday, so families plan short trips.","exampleTranslation":"많은 학교가 징검다리 연휴에 쉬어서 가족들이 짧은 여행을 계획한다.","sense":"징검다리 연휴"},{"wordId":21487,"answer":"time zone difference","form":"원형","example":"Because of the time zone difference, I call my parents before I go to work.","exampleTranslation":"시차 때문에 나는 출근하기 전에 부모님께 전화를 드린다.","sense":"시차"},{"wordId":21488,"answer":"vacation photos","form":"원형","example":"My grandmother printed our vacation photos and put them in a big album.","exampleTranslation":"할머니는 우리 휴가 사진을 인화해서 큰 앨범에 넣으셨다.","sense":"휴가 사진"},{"wordId":21489,"answer":"souvenir for the office","form":"원형","example":"My coworker brought back a box of chocolates from Japan as a souvenir for the office.","exampleTranslation":"동료가 일본에서 사무실에 돌릴 기념품으로 초콜릿 한 상자를 사 왔다.","sense":"사무실 기념품"},{"wordId":21490,"answer":"recharge my batteries","form":"원형","example":"I spend one quiet weekend at the lake every year to recharge my batteries.","exampleTranslation":"나는 매년 기운을 회복하려고 호숫가에서 조용한 주말을 하루 보낸다.","sense":"기운 회복하다"},{"wordId":21491,"answer":"vacation pay","form":"원형","example":"Workers who leave the company still receive vacation pay for unused days.","exampleTranslation":"회사를 떠나는 직원도 쓰지 않은 휴가에 대한 휴가 수당을 받는다.","sense":"휴가 수당"},{"wordId":21492,"answer":"peak travel season","form":"원형","example":"Hotel rooms near the beach are hard to find during peak travel season.","exampleTranslation":"여행 성수기에는 해변 근처 호텔 방을 구하기 어렵다.","sense":"여행 성수기"},{"wordId":21493,"answer":"work email","form":"원형","example":"My boss asked me not to use my work email for personal shopping.","exampleTranslation":"사장님은 회사 이메일을 개인 쇼핑에 쓰지 말라고 하셨다.","sense":"회사 이메일"},{"wordId":21494,"answer":"approve my leave","form":"원형","example":"I sent the form early so my manager could approve my leave before the holidays.","exampleTranslation":"관리자가 연휴 전에 내 휴가를 승인할 수 있도록 서류를 일찍 보냈다.","sense":"휴가 승인하다"},{"wordId":21495,"answer":"year-end vacation","form":"원형","example":"The factory gives all workers a year-end vacation of one full week.","exampleTranslation":"그 공장은 모든 직원에게 꼬박 일주일의 연말 휴가를 준다.","sense":"연말 휴가"},{"wordId":21496,"answer":"vacation plans","form":"원형","example":"The storm ruined our vacation plans, so we stayed home and played board games.","exampleTranslation":"폭풍 때문에 휴가 계획이 엉망이 되어 우리는 집에서 보드게임을 했다.","sense":"휴가 계획"},{"wordId":21497,"answer":"leave request form","form":"원형","example":"New employees can find the leave request form on the company website.","exampleTranslation":"신입 사원은 회사 웹사이트에서 휴가 신청서를 찾을 수 있다.","sense":"휴가 신청서"},{"wordId":21498,"answer":"time off work","form":"원형","example":"My father took two weeks of time off work to paint our house.","exampleTranslation":"아버지는 우리 집을 칠하려고 2주 동안 일을 쉬셨다.","sense":"일 쉬는 기간"},{"wordId":21499,"answer":"holiday schedule","form":"원형","example":"The restaurant posted its holiday schedule on the front door last week.","exampleTranslation":"그 식당은 지난주 정문에 휴일 영업 일정을 붙여 두었다.","sense":"휴일 일정"},{"wordId":21500,"answer":"vacation mode","form":"원형","example":"My son switched into vacation mode the moment school ended for the summer.","exampleTranslation":"아들은 여름 방학이 시작되자마자 휴가 모드로 바뀌었다.","sense":"휴가 모드"},{"wordId":21501,"answer":"attend a meeting","form":"원형","example":"Parents are invited to attend a meeting about the school trip next Thursday.","exampleTranslation":"학부모들은 다음 주 목요일 수학여행 관련 회의에 참석해 달라는 초대를 받았다.","sense":"회의 참석하다"},{"wordId":21502,"answer":"submit a report","form":"원형","example":"All science groups must submit a report on their experiments by the end of the month.","exampleTranslation":"모든 과학 조는 이달 말까지 실험에 관한 보고서를 제출해야 한다.","sense":"보고서 제출하다"},{"wordId":21503,"answer":"apply for a job","form":"원형","example":"My cousin plans to apply for a job at the airport this summer.","exampleTranslation":"내 사촌은 이번 여름에 공항 일자리에 지원할 계획이다.","sense":"일자리에 지원하다"},{"wordId":21504,"answer":"get a promotion","form":"원형","example":"You will get a promotion if you keep working this hard.","exampleTranslation":"이렇게 계속 열심히 일하면 승진할 거야.","sense":"승진하다"},{"wordId":21505,"answer":"run late","form":"원형","example":"The doctor tends to run late on busy Monday mornings.","exampleTranslation":"그 의사는 바쁜 월요일 아침이면 진료가 늦어지는 편이다.","sense":"늦어지다"},{"wordId":21506,"answer":"set up a meeting","form":"원형","example":"I will set up a meeting with the landlord to discuss the repairs.","exampleTranslation":"수리 문제를 의논하려고 집주인과 만날 약속을 잡을게요.","sense":"회의 일정을 잡다"},{"wordId":21507,"answer":"reply to an email","form":"원형","example":"It only takes a minute to reply to an email from a customer.","exampleTranslation":"고객이 보낸 이메일에 답장하는 데는 일 분이면 된다.","sense":"이메일에 답장하다"},{"wordId":21508,"answer":"make a phone call","form":"원형","example":"Can I borrow your phone to make a phone call to my mom?","exampleTranslation":"엄마한테 전화 좀 걸게 휴대폰 좀 빌려줄래?","sense":"전화를 걸다"},{"wordId":21509,"answer":"job interview","form":"원형","example":"My sister was so nervous before her first job interview yesterday.","exampleTranslation":"언니는 어제 첫 취업 면접 전에 무척 긴장했다.","sense":"취업 면접"},{"wordId":21510,"answer":"business trip","form":"원형","example":"I always pack light when I go on a business trip.","exampleTranslation":"나는 출장 갈 때 항상 짐을 가볍게 싼다.","sense":"출장"},{"wordId":21511,"answer":"team leader","form":"원형","example":"The new team leader bought donuts for everyone on her first day.","exampleTranslation":"새 팀장은 첫날 모두에게 도넛을 사 왔다.","sense":"팀장"},{"wordId":21512,"answer":"working hours","form":"원형","example":"Please do not call me about personal matters during working hours.","exampleTranslation":"근무 시간에는 개인적인 일로 전화하지 말아 주세요.","sense":"근무 시간"},{"wordId":21513,"answer":"team member","form":"원형","example":"Each team member will get a free ticket to the company picnic.","exampleTranslation":"팀원 한 명 한 명이 회사 야유회 무료 입장권을 받게 된다.","sense":"팀원"},{"wordId":21514,"answer":"meet expectations","form":"원형","example":"I hope the new chef can meet expectations after the last one left.","exampleTranslation":"전 셰프가 떠난 뒤로 새 셰프가 기대에 부응할 수 있으면 좋겠다.","sense":"기대에 부응하다"},{"wordId":21515,"answer":"finish work","form":"원형","example":"Call me when you finish work, and we can grab dinner together.","exampleTranslation":"일 끝나면 전화해, 같이 저녁 먹자.","sense":"퇴근하다"},{"wordId":21516,"answer":"start work","form":"원형","example":"Nurses on the night shift start work at ten in the evening.","exampleTranslation":"야간 근무 간호사들은 밤 열 시에 일을 시작한다.","sense":"출근하다"},{"wordId":21517,"answer":"quit your job","form":"원형","example":"Do not quit your job until you have saved enough money for the trip.","exampleTranslation":"여행 갈 돈을 충분히 모으기 전까지는 일을 그만두지 마.","sense":"일을 그만두다"},{"wordId":21518,"answer":"full-time job","form":"원형","example":"Finding a full-time job in this small town is not easy.","exampleTranslation":"이 작은 마을에서 정규직 일자리를 찾는 건 쉽지 않다.","sense":"정규직 일자리"},{"wordId":21519,"answer":"part-time job","form":"원형","example":"My son wants a part-time job at the movie theater this summer.","exampleTranslation":"우리 아들은 이번 여름에 영화관에서 아르바이트를 하고 싶어 한다.","sense":"아르바이트"},{"wordId":21520,"answer":"sign a contract","form":"원형","example":"Our landlord asked us to sign a contract for another two years.","exampleTranslation":"집주인이 우리에게 이 년 더 계약서에 서명해 달라고 했다.","sense":"계약서에 서명하다"},{"wordId":21521,"answer":"make a suggestion","form":"원형","example":"May I make a suggestion about where we should eat tonight?","exampleTranslation":"오늘 저녁에 어디서 먹을지 제안 하나 해도 될까요?","sense":"제안하다"},{"wordId":21522,"answer":"share your ideas","form":"원형","example":"In this class, I want you to share your ideas without fear.","exampleTranslation":"이 수업에서는 여러분이 두려움 없이 생각을 나눴으면 좋겠어요.","sense":"생각을 나누다"},{"wordId":21523,"answer":"work from home","form":"원형","example":"I work from home on Tuesdays, so I can walk the dog at noon.","exampleTranslation":"나는 화요일마다 재택근무를 해서 정오에 개를 산책시킬 수 있다.","sense":"재택근무하다"},{"wordId":21524,"answer":"meet a client","form":"원형","example":"He wore his best suit to meet a client at the hotel lobby.","exampleTranslation":"그는 호텔 로비에서 고객을 만나려고 가장 좋은 정장을 입었다.","sense":"고객을 만나다"},{"wordId":21525,"answer":"close a deal","form":"원형","example":"If we lower the price a little, we can close a deal today.","exampleTranslation":"가격을 조금 낮추면 오늘 거래를 성사시킬 수 있다.","sense":"거래를 성사시키다"},{"wordId":21526,"answer":"staff meeting","form":"원형","example":"The manager announced the new vacation rules at the staff meeting.","exampleTranslation":"매니저가 직원회의에서 새 휴가 규정을 발표했다.","sense":"직원회의"},{"wordId":21527,"answer":"busy season","form":"원형","example":"The ski shop hires extra workers before the busy season begins.","exampleTranslation":"그 스키 가게는 성수기가 시작되기 전에 일손을 더 뽑는다.","sense":"성수기"},{"wordId":21528,"answer":"miss a deadline","form":"원형","example":"Students who miss a deadline lose ten points on the assignment.","exampleTranslation":"마감을 놓친 학생은 과제 점수에서 십 점이 깎인다.","sense":"마감을 놓치다"},{"wordId":21529,"answer":"make a list","form":"원형","example":"Let us make a list of everything we need for the camping trip.","exampleTranslation":"캠핑 여행에 필요한 걸 전부 목록으로 만들자.","sense":"목록을 만들다"},{"wordId":21530,"answer":"check your email","form":"원형","example":"You should check your email for the hotel booking confirmation.","exampleTranslation":"호텔 예약 확인 메일이 왔는지 이메일을 확인해 봐.","sense":"이메일을 확인하다"},{"wordId":21531,"answer":"print a copy","form":"원형","example":"Please print a copy of your ticket before you go to the airport.","exampleTranslation":"공항에 가기 전에 항공권 사본을 한 부 인쇄해 주세요.","sense":"사본을 인쇄하다"},{"wordId":21532,"answer":"on schedule","form":"원형","example":"Despite the snow, our flight to Chicago left right on schedule.","exampleTranslation":"눈이 왔는데도 시카고행 비행기는 정확히 예정대로 출발했다.","sense":"예정대로"},{"wordId":21533,"answer":"at work","form":"원형","example":"My dad hurt his back at work while lifting heavy boxes.","exampleTranslation":"아빠는 직장에서 무거운 상자를 들다가 허리를 다치셨다.","sense":"직장에서"},{"wordId":21534,"answer":"on business","form":"원형","example":"My uncle flew to Singapore on business for three days.","exampleTranslation":"삼촌은 업무차 사흘 동안 싱가포르에 다녀오셨다.","sense":"업무차"},{"wordId":21535,"answer":"attend a conference","form":"원형","example":"Teachers from every school will attend a conference on online learning.","exampleTranslation":"모든 학교의 선생님들이 온라인 학습에 관한 콘퍼런스에 참석할 것이다.","sense":"콘퍼런스에 참석하다"},{"wordId":21536,"answer":"hire new staff","form":"원형","example":"The hospital needs to hire new staff for the night shift.","exampleTranslation":"그 병원은 야간 근무를 맡을 새 직원을 채용해야 한다.","sense":"새 직원을 채용하다"},{"wordId":21537,"answer":"meet the requirements","form":"원형","example":"Sadly, my old car did not meet the requirements for the safety test.","exampleTranslation":"안타깝게도 내 낡은 차는 안전 검사 요건을 충족하지 못했다.","sense":"요건을 충족하다"},{"wordId":21538,"answer":"give feedback","form":"원형","example":"The coach will give feedback to each player after the game.","exampleTranslation":"코치는 경기가 끝난 뒤 선수 한 명 한 명에게 피드백을 줄 것이다.","sense":"피드백을 주다"},{"wordId":21539,"answer":"receive feedback","form":"원형","example":"New drivers often receive feedback from their instructor after each lesson.","exampleTranslation":"초보 운전자들은 매 수업 후에 강사에게 피드백을 받곤 한다.","sense":"피드백을 받다"},{"wordId":21540,"answer":"ask a question","form":"원형","example":"Excuse me, can I ask a question about the museum hours?","exampleTranslation":"실례지만 박물관 운영 시간에 대해 질문해도 될까요?","sense":"질문하다"},{"wordId":21541,"answer":"gather information","form":"원형","example":"Before our trip to Peru, we tried to gather information about the weather.","exampleTranslation":"페루 여행 전에 우리는 날씨에 대한 정보를 모으려고 했다.","sense":"정보를 모으다"},{"wordId":21542,"answer":"express an opinion","form":"원형","example":"In my family, even the youngest child can express an opinion at dinner.","exampleTranslation":"우리 가족은 저녁 식사 때 막내도 의견을 말할 수 있다.","sense":"의견을 말하다"},{"wordId":21543,"answer":"weekly meeting","form":"원형","example":"The boss canceled the weekly meeting because half the team was sick.","exampleTranslation":"팀원 절반이 아파서 사장님이 주간 회의를 취소했다.","sense":"주간 회의"},{"wordId":21544,"answer":"answer the phone","form":"원형","example":"Nobody was home to answer the phone when the delivery driver called.","exampleTranslation":"택배 기사가 전화했을 때 집에 전화를 받을 사람이 아무도 없었다.","sense":"전화를 받다"},{"wordId":21545,"answer":"take a risk","form":"원형","example":"I decided to take a risk and move to a new city alone.","exampleTranslation":"나는 위험을 감수하고 혼자 새 도시로 이사하기로 했다.","sense":"위험을 감수하다"},{"wordId":21546,"answer":"make a choice","form":"원형","example":"The menu is so long that I cannot make a choice.","exampleTranslation":"메뉴가 너무 길어서 뭘 골라야 할지 모르겠다.","sense":"선택하다"},{"wordId":21547,"answer":"make an offer","form":"원형","example":"I really like this used car, so I want to make an offer today.","exampleTranslation":"이 중고차가 정말 마음에 들어서 오늘 가격을 제시하고 싶다.","sense":"가격을 제시하다"},{"wordId":21548,"answer":"make a profit","form":"원형","example":"Our school bake sale needs to make a profit for the class trip.","exampleTranslation":"우리 학교 빵 바자회는 수학여행 비용을 위해 이익을 내야 한다.","sense":"이익을 내다"},{"wordId":21549,"answer":"ask for help","form":"원형","example":"It is okay to ask for help when you are lost in a new city.","exampleTranslation":"낯선 도시에서 길을 잃으면 도움을 청해도 괜찮다.","sense":"도움을 청하다"},{"wordId":21550,"answer":"work hard","form":"원형","example":"Farmers work hard in the fields from early morning until sunset.","exampleTranslation":"농부들은 이른 아침부터 해 질 녘까지 밭에서 열심히 일한다.","sense":"열심히 일하다"},{"wordId":21551,"answer":"vacuum the floor","form":"원형","example":"My roommate and I take turns to vacuum the floor every Saturday.","exampleTranslation":"룸메이트와 나는 토요일마다 번갈아 바닥을 청소기로 민다.","sense":"청소기로 밀다"},{"wordId":21552,"answer":"feed the cat","form":"원형","example":"My neighbor will feed the cat while we are on vacation.","exampleTranslation":"우리가 휴가 간 동안 이웃이 고양이 밥을 줄 것이다.","sense":"고양이 밥을 주다"},{"wordId":21553,"answer":"cook dinner","form":"원형","example":"My brother learned to cook dinner by watching videos online.","exampleTranslation":"우리 오빠는 온라인 영상을 보며 저녁 요리하는 법을 배웠다.","sense":"저녁을 요리하다"},{"wordId":21554,"answer":"brush your teeth","form":"원형","example":"Kids, please brush your teeth right after you finish your candy.","exampleTranslation":"얘들아, 사탕 다 먹으면 바로 이 닦으렴.","sense":"이를 닦다"},{"wordId":21555,"answer":"wash your hands","form":"원형","example":"Remember to wash your hands after you play with the dog.","exampleTranslation":"강아지랑 놀고 나면 손 씻는 거 잊지 마.","sense":"손을 씻다"},{"wordId":21556,"answer":"get dressed","form":"원형","example":"Hurry up and get dressed, or we will miss the school bus.","exampleTranslation":"서둘러 옷 입어, 안 그러면 통학 버스 놓친다.","sense":"옷을 입다"},{"wordId":21557,"answer":"get up early","form":"원형","example":"We need to get up early tomorrow to catch the sunrise at the beach.","exampleTranslation":"내일 해변에서 일출을 보려면 일찍 일어나야 한다.","sense":"일찍 일어나다"},{"wordId":21558,"answer":"go to bed","form":"원형","example":"I was so tired after the hike that I wanted to go to bed at eight.","exampleTranslation":"등산 후에 너무 피곤해서 여덟 시에 잠자리에 들고 싶었다.","sense":"잠자리에 들다"},{"wordId":21559,"answer":"stay up late","form":"원형","example":"Teenagers often stay up late playing games on their phones.","exampleTranslation":"십 대들은 휴대폰으로 게임을 하느라 늦게까지 깨어 있는 경우가 많다.","sense":"늦게까지 깨어 있다"},{"wordId":21560,"answer":"take a bath","form":"원형","example":"My grandmother likes to take a bath with warm water and lavender oil.","exampleTranslation":"할머니는 따뜻한 물에 라벤더 오일을 넣고 목욕하는 걸 좋아하신다.","sense":"목욕하다"},{"wordId":21561,"answer":"pay the rent","form":"원형","example":"My roommate lost his job, so I helped him pay the rent this month.","exampleTranslation":"룸메이트가 일자리를 잃어서 이번 달 월세 내는 걸 도와줬다.","sense":"월세를 내다"},{"wordId":21562,"answer":"leaky faucet","form":"원형","example":"The plumber came this morning to fix the leaky faucet in the bathroom.","exampleTranslation":"오늘 아침 배관공이 와서 욕실의 물이 새는 수도꼭지를 고쳤다.","sense":"물이 새는 수도꼭지"},{"wordId":21563,"answer":"turn off the lights","form":"원형","example":"Can you turn off the lights in the hallway before you sleep?","exampleTranslation":"자기 전에 복도 불 좀 꺼 줄래?","sense":"불을 끄다"},{"wordId":21564,"answer":"lock the door","form":"원형","example":"Always lock the door of your car when you park downtown.","exampleTranslation":"시내에 주차할 때는 항상 차 문을 잠가라.","sense":"문을 잠그다"},{"wordId":21565,"answer":"messy room","form":"원형","example":"I cannot find my keys anywhere in this messy room.","exampleTranslation":"이 지저분한 방에서는 열쇠를 도무지 못 찾겠다.","sense":"지저분한 방"},{"wordId":21566,"answer":"living room","form":"원형","example":"We bought a new sofa for the living room last weekend.","exampleTranslation":"우리는 지난 주말에 거실에 둘 새 소파를 샀다.","sense":"거실"},{"wordId":21567,"answer":"front door","form":"원형","example":"The delivery driver left the package by the front door this morning.","exampleTranslation":"택배 기사가 오늘 아침 현관문 옆에 소포를 두고 갔다.","sense":"현관문"},{"wordId":21568,"answer":"eat leftovers","form":"원형","example":"I do not mind if we eat leftovers from the party tonight.","exampleTranslation":"오늘 저녁에 파티 때 남은 음식을 먹어도 난 괜찮아.","sense":"남은 음식을 먹다"},{"wordId":21569,"answer":"boil water","form":"원형","example":"At the campsite, we had to boil water over the fire to drink it.","exampleTranslation":"야영지에서 우리는 마실 물을 불에 끓여야 했다.","sense":"물을 끓이다"},{"wordId":21570,"answer":"order takeout","form":"원형","example":"The office workers decided to order takeout for the late meeting.","exampleTranslation":"직원들은 늦은 회의를 위해 포장 음식을 주문하기로 했다.","sense":"포장 음식을 주문하다"},{"wordId":21571,"answer":"paint the walls","form":"원형","example":"My kids want to paint the walls of their bedroom bright yellow.","exampleTranslation":"우리 아이들은 자기 방 벽을 밝은 노란색으로 칠하고 싶어 한다.","sense":"벽을 칠하다"},{"wordId":21572,"answer":"family dinner","form":"원형","example":"My grandfather told funny stories at the family dinner last night.","exampleTranslation":"할아버지가 어젯밤 가족 저녁 식사에서 재미있는 이야기를 해 주셨다.","sense":"가족 저녁 식사"},{"wordId":21573,"answer":"running water","form":"원형","example":"Rinse the vegetables under running water before you cut them.","exampleTranslation":"채소를 썰기 전에 흐르는 물에 헹궈라.","sense":"흐르는 물"},{"wordId":21574,"answer":"unpack your bags","form":"원형","example":"You can unpack your bags later, but first come and eat dinner.","exampleTranslation":"짐은 나중에 풀어도 되니까 우선 와서 저녁 먹어.","sense":"짐을 풀다"},{"wordId":21575,"answer":"pack a lunch","form":"원형","example":"On hiking days, I pack a lunch with sandwiches and fruit.","exampleTranslation":"등산 가는 날에는 샌드위치와 과일로 도시락을 싼다.","sense":"도시락을 싸다"},{"wordId":21576,"answer":"do some cleaning","form":"원형","example":"We should do some cleaning in the garage this weekend.","exampleTranslation":"이번 주말에 차고 청소를 좀 해야겠다.","sense":"청소를 좀 하다"},{"wordId":21577,"answer":"make a mess","form":"원형","example":"Puppies always make a mess when they are left alone at home.","exampleTranslation":"강아지들은 집에 혼자 남겨지면 늘 집을 어지른다.","sense":"어지르다"},{"wordId":21578,"answer":"make coffee","form":"원형","example":"Can you make coffee for our guests while I set the table?","exampleTranslation":"내가 상을 차리는 동안 손님들 드릴 커피 좀 내려 줄래?","sense":"커피를 내리다"},{"wordId":21579,"answer":"make breakfast","form":"원형","example":"I will make breakfast tomorrow so you can sleep a little longer.","exampleTranslation":"내일은 내가 아침을 차릴 테니 조금 더 자.","sense":"아침을 차리다"},{"wordId":21580,"answer":"have dinner","form":"원형","example":"Would you like to have dinner with us after the concert?","exampleTranslation":"콘서트 끝나고 우리랑 저녁 먹을래요?","sense":"저녁을 먹다"},{"wordId":21581,"answer":"have a snack","form":"원형","example":"I usually have a snack at three to keep my energy up at work.","exampleTranslation":"나는 회사에서 기운을 유지하려고 보통 세 시에 간식을 먹는다.","sense":"간식을 먹다"},{"wordId":21582,"answer":"order a pizza","form":"원형","example":"After the game, the whole team wanted to order a pizza together.","exampleTranslation":"경기가 끝난 뒤 팀 전체가 함께 피자를 주문하고 싶어 했다.","sense":"피자를 주문하다"},{"wordId":21583,"answer":"watch TV","form":"원형","example":"On rainy days, the kids are allowed to watch TV for one hour.","exampleTranslation":"비 오는 날에는 아이들이 한 시간 동안 텔레비전을 볼 수 있다.","sense":"텔레비전을 보다"},{"wordId":21584,"answer":"listen to music","form":"원형","example":"Many students listen to music to stay focused while they study.","exampleTranslation":"많은 학생들이 공부하는 동안 집중하려고 음악을 듣는다.","sense":"음악을 듣다"},{"wordId":21585,"answer":"make a noise","form":"원형","example":"The baby is sleeping, so please do not make a noise.","exampleTranslation":"아기가 자고 있으니 소리 내지 말아 주세요.","sense":"소리를 내다"},{"wordId":21586,"answer":"spend the weekend","form":"원형","example":"My friends and I want to spend the weekend camping by the lake.","exampleTranslation":"친구들과 나는 호숫가에서 캠핑하며 주말을 보내고 싶다.","sense":"주말을 보내다"},{"wordId":21587,"answer":"family member","form":"원형","example":"In our house, each family member washes his or her own dishes.","exampleTranslation":"우리 집에서는 가족 구성원이 각자 자기 설거지를 한다.","sense":"가족 구성원"},{"wordId":21588,"answer":"older sister","form":"원형","example":"Her older sister lent her a dress for the school dance.","exampleTranslation":"그녀의 언니가 학교 댄스파티에 입을 드레스를 빌려주었다.","sense":"언니"},{"wordId":21589,"answer":"younger brother","form":"원형","example":"My younger brother just started his first year of high school.","exampleTranslation":"내 남동생은 이제 막 고등학교 일 학년을 시작했다.","sense":"남동생"},{"wordId":21590,"answer":"raise children","form":"원형","example":"My parents worked full-time and still found time to raise children.","exampleTranslation":"부모님은 전일제로 일하시면서도 아이들을 키울 시간을 내셨다.","sense":"아이를 키우다"},{"wordId":21591,"answer":"convenience store","form":"원형","example":"I bought a bottle of water at the convenience store near the station.","exampleTranslation":"역 근처 편의점에서 물 한 병을 샀다.","sense":"편의점"},{"wordId":21592,"answer":"grocery store","form":"원형","example":"The grocery store on Main Street closes early on Sundays.","exampleTranslation":"메인 스트리트에 있는 식료품점은 일요일에 일찍 문을 닫는다.","sense":"식료품점"},{"wordId":21593,"answer":"next door","form":"원형","example":"The family next door has a big dog that barks all night.","exampleTranslation":"옆집 가족은 밤새 짖는 큰 개를 키운다.","sense":"옆집에"},{"wordId":21594,"answer":"take the stairs","form":"원형","example":"The elevator is broken, so we have to take the stairs today.","exampleTranslation":"엘리베이터가 고장 나서 오늘은 계단으로 가야 한다.","sense":"계단으로 가다"},{"wordId":21595,"answer":"make tea","form":"원형","example":"My grandmother loves to make tea with fresh mint from her garden.","exampleTranslation":"할머니는 정원에서 딴 신선한 박하로 차를 끓이는 걸 좋아하신다.","sense":"차를 끓이다"},{"wordId":21596,"answer":"read a book","form":"원형","example":"On long train rides, I always read a book instead of using my phone.","exampleTranslation":"긴 기차 여행 때는 휴대폰 대신 항상 책을 읽는다.","sense":"책을 읽다"},{"wordId":21597,"answer":"play games","form":"원형","example":"At the party, the children wanted to play games in the backyard.","exampleTranslation":"파티에서 아이들은 뒷마당에서 게임을 하고 싶어 했다.","sense":"게임을 하다"},{"wordId":21598,"answer":"spend the night","form":"원형","example":"The storm was so bad that we had to spend the night at the airport.","exampleTranslation":"폭풍이 너무 심해서 우리는 공항에서 하룻밤을 묵어야 했다.","sense":"하룻밤 묵다"},{"wordId":21599,"answer":"make a sandwich","form":"원형","example":"Can you make a sandwich for me while I finish packing?","exampleTranslation":"내가 짐 다 싸는 동안 샌드위치 하나 만들어 줄래?","sense":"샌드위치를 만들다"},{"wordId":21600,"answer":"have lunch","form":"원형","example":"We usually have lunch in the park when the weather is nice.","exampleTranslation":"날씨가 좋으면 우리는 보통 공원에서 점심을 먹는다.","sense":"점심을 먹다"},{"wordId":21601,"answer":"catch the flu","form":"원형","example":"Wash your hands often so you do not catch the flu this winter.","exampleTranslation":"이번 겨울에 독감에 걸리지 않도록 손을 자주 씻어라.","sense":"독감에 걸리다"},{"wordId":21602,"answer":"sore throat","form":"원형","example":"The singer canceled her concert because of a sore throat.","exampleTranslation":"그 가수는 인후통 때문에 콘서트를 취소했다.","sense":"인후통"},{"wordId":21603,"answer":"runny nose","form":"원형","example":"I keep sneezing and have a runny nose because of the dust.","exampleTranslation":"먼지 때문에 계속 재채기가 나고 콧물이 흐른다.","sense":"콧물"},{"wordId":21604,"answer":"see a doctor","form":"원형","example":"My grandfather finally agreed to see a doctor about his cough.","exampleTranslation":"할아버지는 마침내 기침 때문에 진찰을 받기로 하셨다.","sense":"진찰을 받다"},{"wordId":21605,"answer":"get some exercise","form":"원형","example":"After work, I walk to the park to get some exercise.","exampleTranslation":"퇴근 후에 나는 운동을 좀 하려고 공원까지 걸어간다.","sense":"운동을 좀 하다"},{"wordId":21606,"answer":"stay healthy","form":"원형","example":"My grandmother swims every morning to stay healthy at eighty.","exampleTranslation":"할머니는 여든의 나이에도 건강을 유지하려고 매일 아침 수영을 하신다.","sense":"건강을 유지하다"},{"wordId":21607,"answer":"lose your appetite","form":"원형","example":"If you lose your appetite for more than a week, call the clinic.","exampleTranslation":"일주일 넘게 입맛이 없으면 병원에 전화해라.","sense":"입맛을 잃다"},{"wordId":21608,"answer":"go on a diet","form":"원형","example":"My dad decided to go on a diet after his doctor's visit.","exampleTranslation":"아빠는 병원에 다녀오신 뒤 다이어트를 시작하기로 하셨다.","sense":"다이어트를 시작하다"},{"wordId":21609,"answer":"feel dizzy","form":"원형","example":"Some passengers feel dizzy on the boat when the sea is rough.","exampleTranslation":"바다가 거칠면 배에서 어지러움을 느끼는 승객들이 있다.","sense":"어지럽다"},{"wordId":21610,"answer":"side effects","form":"원형","example":"Ask the pharmacist about any side effects before you take the pills.","exampleTranslation":"약을 먹기 전에 약사에게 부작용이 있는지 물어봐라.","sense":"부작용"},{"wordId":21611,"answer":"medical checkup","form":"원형","example":"The company pays for a free medical checkup for all employees.","exampleTranslation":"회사는 전 직원의 무료 건강 검진 비용을 낸다.","sense":"건강 검진"},{"wordId":21612,"answer":"sprain your ankle","form":"원형","example":"Wear good shoes so you do not sprain your ankle on the trail.","exampleTranslation":"산길에서 발목을 삐지 않도록 좋은 신발을 신어라.","sense":"발목을 삐다"},{"wordId":21613,"answer":"upset stomach","form":"원형","example":"My son stayed home from school with an upset stomach.","exampleTranslation":"아들이 배탈이 나서 학교에 가지 않고 집에 있었다.","sense":"배탈"},{"wordId":21614,"answer":"feel full","form":"원형","example":"Eat slowly, and you will feel full with less food.","exampleTranslation":"천천히 먹으면 더 적게 먹어도 배부를 거야.","sense":"배부르다"},{"wordId":21615,"answer":"junk food","form":"원형","example":"The school stopped selling junk food in the cafeteria this year.","exampleTranslation":"그 학교는 올해부터 구내식당에서 불량 식품을 팔지 않는다.","sense":"불량 식품"},{"wordId":21616,"answer":"healthy lifestyle","form":"원형","example":"My doctor says a healthy lifestyle is better than any medicine.","exampleTranslation":"의사 선생님은 건강한 생활 방식이 어떤 약보다 낫다고 하신다.","sense":"건강한 생활 방식"},{"wordId":21617,"answer":"go for a run","form":"원형","example":"If the rain stops, I will go for a run along the river.","exampleTranslation":"비가 그치면 강을 따라 달리러 나갈 거야.","sense":"달리러 나가다"},{"wordId":21618,"answer":"take vitamins","form":"원형","example":"My doctor told me to take vitamins during the dark winter months.","exampleTranslation":"의사가 나에게 해가 짧은 겨울철에는 비타민을 먹으라고 했다.","sense":"비타민을 먹다"},{"wordId":21619,"answer":"pull a muscle","form":"원형","example":"Lift the heavy box slowly, or you might pull a muscle.","exampleTranslation":"무거운 상자는 천천히 들어, 안 그러면 근육이 결릴 수도 있어.","sense":"근육을 다치다"},{"wordId":21620,"answer":"back pain","form":"원형","example":"My mom has back pain after working in the garden all day.","exampleTranslation":"엄마는 하루 종일 정원 일을 하신 뒤 허리 통증이 있으시다.","sense":"허리 통증"},{"wordId":21621,"answer":"empty stomach","form":"원형","example":"Drinking coffee on an empty stomach makes me feel shaky.","exampleTranslation":"빈속에 커피를 마시면 몸이 떨린다.","sense":"빈속"},{"wordId":21622,"answer":"eat healthy","form":"원형","example":"My roommate and I cook at home so we can eat healthy.","exampleTranslation":"룸메이트와 나는 건강하게 먹으려고 집에서 요리한다.","sense":"건강하게 먹다"},{"wordId":21623,"answer":"emergency room","form":"원형","example":"The ambulance took the injured biker straight to the emergency room.","exampleTranslation":"구급차가 다친 자전거 운전자를 곧장 응급실로 데려갔다.","sense":"응급실"},{"wordId":21624,"answer":"fill a prescription","form":"원형","example":"I stopped at the drugstore to fill a prescription for my daughter.","exampleTranslation":"딸의 처방약을 조제받으려고 약국에 들렀다.","sense":"처방약을 조제받다"},{"wordId":21625,"answer":"get a shot","form":"원형","example":"Before the trip to Africa, we had to get a shot for yellow fever.","exampleTranslation":"아프리카 여행 전에 우리는 황열병 주사를 맞아야 했다.","sense":"주사를 맞다"},{"wordId":21626,"answer":"feel sick","form":"원형","example":"I always feel sick when I read in the back seat of a car.","exampleTranslation":"나는 차 뒷좌석에서 책을 읽으면 항상 속이 메스껍다.","sense":"속이 메스껍다"},{"wordId":21627,"answer":"mild symptoms","form":"원형","example":"The nurse said my son only has mild symptoms, so he can rest at home.","exampleTranslation":"간호사는 아들이 가벼운 증상만 있어서 집에서 쉬면 된다고 했다.","sense":"가벼운 증상"},{"wordId":21628,"answer":"regular exercise","form":"원형","example":"My grandfather says regular exercise keeps his mind sharp.","exampleTranslation":"할아버지는 규칙적인 운동이 정신을 맑게 해 준다고 하신다.","sense":"규칙적인 운동"},{"wordId":21629,"answer":"drink plenty of water","form":"원형","example":"On hot days at the beach, you should drink plenty of water.","exampleTranslation":"더운 날 해변에서는 물을 충분히 마셔야 한다.","sense":"물을 충분히 마시다"},{"wordId":21630,"answer":"watch your weight","form":"원형","example":"You do not need to watch your weight during the holidays, so enjoy the cake.","exampleTranslation":"명절 동안에는 체중 관리 안 해도 되니까 케이크 맛있게 먹어.","sense":"체중을 관리하다"},{"wordId":21631,"answer":"home remedy","form":"원형","example":"My grandmother has a home remedy for every small health problem.","exampleTranslation":"할머니는 사소한 건강 문제마다 쓰시는 민간요법이 있다.","sense":"민간요법"},{"wordId":21632,"answer":"hurt your back","form":"원형","example":"Do not try to move the sofa alone, or you will hurt your back.","exampleTranslation":"소파를 혼자 옮기려고 하지 마, 그러다 허리 다친다.","sense":"허리를 다치다"},{"wordId":21633,"answer":"chronic pain","form":"원형","example":"Gentle yoga helps my aunt manage her chronic pain.","exampleTranslation":"부드러운 요가가 이모의 만성 통증 관리에 도움이 된다.","sense":"만성 통증"},{"wordId":21634,"answer":"heart rate","form":"원형","example":"The nurse checked my heart rate before the blood test.","exampleTranslation":"간호사가 피 검사 전에 내 심박수를 쟀다.","sense":"심박수"},{"wordId":21635,"answer":"cut down on sugar","form":"원형","example":"My doctor told me to cut down on sugar and drink more water.","exampleTranslation":"의사가 나에게 설탕 섭취를 줄이고 물을 더 마시라고 했다.","sense":"설탕 섭취를 줄이다"},{"wordId":21636,"answer":"low-fat milk","form":"원형","example":"Could you pick up a carton of low-fat milk at the store?","exampleTranslation":"가게에서 저지방 우유 한 팩 사다 줄래?","sense":"저지방 우유"},{"wordId":21637,"answer":"spicy food","form":"원형","example":"My little brother cries every time he tries spicy food.","exampleTranslation":"내 남동생은 매운 음식을 먹어 볼 때마다 운다.","sense":"매운 음식"},{"wordId":21638,"answer":"fast food","form":"원형","example":"There are too many fast food restaurants near my school.","exampleTranslation":"우리 학교 근처에는 패스트푸드 식당이 너무 많다.","sense":"패스트푸드"},{"wordId":21639,"answer":"light snack","form":"원형","example":"An apple with peanut butter is a light snack I enjoy after school.","exampleTranslation":"땅콩버터를 바른 사과는 내가 방과 후에 즐기는 가벼운 간식이다.","sense":"가벼운 간식"},{"wordId":21640,"answer":"make a full recovery","form":"원형","example":"With enough rest, your dog should make a full recovery after the surgery.","exampleTranslation":"충분히 쉬면 너희 개는 수술 후에 완전히 회복할 거야.","sense":"완전히 회복하다"},{"wordId":21641,"answer":"wear a mask","form":"원형","example":"Workers wear a mask when they paint inside small rooms.","exampleTranslation":"작업자들은 좁은 방 안에서 페인트칠을 할 때 마스크를 쓴다.","sense":"마스크를 쓰다"},{"wordId":21642,"answer":"feel refreshed","form":"원형","example":"A cold shower in the morning helps me feel refreshed for the day.","exampleTranslation":"아침에 찬물로 샤워하면 하루를 상쾌하게 시작할 수 있다.","sense":"상쾌해지다"},{"wordId":21643,"answer":"good for your health","form":"원형","example":"My grandmother believes that green tea is good for your health.","exampleTranslation":"할머니는 녹차가 건강에 좋다고 믿으신다.","sense":"건강에 좋은"},{"wordId":21644,"answer":"feel tired","form":"원형","example":"If you feel tired while driving, stop and take a short break.","exampleTranslation":"운전하다가 피곤하면 차를 세우고 잠깐 쉬어라.","sense":"피곤하다"},{"wordId":21645,"answer":"feel hungry","form":"원형","example":"Babies cry loudly when they feel hungry in the middle of the night.","exampleTranslation":"아기들은 한밤중에 배가 고프면 크게 운다.","sense":"배가 고프다"},{"wordId":21646,"answer":"feel stressed","form":"원형","example":"When I feel stressed, I go for a long walk with my dog.","exampleTranslation":"스트레스를 받으면 나는 개와 함께 오래 산책한다.","sense":"스트레스를 받다"},{"wordId":21647,"answer":"feel sleepy","form":"원형","example":"This cold medicine might make you feel sleepy, so do not drive.","exampleTranslation":"이 감기약은 졸릴 수 있으니 운전하지 마세요.","sense":"졸리다"},{"wordId":21648,"answer":"completely exhausted","form":"원형","example":"The nurses were completely exhausted after working a double shift.","exampleTranslation":"간호사들은 연달아 두 번 근무하고 나서 완전히 지쳤다.","sense":"완전히 지친"},{"wordId":21649,"answer":"badly hurt","form":"원형","example":"The hiker was badly hurt when he fell from the rocks.","exampleTranslation":"그 등산객은 바위에서 떨어져 심하게 다쳤다.","sense":"심하게 다친"},{"wordId":21650,"answer":"go swimming","form":"원형","example":"If the weather is hot tomorrow, we can go swimming in the lake.","exampleTranslation":"내일 날씨가 더우면 호수에 수영하러 가도 돼.","sense":"수영하러 가다"},{"wordId":21651,"answer":"save money","form":"원형","example":"My kids put coins in a jar to save money for a new bike.","exampleTranslation":"우리 아이들은 새 자전거를 사려고 돈을 모으며 동전을 병에 넣는다.","sense":"돈을 모으다"},{"wordId":21652,"answer":"borrow money","form":"원형","example":"Young couples often borrow money from the bank to buy a house.","exampleTranslation":"젊은 부부들은 집을 사려고 은행에서 돈을 빌리는 경우가 많다.","sense":"돈을 빌리다"},{"wordId":21653,"answer":"lend money","form":"원형","example":"My parents do not like to lend money to relatives.","exampleTranslation":"우리 부모님은 친척들에게 돈 빌려주는 걸 좋아하지 않으신다.","sense":"돈을 빌려주다"},{"wordId":21654,"answer":"pay by card","form":"원형","example":"The taxi driver said I could pay by card at the end of the ride.","exampleTranslation":"택시 기사가 내릴 때 카드로 결제해도 된다고 했다.","sense":"카드로 결제하다"},{"wordId":21655,"answer":"open an account","form":"원형","example":"My daughter is old enough to open an account for her savings.","exampleTranslation":"딸은 저축을 위해 계좌를 개설할 수 있을 만큼 컸다.","sense":"계좌를 개설하다"},{"wordId":21656,"answer":"withdraw money","form":"원형","example":"You can withdraw money at the counter if the machine is broken.","exampleTranslation":"기계가 고장 났으면 창구에서 돈을 인출할 수 있다.","sense":"돈을 인출하다"},{"wordId":21657,"answer":"pay off a loan","form":"원형","example":"They sold their old car to pay off a loan from the bank.","exampleTranslation":"그들은 은행 대출을 다 갚으려고 오래된 차를 팔았다.","sense":"대출을 다 갚다"},{"wordId":21658,"answer":"on a budget","form":"원형","example":"Students on a budget often cook at home instead of eating out.","exampleTranslation":"형편이 빠듯한 학생들은 외식 대신 집에서 요리하는 경우가 많다.","sense":"알뜰하게"},{"wordId":21659,"answer":"get a discount","form":"원형","example":"If you buy two shirts, you can get a discount on the second one.","exampleTranslation":"셔츠를 두 장 사면 두 번째 셔츠는 할인받을 수 있다.","sense":"할인을 받다"},{"wordId":21660,"answer":"good deal","form":"원형","example":"My brother found a good deal on a used bike online.","exampleTranslation":"형은 온라인에서 중고 자전거를 싸게 잘 샀다.","sense":"싸게 잘 산 것"},{"wordId":21661,"answer":"full price","form":"원형","example":"The shoes were not on sale, so I had to pay full price.","exampleTranslation":"신발이 세일 중이 아니어서 정가를 내야 했다.","sense":"정가"},{"wordId":21662,"answer":"go shopping","form":"원형","example":"My sister and I love to go shopping at the outlet mall.","exampleTranslation":"언니와 나는 아웃렛 매장에 쇼핑하러 가는 걸 좋아한다.","sense":"쇼핑하러 가다"},{"wordId":21663,"answer":"get a refund","form":"원형","example":"The concert was canceled, so everyone will get a refund for their tickets.","exampleTranslation":"콘서트가 취소되어서 모두 표값을 환불받을 것이다.","sense":"환불받다"},{"wordId":21664,"answer":"keep the receipt","form":"원형","example":"Please keep the receipt so your company can pay you back later.","exampleTranslation":"나중에 회사에서 돌려받을 수 있도록 영수증을 보관하세요.","sense":"영수증을 보관하다"},{"wordId":21665,"answer":"pay taxes","form":"원형","example":"Small business owners pay taxes every three months in some countries.","exampleTranslation":"어떤 나라에서는 자영업자들이 석 달마다 세금을 낸다.","sense":"세금을 내다"},{"wordId":21666,"answer":"affordable price","form":"원형","example":"The new gym near my office has classes at an affordable price.","exampleTranslation":"사무실 근처에 새로 생긴 헬스장은 수업료가 적당하다.","sense":"적당한 가격"},{"wordId":21667,"answer":"book a flight","form":"원형","example":"My parents want to book a flight to visit us in December.","exampleTranslation":"부모님은 십이월에 우리를 보러 오시려고 항공권을 예약하고 싶어 하신다.","sense":"항공권을 예약하다"},{"wordId":21668,"answer":"book a room","form":"원형","example":"Call the hotel today and book a room before the festival weekend.","exampleTranslation":"축제 주말 전에 오늘 호텔에 전화해서 방을 예약해라.","sense":"방을 예약하다"},{"wordId":21669,"answer":"pack your bags","form":"원형","example":"You should pack your bags the night before your camping trip.","exampleTranslation":"캠핑 여행 전날 밤에 짐을 싸 두는 게 좋다.","sense":"짐을 싸다"},{"wordId":21670,"answer":"miss your flight","form":"원형","example":"If the traffic is this bad, you might miss your flight to Denver.","exampleTranslation":"교통이 이렇게 막히면 덴버행 비행기를 놓칠 수도 있다.","sense":"비행기를 놓치다"},{"wordId":21671,"answer":"pay in full","form":"원형","example":"The store gives a small discount if you pay in full today.","exampleTranslation":"그 가게는 오늘 전액을 지불하면 조금 할인해 준다.","sense":"전액 지불하다"},{"wordId":21672,"answer":"one-way ticket","form":"원형","example":"She bought a one-way ticket to Seattle to start her new job.","exampleTranslation":"그녀는 새 직장 생활을 시작하려고 시애틀행 편도 표를 샀다.","sense":"편도 표"},{"wordId":21673,"answer":"go sightseeing","form":"원형","example":"After the conference, we had one free day to go sightseeing in Rome.","exampleTranslation":"콘퍼런스가 끝난 뒤 우리는 로마에서 관광할 수 있는 하루가 있었다.","sense":"관광하다"},{"wordId":21674,"answer":"take a trip","form":"원형","example":"My grandparents take a trip to the mountains every fall.","exampleTranslation":"조부모님은 가을마다 산으로 여행을 가신다.","sense":"여행을 가다"},{"wordId":21675,"answer":"local food","form":"원형","example":"The hotel staff told us where to find the best local food.","exampleTranslation":"호텔 직원이 가장 맛있는 현지 음식을 어디서 먹을 수 있는지 알려 주었다.","sense":"현지 음식"},{"wordId":21676,"answer":"jet lag","form":"원형","example":"Drinking water and walking in the sun can help with jet lag.","exampleTranslation":"물을 마시고 햇빛 아래에서 걸으면 시차증에 도움이 된다.","sense":"시차증"},{"wordId":21677,"answer":"exchange money","form":"원형","example":"You can exchange money at the airport, but the rate is not great.","exampleTranslation":"공항에서 환전할 수 있지만 환율이 좋지는 않다.","sense":"환전하다"},{"wordId":21678,"answer":"passport control","form":"원형","example":"Have your passport ready when you get to passport control.","exampleTranslation":"출입국 심사대에 도착하면 여권을 꺼내 두세요.","sense":"출입국 심사대"},{"wordId":21679,"answer":"return flight","form":"원형","example":"The airline canceled our return flight, so we stayed one more night.","exampleTranslation":"항공사가 우리가 돌아올 항공편을 취소해서 하룻밤 더 묵었다.","sense":"돌아오는 항공편"},{"wordId":21680,"answer":"extra charge","form":"원형","example":"The airline asked for an extra charge because my suitcase was too heavy.","exampleTranslation":"내 여행 가방이 너무 무거워서 항공사가 추가 요금을 요구했다.","sense":"추가 요금"},{"wordId":21681,"answer":"tip the waiter","form":"원형","example":"My dad always forgets to tip the waiter when we eat out.","exampleTranslation":"아빠는 외식할 때 항상 웨이터에게 팁 주는 걸 잊으신다.","sense":"팁을 주다"},{"wordId":21682,"answer":"bank account","form":"원형","example":"I set up a bank account for my son on his tenth birthday.","exampleTranslation":"아들의 열 번째 생일에 아들 이름으로 은행 계좌를 만들어 주었다.","sense":"은행 계좌"},{"wordId":21683,"answer":"online shopping","form":"원형","example":"My grandmother learned online shopping during the long winter.","exampleTranslation":"할머니는 긴 겨울 동안 온라인 쇼핑하는 법을 배우셨다.","sense":"온라인 쇼핑"},{"wordId":21684,"answer":"free shipping","form":"원형","example":"I added one more book to my cart to get free shipping.","exampleTranslation":"무료 배송을 받으려고 장바구니에 책 한 권을 더 담았다.","sense":"무료 배송"},{"wordId":21685,"answer":"make a payment","form":"원형","example":"Please make a payment before the end of the month to avoid late fees.","exampleTranslation":"연체료를 내지 않으려면 월말 전에 납부해 주세요.","sense":"납부하다"},{"wordId":21686,"answer":"pay a fine","form":"원형","example":"My library book was two weeks late, so I had to pay a fine.","exampleTranslation":"도서관 책을 이 주나 늦게 반납해서 벌금을 내야 했다.","sense":"벌금을 내다"},{"wordId":21687,"answer":"lose money","form":"원형","example":"Restaurants lose money when bad weather keeps customers at home.","exampleTranslation":"날씨가 나빠서 손님들이 집에 머물면 식당들은 손해를 본다.","sense":"손해 보다"},{"wordId":21688,"answer":"waste money","form":"원형","example":"My mom says I waste money on snacks at the gas station.","exampleTranslation":"엄마는 내가 주유소에서 과자 사는 데 돈을 낭비한다고 하신다.","sense":"돈을 낭비하다"},{"wordId":21689,"answer":"pay the bills","form":"원형","example":"After he lost his job, he sold his guitar to pay the bills.","exampleTranslation":"그는 일자리를 잃은 뒤 생활비를 대려고 기타를 팔았다.","sense":"생활비를 대다"},{"wordId":21690,"answer":"student loan","form":"원형","example":"My sister used her first bonus to pay back part of her student loan.","exampleTranslation":"언니는 첫 보너스로 학자금 대출의 일부를 갚았다.","sense":"학자금 대출"},{"wordId":21691,"answer":"take a taxi","form":"원형","example":"The buses stop running at midnight, so we had to take a taxi.","exampleTranslation":"버스가 자정에 끊겨서 우리는 택시를 타야 했다.","sense":"택시를 타다"},{"wordId":21692,"answer":"catch a bus","form":"원형","example":"If you miss the train, you can catch a bus to the airport.","exampleTranslation":"기차를 놓치면 공항까지 가는 버스를 탈 수 있다.","sense":"버스를 타다"},{"wordId":21693,"answer":"get a ride","form":"원형","example":"My car is in the shop, so I need to get a ride to work.","exampleTranslation":"차가 정비소에 있어서 회사까지 차를 얻어 타야 한다.","sense":"차를 얻어 타다"},{"wordId":21694,"answer":"cheap flight","form":"원형","example":"If you are flexible with dates, it is easy to find a cheap flight.","exampleTranslation":"날짜를 유연하게 잡으면 저렴한 항공편을 찾기 쉽다.","sense":"저렴한 항공편"},{"wordId":21695,"answer":"travel abroad","form":"원형","example":"My parents saved for years to travel abroad after they retired.","exampleTranslation":"부모님은 은퇴 후 해외여행을 하려고 여러 해 동안 저축하셨다.","sense":"해외여행을 하다"},{"wordId":21696,"answer":"foreign country","form":"원형","example":"Learning to drive in a foreign country can be a little scary.","exampleTranslation":"외국에서 운전을 배우는 건 조금 무서울 수 있다.","sense":"외국"},{"wordId":21697,"answer":"public transportation","form":"원형","example":"Our new apartment is close to public transportation, so we sold the car.","exampleTranslation":"새 아파트가 대중교통과 가까워서 우리는 차를 팔았다.","sense":"대중교통"},{"wordId":21698,"answer":"take the subway","form":"원형","example":"On rainy days, I take the subway instead of riding my bike.","exampleTranslation":"비 오는 날에는 자전거 대신 지하철을 탄다.","sense":"지하철을 타다"},{"wordId":21699,"answer":"traffic light","form":"원형","example":"The traffic light on our street was broken during the storm.","exampleTranslation":"우리 동네 거리의 신호등이 폭풍 때 고장 났다.","sense":"신호등"},{"wordId":21700,"answer":"department store","form":"원형","example":"The department store downtown has a big sale every January.","exampleTranslation":"시내 백화점은 매년 일월에 큰 세일을 한다.","sense":"백화점"},{"wordId":21701,"answer":"feel nervous","form":"원형","example":"Many people feel nervous on their first day at a new school.","exampleTranslation":"많은 사람들이 새 학교에 가는 첫날 긴장한다.","sense":"긴장되다"},{"wordId":21702,"answer":"feel lonely","form":"원형","example":"My grandmother started to feel lonely after her children moved away.","exampleTranslation":"할머니는 자녀들이 멀리 이사 간 뒤로 외로움을 느끼기 시작하셨다.","sense":"외롭다"},{"wordId":21703,"answer":"best friend","form":"원형","example":"I told my best friend about the surprise party for my mom.","exampleTranslation":"가장 친한 친구에게 엄마를 위한 깜짝 파티 이야기를 했다.","sense":"가장 친한 친구"},{"wordId":21704,"answer":"close friends","form":"원형","example":"My grandmother still writes letters to her close friends from school.","exampleTranslation":"할머니는 지금도 학창 시절의 친한 친구들에게 편지를 쓰신다.","sense":"친한 친구들"},{"wordId":21705,"answer":"go on a date","form":"원형","example":"My parents still go on a date every Friday night after thirty years.","exampleTranslation":"우리 부모님은 결혼 삼십 년이 지나도 매주 금요일 밤 데이트하러 나가신다.","sense":"데이트하러 가다"},{"wordId":21706,"answer":"fall in love","form":"원형","example":"In the movie, the two strangers fall in love on a long train ride.","exampleTranslation":"그 영화에서 두 낯선 사람은 긴 기차 여행 중에 사랑에 빠진다.","sense":"사랑에 빠지다"},{"wordId":21707,"answer":"spend quality time","form":"원형","example":"On Sundays, we turn off our phones and spend quality time as a family.","exampleTranslation":"일요일마다 우리는 휴대폰을 끄고 가족끼리 오붓한 시간을 보낸다.","sense":"오붓한 시간을 보내다"},{"wordId":21708,"answer":"get along well","form":"원형","example":"I hope my new roommate and I will get along well this year.","exampleTranslation":"올해 새 룸메이트와 내가 사이좋게 지냈으면 좋겠다.","sense":"사이좋게 지내다"},{"wordId":21709,"answer":"feel proud","form":"원형","example":"The players should feel proud of how hard they played tonight.","exampleTranslation":"선수들은 오늘 밤 얼마나 열심히 뛰었는지 자랑스러워해도 된다.","sense":"자랑스럽다"},{"wordId":21710,"answer":"feel guilty","form":"원형","example":"I feel guilty when I forget to call my grandmother on Sundays.","exampleTranslation":"일요일에 할머니께 전화드리는 걸 잊으면 죄책감이 든다.","sense":"죄책감을 느끼다"},{"wordId":21711,"answer":"burst into tears","form":"원형","example":"The little boy might burst into tears if we leave without his teddy bear.","exampleTranslation":"곰 인형 없이 떠나면 그 꼬마는 울음을 터뜨릴지도 몰라.","sense":"울음을 터뜨리다"},{"wordId":21712,"answer":"stay calm","form":"원형","example":"If you get lost in the forest, stay calm and wait for help.","exampleTranslation":"숲에서 길을 잃으면 침착하게 도움을 기다려라.","sense":"침착함을 유지하다"},{"wordId":21713,"answer":"sunny day","form":"원형","example":"On a sunny day like this, we should wash the car outside.","exampleTranslation":"이렇게 화창한 날에는 밖에서 세차를 해야겠다.","sense":"화창한 날"},{"wordId":21714,"answer":"clear sky","form":"원형","example":"The pilot said we can expect a clear sky all the way to Miami.","exampleTranslation":"조종사는 마이애미까지 내내 맑은 하늘이 이어질 거라고 말했다.","sense":"맑은 하늘"},{"wordId":21715,"answer":"heavy snow","form":"원형","example":"The heavy snow made our flight to Denver four hours late.","exampleTranslation":"폭설 때문에 덴버행 비행기가 네 시간 늦어졌다.","sense":"폭설"},{"wordId":21716,"answer":"gentle breeze","form":"원형","example":"We sat on the porch and enjoyed the gentle breeze after dinner.","exampleTranslation":"우리는 저녁을 먹고 현관 앞에 앉아 산들바람을 즐겼다.","sense":"산들바람"},{"wordId":21717,"answer":"hot and humid","form":"원형","example":"My hair always gets frizzy when the weather is hot and humid.","exampleTranslation":"날씨가 덥고 습하면 내 머리카락은 늘 부스스해진다.","sense":"덥고 습한"},{"wordId":21718,"answer":"freezing cold","form":"원형","example":"The water in the lake was freezing cold, but the kids jumped in anyway.","exampleTranslation":"호수 물은 몹시 차가웠지만 아이들은 그래도 뛰어들었다.","sense":"몹시 차가운"},{"wordId":21719,"answer":"pouring rain","form":"원형","example":"The soccer game continued even in the pouring rain.","exampleTranslation":"축구 경기는 쏟아지는 비 속에서도 계속되었다.","sense":"쏟아지는 비"},{"wordId":21720,"answer":"the temperature drops","form":"원형","example":"Bring a warm jacket, because the temperature drops quickly after sunset.","exampleTranslation":"해가 지면 기온이 빠르게 떨어지니까 따뜻한 재킷을 챙겨라.","sense":"기온이 떨어지다"},{"wordId":21721,"answer":"the wind picks up","form":"원형","example":"Hold on to your hat when the wind picks up on the ferry.","exampleTranslation":"배에서 바람이 거세지면 모자를 꽉 잡아라.","sense":"바람이 거세지다"},{"wordId":21722,"answer":"early morning","form":"원형","example":"The fishermen leave the harbor in the early morning before sunrise.","exampleTranslation":"어부들은 해 뜨기 전 이른 아침에 항구를 떠난다.","sense":"이른 아침"},{"wordId":21723,"answer":"late at night","form":"원형","example":"My brother often eats ramen in the kitchen late at night.","exampleTranslation":"우리 형은 밤늦게 부엌에서 라면을 자주 먹는다.","sense":"밤늦게"},{"wordId":21724,"answer":"right away","form":"원형","example":"The plumber came right away when we called about the flood.","exampleTranslation":"물이 넘친다고 전화하자 배관공이 바로 왔다.","sense":"즉시"},{"wordId":21725,"answer":"on the weekend","form":"원형","example":"My dad likes to wash his car on the weekend when the weather is nice.","exampleTranslation":"아빠는 날씨가 좋으면 주말에 세차하는 걸 좋아하신다.","sense":"주말에"},{"wordId":21726,"answer":"for a while","form":"원형","example":"My aunt lived in Canada for a while before she moved back home.","exampleTranslation":"이모는 고국으로 돌아오기 전에 한동안 캐나다에서 사셨다.","sense":"한동안"},{"wordId":21727,"answer":"cancel plans","form":"원형","example":"My boss does not like it when we cancel plans at the last minute.","exampleTranslation":"우리 상사는 우리가 막판에 약속을 취소하는 걸 싫어한다.","sense":"약속을 취소하다"},{"wordId":21728,"answer":"feel jealous","form":"원형","example":"Try not to feel jealous when your friends post their vacation photos.","exampleTranslation":"친구들이 휴가 사진을 올려도 질투하지 않도록 해 봐.","sense":"질투가 나다"},{"wordId":21729,"answer":"good mood","form":"원형","example":"The coach was in a good mood after the team won the game.","exampleTranslation":"팀이 경기에서 이기자 코치는 기분이 좋았다.","sense":"좋은 기분"},{"wordId":21730,"answer":"feel homesick","form":"원형","example":"During my first winter abroad, I started to feel homesick at night.","exampleTranslation":"해외에서 보낸 첫 겨울에 나는 밤마다 향수병을 느끼기 시작했다.","sense":"향수병을 느끼다"},{"wordId":21731,"answer":"make eye contact","form":"원형","example":"Shy children sometimes find it hard to make eye contact with adults.","exampleTranslation":"수줍음 많은 아이들은 어른과 눈을 맞추기 어려워하기도 한다.","sense":"눈을 맞추다"},{"wordId":21732,"answer":"give me a hug","form":"원형","example":"Please give me a hug before you board the plane to college.","exampleTranslation":"대학 가는 비행기 타기 전에 나 한번 안아 줘.","sense":"나를 안아 주다"},{"wordId":21733,"answer":"say goodbye","form":"원형","example":"The children waved to say goodbye to their teacher on the last day.","exampleTranslation":"아이들은 마지막 날 선생님께 손을 흔들며 작별 인사를 했다.","sense":"작별 인사를 하다"},{"wordId":21734,"answer":"birthday present","form":"원형","example":"My grandmother knitted a scarf for my birthday present this year.","exampleTranslation":"할머니가 올해 내 생일 선물로 목도리를 떠 주셨다.","sense":"생일 선물"},{"wordId":21735,"answer":"first impression","form":"원형","example":"Her warm smile gave me a great first impression of the new neighbor.","exampleTranslation":"새 이웃의 따뜻한 미소 덕분에 첫인상이 아주 좋았다.","sense":"첫인상"},{"wordId":21736,"answer":"feel relieved","form":"원형","example":"We all feel relieved now that the storm has passed.","exampleTranslation":"폭풍이 지나가서 이제 우리 모두 안도한다.","sense":"안도하다"},{"wordId":21737,"answer":"cold weather","form":"원형","example":"In cold weather, the old car takes a long time to start.","exampleTranslation":"추운 날씨에는 그 낡은 차가 시동이 걸리는 데 오래 걸린다.","sense":"추운 날씨"},{"wordId":21738,"answer":"feel embarrassed","form":"원형","example":"I feel embarrassed when my parents dance in front of my friends.","exampleTranslation":"부모님이 내 친구들 앞에서 춤을 추시면 나는 민망하다.","sense":"민망하다"},{"wordId":21739,"answer":"feel grateful","form":"원형","example":"When I see hungry people on the news, I feel grateful for every meal.","exampleTranslation":"뉴스에서 굶주린 사람들을 보면 모든 끼니가 감사하게 느껴진다.","sense":"감사하게 여기다"},{"wordId":21740,"answer":"feel disappointed","form":"원형","example":"Children often feel disappointed when a trip to the zoo is canceled.","exampleTranslation":"아이들은 동물원 나들이가 취소되면 실망하곤 한다.","sense":"실망하다"},{"wordId":21741,"answer":"meet new people","form":"원형","example":"My grandmother joined a dance class to meet new people in town.","exampleTranslation":"할머니는 동네에서 새로운 사람들을 만나려고 춤 강습에 등록하셨다.","sense":"새로운 사람들을 만나다"},{"wordId":21742,"answer":"introduce yourself","form":"원형","example":"When you call the hotel, introduce yourself and give your booking number.","exampleTranslation":"호텔에 전화하면 먼저 이름을 밝히고 예약 번호를 알려 주세요.","sense":"자기소개를 하다"},{"wordId":21743,"answer":"shake hands","form":"원형","example":"After the game, both teams lined up to shake hands.","exampleTranslation":"경기가 끝난 뒤 두 팀은 줄을 서서 악수했다.","sense":"악수하다"},{"wordId":21744,"answer":"married couple","form":"원형","example":"A young married couple just moved into the apartment upstairs.","exampleTranslation":"젊은 부부가 막 위층 아파트로 이사 왔다.","sense":"부부"},{"wordId":21745,"answer":"nice weather","form":"원형","example":"If we have nice weather tomorrow, we can go to the beach.","exampleTranslation":"내일 날씨가 좋으면 해변에 갈 수 있다.","sense":"좋은 날씨"},{"wordId":21746,"answer":"rainy season","form":"원형","example":"Many tourists avoid this island during the rainy season.","exampleTranslation":"많은 관광객들이 우기에는 이 섬을 피한다.","sense":"우기"},{"wordId":21747,"answer":"weather report","form":"원형","example":"My grandfather watches the weather report every evening before dinner.","exampleTranslation":"할아버지는 매일 저녁 식사 전에 일기 예보를 보신다.","sense":"일기 예보"},{"wordId":21748,"answer":"get dark","form":"원형","example":"In winter, it starts to get dark before five in the afternoon.","exampleTranslation":"겨울에는 오후 다섯 시 전에 어두워지기 시작한다.","sense":"어두워지다"},{"wordId":21749,"answer":"just in time","form":"원형","example":"I finished my report just in time for the meeting.","exampleTranslation":"회의 시간에 딱 맞춰 보고서를 끝냈다.","sense":"딱 맞춰"},{"wordId":21750,"answer":"on weekdays","form":"원형","example":"The museum is free on weekdays after four in the afternoon.","exampleTranslation":"그 박물관은 평일 오후 네 시 이후에는 무료다.","sense":"평일에"},{"wordId":21751,"answer":"hit the hay","form":"원형","example":"We have to leave at dawn, so I will hit the hay right after dinner.","exampleTranslation":"새벽에 출발해야 해서 저녁 먹고 바로 자러 갈 거야.","sense":"자러 가다"},{"wordId":21752,"answer":"cut me some slack","form":"원형","example":"Mom, please cut me some slack because I cleaned my room yesterday.","exampleTranslation":"엄마, 저 어제 방 청소했으니까 좀 봐주세요.","sense":"좀 봐줘"},{"wordId":21753,"answer":"at the end of the day","form":"원형","example":"Prices matter, but at the end of the day, I buy shoes that feel good.","exampleTranslation":"가격도 중요하지만 결국 나는 신었을 때 편한 신발을 산다.","sense":"결국"},{"wordId":21754,"answer":"bark up the wrong tree","form":"원형","example":"If you blame the cat for the mess, you may bark up the wrong tree.","exampleTranslation":"엉망이 된 걸 고양이 탓으로 돌리면 헛다리 짚는 걸 수도 있어.","sense":"헛다리 짚다"},{"wordId":21755,"answer":"blow off steam","form":"원형","example":"My dad goes to the gym after work to blow off steam.","exampleTranslation":"아빠는 스트레스를 풀려고 퇴근 후 헬스장에 가신다.","sense":"스트레스를 풀다"},{"wordId":21756,"answer":"by and large","form":"원형","example":"The weather was rainy, but by and large, we enjoyed our trip to Ireland.","exampleTranslation":"날씨는 비가 왔지만 대체로 우리는 아일랜드 여행을 즐겼다.","sense":"대체로"},{"wordId":21757,"answer":"call it a night","form":"원형","example":"We finished most of the puzzle, so we decided to call it a night.","exampleTranslation":"퍼즐을 거의 다 맞춰서 오늘은 여기까지 하기로 했다.","sense":"그만 끝내다"},{"wordId":21758,"answer":"cut it close","form":"원형","example":"You only left ten minutes for the train change, so you might cut it close.","exampleTranslation":"기차 갈아탈 시간을 십 분밖에 안 남겼으니 아슬아슬할 수도 있어.","sense":"아슬아슬하다"},{"wordId":21759,"answer":"down the road","form":"원형","example":"My son wants to study abroad somewhere down the road.","exampleTranslation":"아들은 나중에 언젠가 해외에서 공부하고 싶어 한다.","sense":"나중에"},{"wordId":21760,"answer":"drive me up the wall","form":"원형","example":"If you keep tapping your pen like that, you will drive me up the wall.","exampleTranslation":"그렇게 계속 펜을 두드리면 나 정말 짜증 나서 미칠 거야.","sense":"몹시 짜증 나게 하다"},{"wordId":21761,"answer":"easy does it","form":"원형","example":"Easy does it when you back the car out of this narrow garage.","exampleTranslation":"이 좁은 차고에서 차를 뺄 때는 살살 해.","sense":"살살 해"},{"wordId":21762,"answer":"every once in a while","form":"원형","example":"My grandparents still go dancing every once in a while.","exampleTranslation":"조부모님은 지금도 이따금 춤추러 가신다.","sense":"가끔"},{"wordId":21763,"answer":"fall into place","form":"원형","example":"After a stressful first week, things at my new school began to fall into place.","exampleTranslation":"힘들었던 첫 주가 지나자 새 학교 생활이 순조롭게 풀리기 시작했다.","sense":"제자리를 찾다"},{"wordId":21764,"answer":"few and far between","form":"원형","example":"In this desert town, rainy days are few and far between.","exampleTranslation":"이 사막 마을에서는 비 오는 날이 아주 드물다.","sense":"아주 드문"},{"wordId":21765,"answer":"get a kick out of","form":"원형","example":"My grandfather seems to get a kick out of telling the same jokes.","exampleTranslation":"할아버지는 같은 농담을 하시는 걸 아주 재미있어하시는 것 같다.","sense":"아주 재미있어하다"},{"wordId":21766,"answer":"get your act together","form":"원형","example":"Your boss is not happy, so you need to get your act together this week.","exampleTranslation":"상사가 불만이 많으니 이번 주에는 정신 차려야 해.","sense":"정신 차리다"},{"wordId":21767,"answer":"in the ballpark","form":"원형","example":"The mechanic gave me a price that was in the ballpark of what I expected.","exampleTranslation":"정비사가 내가 예상한 것과 대략 비슷한 가격을 불렀다.","sense":"대략 맞는"},{"wordId":21768,"answer":"not the end of the world","form":"원형","example":"You burned the toast, but it is not the end of the world.","exampleTranslation":"토스트를 태웠지만 그렇게 큰일은 아니야.","sense":"큰일은 아닌"},{"wordId":21769,"answer":"keep your cool","form":"원형","example":"When your kids fight in the car, try to keep your cool.","exampleTranslation":"아이들이 차 안에서 싸우면 평정심을 잃지 않도록 해 봐.","sense":"평정심을 유지하다"},{"wordId":21770,"answer":"let it slide","form":"원형","example":"The cashier gave me too much change, but I could not let it slide.","exampleTranslation":"계산원이 거스름돈을 너무 많이 줬지만 그냥 넘어갈 수 없었다.","sense":"그냥 넘어가다"},{"wordId":21771,"answer":"let your hair down","form":"원형","example":"On a beach vacation, you can finally let your hair down and relax.","exampleTranslation":"해변 휴가에서는 마침내 긴장을 풀고 마음껏 즐길 수 있다.","sense":"마음껏 즐기다"},{"wordId":21772,"answer":"no strings attached","form":"원형","example":"The gym offers a free week with no strings attached.","exampleTranslation":"그 헬스장은 아무 조건 없이 일주일 무료 이용을 제공한다.","sense":"아무 조건 없이"},{"wordId":21773,"answer":"off the hook","form":"원형","example":"The teacher canceled the quiz, so the whole class was off the hook.","exampleTranslation":"선생님이 쪽지 시험을 취소해서 반 전체가 곤경에서 벗어났다.","sense":"곤경에서 벗어난"},{"wordId":21774,"answer":"off the top of my head","form":"원형","example":"I do not know his phone number off the top of my head.","exampleTranslation":"그의 전화번호가 당장 떠오르지 않는다.","sense":"즉석에서"},{"wordId":21775,"answer":"on the ball","form":"원형","example":"The goalkeeper was really on the ball and stopped every shot.","exampleTranslation":"골키퍼는 정말 빈틈없어서 모든 슛을 막아 냈다.","sense":"빈틈없는"},{"wordId":21776,"answer":"on the go","form":"원형","example":"I eat breakfast on the go because I leave home so early.","exampleTranslation":"나는 집을 너무 일찍 나서서 아침을 이동하면서 먹는다.","sense":"이동하면서"},{"wordId":21777,"answer":"on the mend","form":"원형","example":"The doctor says my broken arm is on the mend and healing well.","exampleTranslation":"의사는 부러진 팔이 회복 중이고 잘 낫고 있다고 한다.","sense":"회복 중인"},{"wordId":21778,"answer":"on pins and needles","form":"원형","example":"The whole family was on pins and needles during the penalty kicks.","exampleTranslation":"승부차기 동안 온 가족이 안절부절못했다.","sense":"몹시 초조한"},{"wordId":21779,"answer":"on top of the world","form":"원형","example":"When our team won the championship, the fans were on top of the world.","exampleTranslation":"우리 팀이 우승하자 팬들은 날아갈 듯 기뻤다.","sense":"최고로 행복한"},{"wordId":21780,"answer":"out of this world","form":"원형","example":"The view from the top of the mountain was out of this world.","exampleTranslation":"산꼭대기에서 본 경치는 환상적이었다.","sense":"환상적인"},{"wordId":21781,"answer":"over the top","form":"원형","example":"His reaction to the small scratch on his car was over the top.","exampleTranslation":"차에 난 작은 긁힌 자국에 대한 그의 반응은 지나쳤다.","sense":"지나친"},{"wordId":21782,"answer":"play it safe","form":"원형","example":"The roads are icy, so let us play it safe and stay home tonight.","exampleTranslation":"길이 얼어 있으니 안전하게 오늘 밤은 집에 있자.","sense":"안전하게 가다"},{"wordId":21783,"answer":"pull yourself together","form":"원형","example":"I know the news is sad, but you need to pull yourself together for the kids.","exampleTranslation":"슬픈 소식인 건 알지만 아이들을 위해 마음을 추슬러야 해.","sense":"마음을 추스르다"},{"wordId":21784,"answer":"take a rain check","form":"원형","example":"Thanks for inviting me to the game, but I need to take a rain check.","exampleTranslation":"경기에 초대해 줘서 고맙지만 다음 기회로 미뤄야겠어.","sense":"다음 기회로 미루다"},{"wordId":21785,"answer":"ring a bell","form":"원형","example":"The name of that hotel seems to ring a bell from my last trip.","exampleTranslation":"그 호텔 이름은 지난 여행 때 들어 본 것 같다.","sense":"들어 본 것 같다"},{"wordId":21786,"answer":"save the day","form":"원형","example":"Our car broke down, but a kind farmer with a truck came to save the day.","exampleTranslation":"차가 고장 났지만 트럭을 가진 친절한 농부가 와서 위기를 구해 주었다.","sense":"위기를 구하다"},{"wordId":21787,"answer":"sleep like a log","form":"원형","example":"The fresh mountain air always makes me sleep like a log.","exampleTranslation":"상쾌한 산 공기를 마시면 나는 늘 세상모르고 잔다.","sense":"곤히 자다"},{"wordId":21788,"answer":"so far so good","form":"원형","example":"My new diet started on Monday, and so far so good.","exampleTranslation":"새 식단을 월요일에 시작했는데 지금까지는 괜찮다.","sense":"아직까지는 괜찮은"},{"wordId":21789,"answer":"spread yourself too thin","form":"원형","example":"If you work two jobs and take classes, you will spread yourself too thin.","exampleTranslation":"일을 두 개 하면서 수업까지 들으면 너무 많은 일을 벌이게 될 거야.","sense":"너무 많은 일을 벌이다"},{"wordId":21790,"answer":"steal the show","form":"원형","example":"At the school concert, the youngest drummer seemed to steal the show.","exampleTranslation":"학교 음악회에서 가장 어린 드럼 연주자가 주목을 다 받는 것 같았다.","sense":"주목을 다 받다"},{"wordId":21791,"answer":"take it easy","form":"원형","example":"You have been studying all day, so take it easy this evening.","exampleTranslation":"하루 종일 공부했으니 오늘 저녁은 쉬엄쉬엄해.","sense":"쉬엄쉬엄하다"},{"wordId":21792,"answer":"the whole nine yards","form":"원형","example":"When my mom cleans for guests, she does the whole nine yards.","exampleTranslation":"엄마는 손님 맞이 청소를 할 때 할 수 있는 건 전부 하신다.","sense":"할 수 있는 건 전부"},{"wordId":21793,"answer":"to each their own","form":"원형","example":"My dad drinks hot coffee even in summer, but to each their own.","exampleTranslation":"아빠는 여름에도 뜨거운 커피를 드시지만 사람마다 취향이 다른 법이다.","sense":"사람마다 취향이 다르다"},{"wordId":21794,"answer":"under the radar","form":"원형","example":"The singer tried to travel under the radar by wearing a hat and sunglasses.","exampleTranslation":"그 가수는 모자와 선글라스를 쓰고 눈에 띄지 않게 여행하려 했다.","sense":"눈에 띄지 않게"},{"wordId":21795,"answer":"up for grabs","form":"원형","example":"The last two concert tickets are still up for grabs on the website.","exampleTranslation":"마지막 콘서트 표 두 장은 아직 웹사이트에서 누구나 살 수 있다.","sense":"아직 주인이 없는"},{"wordId":21796,"answer":"up in arms","form":"원형","example":"The neighbors were up in arms when the city cut down the old trees.","exampleTranslation":"시에서 오래된 나무들을 베어 내자 주민들이 들고일어났다.","sense":"들고일어난"},{"wordId":21797,"answer":"when it rains, it pours","form":"원형","example":"Both my car and my laptop broke this week; I guess when it rains, it pours.","exampleTranslation":"이번 주에 차도 노트북도 고장 났으니 엎친 데 덮친 격이다.","sense":"엎친 데 덮친 격"},{"wordId":21798,"answer":"judge a book by its cover","form":"원형","example":"The new student looks shy, but you should not judge a book by its cover.","exampleTranslation":"새로 온 학생이 수줍어 보이지만 겉모습만 보고 판단하면 안 돼.","sense":"겉모습만 보고 판단하다"},{"wordId":21799,"answer":"back to back","form":"원형","example":"The band played two concerts back to back on Saturday night.","exampleTranslation":"그 밴드는 토요일 밤에 연달아 두 번 공연했다.","sense":"연달아"},{"wordId":21800,"answer":"the big picture","form":"원형","example":"Losing one game is sad, but the coach wants us to see the big picture.","exampleTranslation":"한 경기에 진 건 아쉽지만 코치는 우리가 전체적인 상황을 보길 바란다.","sense":"큰 그림"},{"wordId":21801,"answer":"break new ground","form":"원형","example":"The young chef wants to break new ground by mixing Korean and Mexican food.","exampleTranslation":"그 젊은 셰프는 한식과 멕시코 음식을 섞어 새로운 분야를 개척하고 싶어 한다.","sense":"새로운 분야를 개척하다"},{"wordId":21802,"answer":"bring to the table","form":"원형","example":"Tell us what you can bring to the table as a volunteer.","exampleTranslation":"자원봉사자로서 어떤 기여를 할 수 있는지 말해 주세요.","sense":"기여하다"},{"wordId":21803,"answer":"cross the line","form":"원형","example":"Reading your sister's diary without asking would really cross the line.","exampleTranslation":"허락 없이 여동생 일기를 읽는 건 정말 선을 넘는 일이야.","sense":"선을 넘다"},{"wordId":21804,"answer":"drop me a line","form":"원형","example":"If you ever visit Seoul again, please drop me a line first.","exampleTranslation":"혹시 서울에 다시 오게 되면 미리 연락 좀 줘.","sense":"연락 좀 줘"},{"wordId":21805,"answer":"every step of the way","form":"원형","example":"The nurse stayed with my mother every step of the way during her surgery.","exampleTranslation":"간호사는 엄마가 수술받는 동안 처음부터 끝까지 곁에 있어 주었다.","sense":"처음부터 끝까지"},{"wordId":21806,"answer":"fair and square","form":"원형","example":"My little brother won the card game fair and square this time.","exampleTranslation":"이번에는 남동생이 카드 게임에서 정정당당하게 이겼다.","sense":"정정당당하게"},{"wordId":21807,"answer":"fall flat","form":"원형","example":"The new menu might fall flat with customers who love the old dishes.","exampleTranslation":"예전 요리를 좋아하는 손님들에게는 새 메뉴가 먹히지 않을 수도 있다.","sense":"먹히지 않다"},{"wordId":21808,"answer":"fill me in","form":"원형","example":"When you get back from the trip, please fill me in on everything.","exampleTranslation":"여행에서 돌아오면 있었던 일을 전부 자세히 알려 줘.","sense":"자세히 알려 줘"},{"wordId":21809,"answer":"get a grip","form":"원형","example":"You need to get a grip and stop crying over a broken nail.","exampleTranslation":"정신 좀 차리고 부러진 손톱 하나로 그만 울어.","sense":"정신 차려"},{"wordId":21810,"answer":"get the picture","form":"원형","example":"Once I saw the empty cookie jar and your smile, I could get the picture.","exampleTranslation":"빈 과자 통과 네 미소를 보자마자 상황이 이해됐다.","sense":"감을 잡다"},{"wordId":21811,"answer":"get under my skin","form":"원형","example":"Those loud motorcycles outside my window at night get under my skin.","exampleTranslation":"밤에 창밖에서 들리는 시끄러운 오토바이 소리가 신경을 건드린다.","sense":"신경을 건드리다"},{"wordId":21812,"answer":"go overboard","form":"원형","example":"My grandmother tends to go overboard when she buys gifts for the kids.","exampleTranslation":"할머니는 아이들 선물을 사실 때 지나치게 많이 사시는 편이다.","sense":"지나치게 하다"},{"wordId":21813,"answer":"go the distance","form":"원형","example":"This old car has two hundred thousand miles, but it should go the distance.","exampleTranslation":"이 낡은 차는 이십만 마일을 달렸지만 끝까지 잘 버텨 줄 거다.","sense":"끝까지 해내다"},{"wordId":21814,"answer":"good to go","form":"원형","example":"The doctor checked your knee, and you are good to go for the race.","exampleTranslation":"의사가 무릎을 검사했으니 경주에 나가도 괜찮다.","sense":"준비가 다 된"},{"wordId":21815,"answer":"hang tight","form":"원형","example":"The website is a little slow, so hang tight while your order loads.","exampleTranslation":"웹사이트가 좀 느리니 주문이 처리되는 동안 잠깐 기다려 주세요.","sense":"잠깐 기다려"},{"wordId":21816,"answer":"have a blast","form":"원형","example":"The kids will have a blast at the water park tomorrow.","exampleTranslation":"아이들은 내일 워터파크에서 아주 즐거운 시간을 보낼 거야.","sense":"아주 즐거운 시간을 보내다"},{"wordId":21817,"answer":"a head start","form":"원형","example":"Leaving before sunrise gave us a head start on the long drive.","exampleTranslation":"해 뜨기 전에 출발해서 우리는 긴 운전을 먼저 시작할 수 있었다.","sense":"먼저 시작함"},{"wordId":21818,"answer":"hold down the fort","form":"원형","example":"My sister will hold down the fort at the shop while I visit our parents.","exampleTranslation":"내가 부모님을 뵈러 가는 동안 언니가 가게를 대신 맡아 줄 거다.","sense":"대신 맡아 지키다"},{"wordId":21819,"answer":"in the works","form":"원형","example":"Plans for a new park near the school are in the works.","exampleTranslation":"학교 근처에 새 공원을 만드는 계획이 진행 중이다.","sense":"진행 중인"},{"wordId":21820,"answer":"in a rut","form":"원형","example":"After ten years in the same job, my uncle felt stuck in a rut.","exampleTranslation":"같은 일을 십 년 하고 나니 삼촌은 판에 박힌 생활에 갇힌 기분이었다.","sense":"판에 박힌 생활에 빠진"},{"wordId":21821,"answer":"in a heartbeat","form":"원형","example":"If my best friend needed help, I would fly to see her in a heartbeat.","exampleTranslation":"가장 친한 친구가 도움이 필요하면 나는 망설임 없이 비행기를 타고 갈 거다.","sense":"망설임 없이"},{"wordId":21822,"answer":"in good hands","form":"원형","example":"The pilot has thirty years of experience, so you are in good hands.","exampleTranslation":"조종사는 경력이 삼십 년이니 안심하셔도 된다.","sense":"안심할 수 있는"},{"wordId":21823,"answer":"in the dark","form":"원형","example":"My parents kept me in the dark about the surprise trip to Hawaii.","exampleTranslation":"부모님은 깜짝 하와이 여행에 대해 나에게 전혀 알려 주지 않으셨다.","sense":"전혀 모르는"},{"wordId":21824,"answer":"takes two to tango","form":"원형","example":"My sons always blame each other, but it takes two to tango.","exampleTranslation":"우리 아들들은 늘 서로 탓하지만 손뼉도 마주쳐야 소리가 나는 법이다.","sense":"양쪽 다 책임이 있다"},{"wordId":21825,"answer":"last but not least","form":"원형","example":"Pack your passport, your charger, and last but not least, your tickets.","exampleTranslation":"여권과 충전기, 그리고 마지막으로 꼭 표를 챙겨라.","sense":"끝으로"},{"wordId":21826,"answer":"let bygones be bygones","form":"원형","example":"The two old friends decided to let bygones be bygones and have lunch together.","exampleTranslation":"두 오랜 친구는 지난 일은 잊고 함께 점심을 먹기로 했다.","sense":"지난 일은 잊다"},{"wordId":21827,"answer":"live and learn","form":"원형","example":"I forgot sunscreen and got a bad sunburn, but live and learn.","exampleTranslation":"선크림을 깜빡해서 심하게 탔지만 겪어 봐야 아는 법이지.","sense":"살면서 배우는 거지"},{"wordId":21828,"answer":"make waves","form":"원형","example":"My sister did not want to make waves at her new school, so she stayed quiet.","exampleTranslation":"언니는 새 학교에서 풍파를 일으키고 싶지 않아서 조용히 지냈다.","sense":"풍파를 일으키다"},{"wordId":21829,"answer":"a needle in a haystack","form":"원형","example":"Finding a cheap hotel room during the festival is like finding a needle in a haystack.","exampleTranslation":"축제 기간에 싼 호텔 방을 찾는 건 모래사장에서 바늘 찾기다.","sense":"모래사장에서 바늘 찾기"},{"wordId":21830,"answer":"no big deal","form":"원형","example":"Do not worry about being five minutes late; it is no big deal.","exampleTranslation":"오 분 늦는 건 걱정하지 마, 별일 아니야.","sense":"별일 아닌"},{"wordId":21831,"answer":"no hard feelings","form":"원형","example":"You beat me in the final round, but no hard feelings.","exampleTranslation":"마지막 판에서 네가 날 이겼지만 기분 나쁜 건 없어.","sense":"악감정은 없어"},{"wordId":21832,"answer":"on board","form":"원형","example":"My wife was not on board with buying a second dog at first.","exampleTranslation":"아내는 처음에 강아지를 한 마리 더 들이는 데 찬성하지 않았다.","sense":"동의하는"},{"wordId":21833,"answer":"on the same wavelength","form":"원형","example":"My new coworker and I were on the same wavelength from the first day.","exampleTranslation":"새 동료와 나는 첫날부터 생각이 잘 통했다.","sense":"생각이 잘 통하는"},{"wordId":21834,"answer":"once and for all","form":"원형","example":"I want to clean out the garage once and for all this weekend.","exampleTranslation":"이번 주말에는 차고를 완전히 정리해 버리고 싶다.","sense":"이번을 끝으로"},{"wordId":21835,"answer":"par for the course","form":"원형","example":"Long lines at the theme park are par for the course in summer.","exampleTranslation":"여름에 놀이공원에서 줄이 긴 건 흔한 일이다.","sense":"흔히 있는 일"},{"wordId":21836,"answer":"pay it forward","form":"원형","example":"My teacher helped me for free, so I tutor younger kids to pay it forward.","exampleTranslation":"선생님이 무료로 도와주셨으니 나도 그 호의를 베풀려고 어린 학생들을 가르친다.","sense":"받은 호의를 베풀다"},{"wordId":21837,"answer":"pie in the sky","form":"원형","example":"Buying a beach house next year is just pie in the sky for us.","exampleTranslation":"내년에 해변 별장을 사는 건 우리에게 그림의 떡일 뿐이다.","sense":"그림의 떡"},{"wordId":21838,"answer":"play catch-up","form":"원형","example":"I was sick for a week, so now I have to play catch-up at school.","exampleTranslation":"일주일 동안 아파서 이제 학교 공부를 따라잡아야 한다.","sense":"뒤처진 것을 따라잡다"},{"wordId":21839,"answer":"play hardball","form":"원형","example":"The landlord wants to play hardball about the broken window.","exampleTranslation":"집주인은 깨진 창문 문제로 강경하게 나오려 한다.","sense":"강경하게 나오다"},{"wordId":21840,"answer":"pull strings","form":"원형","example":"My uncle knows the owner, but he refuses to pull strings for anyone.","exampleTranslation":"삼촌은 사장을 알지만 누구를 위해서도 연줄을 쓰지 않으려 한다.","sense":"연줄을 이용하다"},{"wordId":21841,"answer":"put two and two together","form":"원형","example":"You can put two and two together when your dog has mud on its paws.","exampleTranslation":"강아지 발에 진흙이 묻어 있으면 무슨 일인지 짐작할 수 있다.","sense":"눈치채다"},{"wordId":21842,"answer":"rain or shine","form":"원형","example":"My neighbor walks his dog every morning, rain or shine.","exampleTranslation":"이웃은 날씨에 상관없이 매일 아침 개를 산책시킨다.","sense":"날씨에 상관없이"},{"wordId":21843,"answer":"rise and shine","form":"원형","example":"Every morning at camp, our leader wakes us up with a loud rise and shine.","exampleTranslation":"캠프에서는 매일 아침 지도자가 크게 일어나라고 외치며 우리를 깨운다.","sense":"일어나라"},{"wordId":21844,"answer":"run out of steam","form":"원형","example":"Our team started strong, but we might run out of steam in the second half.","exampleTranslation":"우리 팀은 출발이 좋았지만 후반전에 힘이 빠질지도 모른다.","sense":"힘이 다하다"},{"wordId":21845,"answer":"safe and sound","form":"원형","example":"The lost hikers were found safe and sound the next morning.","exampleTranslation":"길을 잃은 등산객들은 다음 날 아침 무사히 발견되었다.","sense":"무사히"},{"wordId":21846,"answer":"so to speak","form":"원형","example":"My grandmother is the glue of our family, so to speak.","exampleTranslation":"할머니는 말하자면 우리 가족을 이어 주는 접착제 같은 분이다.","sense":"말하자면"},{"wordId":21847,"answer":"stay on top of","form":"원형","example":"My mom uses an app to stay on top of all the family bills.","exampleTranslation":"엄마는 앱을 써서 가족의 모든 청구서를 빠짐없이 관리하신다.","sense":"놓치지 않고 관리하다"},{"wordId":21848,"answer":"stick out like a sore thumb","form":"원형","example":"If you wear a tuxedo to the picnic, you will stick out like a sore thumb.","exampleTranslation":"소풍에 턱시도를 입고 가면 혼자 확 튈 거야.","sense":"눈에 확 띄다"},{"wordId":21849,"answer":"take a toll","form":"원형","example":"The long commute began to take a toll on my sleep.","exampleTranslation":"긴 통근 시간이 내 수면에 악영향을 미치기 시작했다.","sense":"악영향을 미치다"},{"wordId":21850,"answer":"take the edge off","form":"원형","example":"A short walk outside can take the edge off your stress before the exam.","exampleTranslation":"시험 전에 밖에서 잠깐 걸으면 긴장이 누그러질 수 있다.","sense":"누그러뜨리다"},{"wordId":21851,"answer":"take the high road","form":"원형","example":"Our coach told us to take the high road when the other team was rude.","exampleTranslation":"상대 팀이 무례하게 굴자 코치는 우리에게 품위 있게 대응하라고 했다.","sense":"품위 있게 대응하다"},{"wordId":21852,"answer":"the real deal","form":"원형","example":"This leather bag looks cheap, but the shop owner says it is the real deal.","exampleTranslation":"이 가죽 가방은 싸 보이지만 가게 주인은 진품이라고 한다.","sense":"진품"},{"wordId":21853,"answer":"throw a curveball","form":"원형","example":"Just when we finished packing, the airline decided to throw a curveball and change our flight.","exampleTranslation":"짐을 다 싸자마자 항공사가 예상치 못하게 비행편을 바꿔 버렸다.","sense":"허를 찌르다"},{"wordId":21854,"answer":"through the roof","form":"원형","example":"After the heat wave, our electricity bill went through the roof.","exampleTranslation":"폭염이 지나고 나니 전기 요금이 천정부지로 올랐다.","sense":"천정부지로"},{"wordId":21855,"answer":"under wraps","form":"원형","example":"My parents kept their trip to Paris under wraps until the last day.","exampleTranslation":"부모님은 마지막 날까지 파리 여행을 비밀로 하셨다.","sense":"비밀에 부쳐진"},{"wordId":21856,"answer":"up to speed","form":"원형","example":"Can someone get the new nurse up to speed on our patients?","exampleTranslation":"누가 새 간호사에게 우리 환자들 상황을 알려 줄 수 있나요?","sense":"제대로 파악한"},{"wordId":21857,"answer":"up to par","form":"원형","example":"I have a cold, so my singing is not up to par tonight.","exampleTranslation":"감기에 걸려서 오늘 밤 내 노래는 평소만 못하다.","sense":"평소만큼 좋은"},{"wordId":21858,"answer":"wait and see","form":"원형","example":"The weather looks bad, so let us wait and see before we cancel the picnic.","exampleTranslation":"날씨가 안 좋아 보이니 소풍을 취소하기 전에 좀 두고 보자.","sense":"두고 보다"},{"wordId":21859,"answer":"wear many hats","form":"원형","example":"Parents often wear many hats as cooks, drivers, and teachers.","exampleTranslation":"부모들은 요리사, 운전사, 선생님 역할까지 1인 다역을 하는 경우가 많다.","sense":"여러 역할을 하다"},{"wordId":21860,"answer":"when in Rome","form":"원형","example":"Everyone here takes a long nap after lunch, so when in Rome, I will too.","exampleTranslation":"여기 사람들은 모두 점심 먹고 낮잠을 길게 자니 로마에 왔으면 로마법을 따라 나도 그럴 거다.","sense":"로마법을 따르라"},{"wordId":21861,"answer":"without a hitch","form":"원형","example":"Our move to the new apartment went without a hitch.","exampleTranslation":"새 아파트로의 이사는 아무 문제 없이 끝났다.","sense":"아무 문제 없이"},{"wordId":21862,"answer":"iron out the kinks","form":"원형","example":"The new bus schedule has problems, but the city plans to iron out the kinks.","exampleTranslation":"새 버스 시간표에 문제가 있지만 시에서 미비점을 다듬을 계획이다.","sense":"문제점을 해결하다"},{"wordId":21863,"answer":"a piece of the pie","form":"원형","example":"When the family sold the farm, every cousin wanted a piece of the pie.","exampleTranslation":"가족이 농장을 팔자 사촌들 모두가 자기 몫을 원했다.","sense":"몫"},{"wordId":21864,"answer":"on the back burner","form":"원형","example":"With a new baby at home, our trip to Japan is on the back burner.","exampleTranslation":"집에 갓난아기가 있어서 일본 여행은 뒤로 미뤄 두었다.","sense":"보류된"},{"wordId":21865,"answer":"bend the rules","form":"원형","example":"The bus driver decided to bend the rules and let my grandmother off near her house.","exampleTranslation":"버스 기사가 규칙을 융통성 있게 적용해서 할머니를 집 근처에 내려 드렸다.","sense":"규칙을 융통성 있게 적용하다"},{"wordId":21866,"answer":"beat yourself up","form":"원형","example":"You missed one easy shot, but you should not beat yourself up over it.","exampleTranslation":"쉬운 슛 하나 놓쳤다고 자책할 필요 없어.","sense":"자책하다"},{"wordId":21867,"answer":"cut ties","form":"원형","example":"After the company cheated us, we decided to cut ties with them.","exampleTranslation":"그 회사가 우리를 속인 뒤 우리는 그 회사와 관계를 끊기로 했다.","sense":"관계를 끊다"},{"wordId":21868,"answer":"dig in your heels","form":"원형","example":"You can dig in your heels, but the store will not give you a refund.","exampleTranslation":"아무리 버텨도 그 가게는 환불해 주지 않을 거야.","sense":"버티다"},{"wordId":21869,"answer":"do the trick","form":"원형","example":"If your phone screen is dirty, a soft cloth will do the trick.","exampleTranslation":"휴대폰 화면이 더러우면 부드러운 천으로 닦으면 해결된다.","sense":"효과가 있다"},{"wordId":21870,"answer":"drag your feet","form":"원형","example":"If you drag your feet, we will miss the start of the movie.","exampleTranslation":"네가 꾸물거리면 영화 시작 부분을 놓칠 거야.","sense":"꾸물거리다"},{"wordId":21871,"answer":"go downhill","form":"원형","example":"My old laptop began to go downhill after I dropped it.","exampleTranslation":"내 낡은 노트북은 떨어뜨린 뒤로 상태가 나빠지기 시작했다.","sense":"악화되다"},{"wordId":21872,"answer":"go south","form":"원형","example":"The picnic began to go south when the ants found our sandwiches.","exampleTranslation":"개미들이 우리 샌드위치를 발견하자 소풍이 틀어지기 시작했다.","sense":"틀어지다"},{"wordId":21873,"answer":"a soft spot for","form":"원형","example":"My grandfather has a soft spot for stray cats in the neighborhood.","exampleTranslation":"할아버지는 동네 길고양이들에게 약하시다.","sense":"특히 좋아함"},{"wordId":21874,"answer":"head in the clouds","form":"원형","example":"My son had his head in the clouds and missed his bus stop again.","exampleTranslation":"아들은 딴생각을 하다가 또 버스 정류장을 지나쳤다.","sense":"딴생각하는"},{"wordId":21875,"answer":"hit home","form":"원형","example":"The coach's words about teamwork seemed to hit home with the players.","exampleTranslation":"팀워크에 관한 코치의 말이 선수들에게 절실히 와닿은 것 같았다.","sense":"절실히 와닿다"},{"wordId":21876,"answer":"for the long haul","form":"원형","example":"This job is hard, but I am staying here for the long haul.","exampleTranslation":"이 일은 힘들지만 나는 오랫동안 여기 있을 거다.","sense":"오랫동안"},{"wordId":21877,"answer":"in the zone","form":"원형","example":"The pianist was in the zone and played for two hours straight.","exampleTranslation":"그 피아니스트는 완전히 몰입해서 두 시간 내내 연주했다.","sense":"완전히 몰입한"},{"wordId":21878,"answer":"in full swing","form":"원형","example":"In July, the beach season is in full swing and the hotels are full.","exampleTranslation":"칠월이면 해변 성수기가 한창이고 호텔이 꽉 찬다.","sense":"한창 진행 중인"},{"wordId":21879,"answer":"keep a low profile","form":"원형","example":"The famous actor tried to keep a low profile while he shopped downtown.","exampleTranslation":"그 유명 배우는 시내에서 쇼핑하는 동안 눈에 띄지 않게 다니려 했다.","sense":"눈에 띄지 않게 지내다"},{"wordId":21880,"answer":"knock it off","form":"원형","example":"Our dad told us to knock it off and stop throwing pillows.","exampleTranslation":"아빠는 우리에게 그만하고 베개 던지기를 멈추라고 하셨다.","sense":"그만해"},{"wordId":21881,"answer":"lend an ear","form":"원형","example":"My grandmother will always lend an ear when I have a bad day.","exampleTranslation":"힘든 날이면 할머니는 언제나 내 이야기를 들어 주신다.","sense":"이야기를 들어 주다"},{"wordId":21882,"answer":"make a mountain out of a molehill","form":"원형","example":"My mom tends to make a mountain out of a molehill when I come home late.","exampleTranslation":"내가 늦게 들어오면 엄마는 별것 아닌 일을 크게 부풀리시는 편이다.","sense":"크게 부풀리다"},{"wordId":21883,"answer":"make my day","form":"원형","example":"A free coffee from a stranger in line can really make my day.","exampleTranslation":"줄에서 낯선 사람이 사 준 공짜 커피 한 잔이 나를 정말 기쁘게 할 수 있다.","sense":"나를 정말 기쁘게 하다"},{"wordId":21884,"answer":"more than meets the eye","form":"원형","example":"This small museum has more than meets the eye, so take your time.","exampleTranslation":"이 작은 박물관에는 보이는 것 이상의 것이 있으니 천천히 둘러보세요.","sense":"보이는 것 이상"},{"wordId":21885,"answer":"off base","form":"원형","example":"The weather forecast was off base, and it snowed all day.","exampleTranslation":"일기 예보는 완전히 빗나갔고 하루 종일 눈이 왔다.","sense":"완전히 틀린"},{"wordId":21886,"answer":"out of my league","form":"원형","example":"The apartments in that neighborhood are out of my league.","exampleTranslation":"그 동네 아파트들은 나에게 너무 과분하다.","sense":"내게 과분한"},{"wordId":21887,"answer":"pick up the tab","form":"원형","example":"My boss offered to pick up the tab for the team lunch.","exampleTranslation":"사장님이 팀 점심 식사 비용을 대신 내겠다고 하셨다.","sense":"계산하다"},{"wordId":21888,"answer":"put your best foot forward","form":"원형","example":"When you meet your partner's parents, try to put your best foot forward.","exampleTranslation":"애인의 부모님을 만날 때는 좋은 인상을 주려고 노력해라.","sense":"좋은 인상을 주려 애쓰다"},{"wordId":21889,"answer":"rain on my parade","form":"원형","example":"I know the forecast says rain, but do not rain on my parade before the picnic.","exampleTranslation":"예보에 비 소식이 있는 건 알지만 소풍 전에 내 흥을 깨지 마.","sense":"흥을 깨다"},{"wordId":21890,"answer":"read the room","form":"원형","example":"A good teacher can read the room and know when students are tired.","exampleTranslation":"좋은 선생님은 분위기를 파악해서 학생들이 언제 지쳤는지 안다.","sense":"분위기를 파악하다"},{"wordId":21891,"answer":"right off the bat","form":"원형","example":"The new phone had problems right off the bat, so I returned it.","exampleTranslation":"새 휴대폰은 처음부터 바로 문제가 있어서 반품했다.","sense":"처음부터 바로"},{"wordId":21892,"answer":"run in the family","form":"원형","example":"My dad and grandpa both love to fish, so it must run in the family.","exampleTranslation":"아빠와 할아버지 모두 낚시를 좋아하시니 집안 내력인가 보다.","sense":"집안 내력이다"},{"wordId":21893,"answer":"saved by the bell","form":"원형","example":"Mom was checking my room when the doorbell rang, so I was saved by the bell.","exampleTranslation":"엄마가 내 방을 검사하던 중에 초인종이 울려서 간신히 위기를 모면했다.","sense":"간신히 위기를 모면한"},{"wordId":21894,"answer":"scratch the surface","form":"원형","example":"One week in Italy is enough to scratch the surface of its food culture.","exampleTranslation":"이탈리아에서 일주일은 그곳 음식 문화를 겉핥기 하기에 충분하다.","sense":"겉핥기만 하다"},{"wordId":21895,"answer":"see the light","form":"원형","example":"After his first speeding ticket, my brother began to see the light and slow down.","exampleTranslation":"첫 과속 딱지를 받고 나서야 동생은 정신을 차리고 속도를 줄이기 시작했다.","sense":"마침내 깨닫다"},{"wordId":21896,"answer":"set the record straight","form":"원형","example":"The actor posted a video to set the record straight about the rumors.","exampleTranslation":"그 배우는 소문에 대한 오해를 바로잡으려고 영상을 올렸다.","sense":"오해를 바로잡다"},{"wordId":21897,"answer":"sit tight","form":"원형","example":"The plane is still on the runway, so please sit tight for a few minutes.","exampleTranslation":"비행기가 아직 활주로에 있으니 몇 분만 그대로 기다려 주세요.","sense":"가만히 기다리다"},{"wordId":21898,"answer":"take a back seat","form":"원형","example":"During exam week, my part-time job has to take a back seat.","exampleTranslation":"시험 주간에는 아르바이트가 뒤로 밀려야 한다.","sense":"뒤로 물러나다"},{"wordId":21899,"answer":"take the cake","form":"원형","example":"Of all my brother's silly ideas, eating cat food for a bet might take the cake.","exampleTranslation":"동생의 엉뚱한 생각들 중에서도 내기로 고양이 사료를 먹은 게 단연 으뜸일 거다.","sense":"단연 으뜸이다"},{"wordId":21900,"answer":"the coast is clear","form":"원형","example":"Tell me when the coast is clear so I can wrap Mom's present.","exampleTranslation":"엄마 선물을 포장할 수 있게 보는 사람이 없으면 알려 줘.","sense":"보는 사람이 없다"},{"wordId":21901,"answer":"the devil is in the details","form":"원형","example":"Building a bookshelf seems easy, but the devil is in the details.","exampleTranslation":"책장 만들기는 쉬워 보이지만 작은 부분이 일을 그르칠 수 있다.","sense":"세부 사항이 중요하다"},{"wordId":21902,"answer":"the more the merrier","form":"원형","example":"Sure, you can bring your cousins to the barbecue, because the more the merrier.","exampleTranslation":"그럼, 사촌들 바비큐에 데려와도 돼, 많을수록 좋으니까.","sense":"많을수록 더 좋다"},{"wordId":21903,"answer":"turn the tables","form":"원형","example":"I lost the first two games of chess, but I hope to turn the tables tonight.","exampleTranslation":"체스 첫 두 판은 졌지만 오늘 밤에는 전세를 뒤집고 싶다.","sense":"전세를 뒤집다"},{"wordId":21904,"answer":"under your belt","form":"원형","example":"Once you have a few long road trips under your belt, driving gets easier.","exampleTranslation":"장거리 자동차 여행을 몇 번 해 보고 나면 운전이 더 쉬워진다.","sense":"이미 갖춘"},{"wordId":21905,"answer":"a walk in the park","form":"원형","example":"For my brother, fixing a flat bike tire is a walk in the park.","exampleTranslation":"우리 형에게 자전거 펑크를 고치는 건 식은 죽 먹기다.","sense":"식은 죽 먹기"},{"wordId":21906,"answer":"what goes around comes around","form":"원형","example":"He cheated in every game, and now nobody plays with him; what goes around comes around.","exampleTranslation":"그는 게임마다 반칙을 하더니 이제 아무도 함께 놀아 주지 않는다, 뿌린 대로 거두는 법이다.","sense":"인과응보"},{"wordId":21907,"answer":"with open arms","form":"원형","example":"The small village greeted the tired travelers with open arms.","exampleTranslation":"그 작은 마을은 지친 여행객들을 두 팔 벌려 맞이했다.","sense":"두 팔 벌려"},{"wordId":21908,"answer":"all in all","form":"원형","example":"The weather was cold, but all in all, the wedding was beautiful.","exampleTranslation":"날씨는 추웠지만 전체적으로 보면 결혼식은 아름다웠다.","sense":"전체적으로 보면"},{"wordId":21909,"answer":"all set","form":"원형","example":"I printed our boarding passes, so we are all set for tomorrow morning.","exampleTranslation":"탑승권을 인쇄해 뒀으니 내일 아침 준비는 다 됐다.","sense":"준비가 다 된"},{"wordId":21910,"answer":"as good as new","form":"원형","example":"My grandmother had knee surgery, and now she feels as good as new.","exampleTranslation":"할머니는 무릎 수술을 받으시고 이제 다 나은 듯 개운해하신다.","sense":"완전히 회복된"},{"wordId":21911,"answer":"as easy as pie","form":"원형","example":"With this app, sending money to a friend is as easy as pie.","exampleTranslation":"이 앱만 있으면 친구에게 돈을 보내는 건 누워서 떡 먹기다.","sense":"아주 쉬운"},{"wordId":21912,"answer":"at the end of my rope","form":"원형","example":"After three weeks of noisy construction next door, I am at the end of my rope.","exampleTranslation":"옆집 공사 소음이 삼 주째 이어지니 나는 더는 못 견디겠다.","sense":"한계에 다다른"},{"wordId":21913,"answer":"back in the day","form":"원형","example":"My grandfather says that back in the day, a movie ticket cost one dollar.","exampleTranslation":"할아버지는 예전에는 영화표가 일 달러였다고 하신다.","sense":"예전에는"},{"wordId":21914,"answer":"beside the point","form":"원형","example":"How much the tickets cost is beside the point; we promised to go.","exampleTranslation":"표값이 얼마인지는 중요하지 않아, 우리는 가기로 약속했잖아.","sense":"상관없는"},{"wordId":21915,"answer":"better safe than sorry","form":"원형","example":"I will bring an extra phone charger on the trip; better safe than sorry.","exampleTranslation":"여행에 휴대폰 충전기를 하나 더 챙겨 갈 거야, 후회하느니 조심하는 게 낫지.","sense":"조심하는 게 낫다"},{"wordId":21916,"answer":"burst my bubble","form":"원형","example":"I know the concert is sold out, but do not burst my bubble yet.","exampleTranslation":"콘서트가 매진된 건 알지만 아직 내 환상을 깨지는 마.","sense":"김새게 하다"},{"wordId":21917,"answer":"fly by the seat of your pants","form":"원형","example":"When your kids ask a hard question, you often fly by the seat of your pants.","exampleTranslation":"아이들이 어려운 질문을 하면 그때그때 감으로 대답할 때가 많다.","sense":"즉흥적으로 하다"},{"wordId":21918,"answer":"from the ground up","form":"원형","example":"My parents built their small farm from the ground up.","exampleTranslation":"우리 부모님은 작은 농장을 밑바닥부터 일구셨다.","sense":"밑바닥부터"},{"wordId":21919,"answer":"give it a rest","form":"원형","example":"You have complained about the weather all morning, so please give it a rest.","exampleTranslation":"아침 내내 날씨 불평을 했으니 이제 그만 좀 해.","sense":"그만 좀 해"},{"wordId":21920,"answer":"go to great lengths","form":"원형","example":"Some fans go to great lengths to meet their favorite singers.","exampleTranslation":"어떤 팬들은 좋아하는 가수를 만나려고 갖은 애를 쓴다.","sense":"갖은 애를 쓰다"},{"wordId":21921,"answer":"green with envy","form":"원형","example":"My sister was green with envy when I got tickets to the final game.","exampleTranslation":"내가 결승전 표를 구하자 언니는 몹시 샘을 냈다.","sense":"몹시 샘이 나는"},{"wordId":21922,"answer":"hang by a thread","form":"원형","example":"After two players got hurt, our chances of winning hang by a thread.","exampleTranslation":"선수 두 명이 다치면서 우리 팀의 우승 가능성은 위태롭다.","sense":"위태롭다"},{"wordId":21923,"answer":"hit or miss","form":"원형","example":"The internet at this cafe is hit or miss, so download your files at home.","exampleTranslation":"이 카페 인터넷은 들쭉날쭉하니 파일은 집에서 내려받아라.","sense":"들쭉날쭉한"},{"wordId":21924,"answer":"in a jam","form":"원형","example":"My car broke down on the highway, and I was really in a jam.","exampleTranslation":"고속도로에서 차가 고장 나서 정말 난처했다.","sense":"곤경에 처한"},{"wordId":21925,"answer":"jump on the bandwagon","form":"원형","example":"My grandparents decided to jump on the bandwagon and buy smartphones.","exampleTranslation":"조부모님은 유행을 따라 스마트폰을 사기로 하셨다.","sense":"유행에 편승하다"},{"wordId":21926,"answer":"like a kid in a candy store","form":"원형","example":"At the toy museum, my husband was like a kid in a candy store.","exampleTranslation":"장난감 박물관에서 남편은 신나서 어쩔 줄 몰랐다.","sense":"몹시 신이 난"},{"wordId":21927,"answer":"a lost cause","form":"원형","example":"My old printer jams every day, so trying to fix it is a lost cause.","exampleTranslation":"낡은 프린터가 매일 걸리니 고치려는 건 가망 없는 일이다.","sense":"가망 없는 일"},{"wordId":21928,"answer":"make a scene","form":"원형","example":"My son started to make a scene when I said no to ice cream.","exampleTranslation":"아이스크림은 안 된다고 하자 아들이 난리를 치기 시작했다.","sense":"소란을 피우다"},{"wordId":21929,"answer":"mind your own business","form":"원형","example":"Mind your own business and stop reading my text messages.","exampleTranslation":"참견 말고 내 문자 메시지 그만 훔쳐봐.","sense":"남의 일에 참견하지 마"},{"wordId":21930,"answer":"on the fly","form":"원형","example":"The singer forgot the lyrics, so she changed the words on the fly.","exampleTranslation":"가수가 가사를 잊어버려서 즉석에서 가사를 바꿔 불렀다.","sense":"즉석에서"},{"wordId":21931,"answer":"pull the plug","form":"원형","example":"The TV station decided to pull the plug on the cooking show after one season.","exampleTranslation":"그 방송국은 요리 프로그램을 한 시즌 만에 중단하기로 했다.","sense":"중단시키다"},{"wordId":21932,"answer":"rough around the edges","form":"원형","example":"The new waiter is rough around the edges, but he is very kind.","exampleTranslation":"새 웨이터는 다듬어지지 않은 면이 있지만 아주 친절하다.","sense":"다듬어지지 않은"},{"wordId":21933,"answer":"run-of-the-mill","form":"원형","example":"It looked like a run-of-the-mill cafe, but the coffee was amazing.","exampleTranslation":"평범한 카페처럼 보였지만 커피는 놀라울 만큼 맛있었다.","sense":"평범한"},{"wordId":21934,"answer":"smooth sailing","form":"원형","example":"After the first difficult week at my new job, it was smooth sailing.","exampleTranslation":"새 직장에서 힘들었던 첫 주가 지나자 모든 게 순조로웠다.","sense":"순조로운 진행"},{"wordId":21935,"answer":"sour grapes","form":"원형","example":"My neighbor calls my new car ugly, but I think it is sour grapes.","exampleTranslation":"이웃은 내 새 차가 못생겼다고 하지만 나는 그게 여우의 신 포도 같은 말이라고 생각한다.","sense":"여우의 신 포도"},{"wordId":21936,"answer":"on the spur of the moment","form":"원형","example":"My parents bought a puppy on the spur of the moment last weekend.","exampleTranslation":"부모님은 지난 주말에 충동적으로 강아지를 사 오셨다.","sense":"충동적으로"},{"wordId":21937,"answer":"one day at a time","form":"원형","example":"Learning a new language is hard, so just take it one day at a time.","exampleTranslation":"새 언어를 배우는 건 어려우니 하루하루 차근차근 해 나가라.","sense":"하루하루 차근차근"},{"wordId":21938,"answer":"the name of the game","form":"원형","example":"When you train a puppy, consistency is the name of the game.","exampleTranslation":"강아지를 훈련할 때는 일관성이 가장 중요하다.","sense":"가장 중요한 것"},{"wordId":21939,"answer":"to make matters worse","form":"원형","example":"We got lost on the way, and to make matters worse, my phone died.","exampleTranslation":"우리는 가는 길에 길을 잃었고 설상가상으로 내 휴대폰 배터리도 나갔다.","sense":"설상가상으로"},{"wordId":21940,"answer":"worth a shot","form":"원형","example":"The concert is sold out, but asking at the door is worth a shot.","exampleTranslation":"콘서트는 매진됐지만 입구에서 물어볼 만은 하다.","sense":"시도해 볼 만한"},{"wordId":21941,"answer":"you name it","form":"원형","example":"My grandmother can cook anything, soup, noodles, cakes, you name it.","exampleTranslation":"할머니는 수프든 국수든 케이크든 뭐든지 요리하실 수 있다.","sense":"뭐든지"},{"wordId":21942,"answer":"a nest egg","form":"원형","example":"My parents opened a savings account to give each of us a nest egg.","exampleTranslation":"부모님은 우리에게 각자 목돈을 마련해 주시려고 적금 통장을 만드셨다.","sense":"목돈"},{"wordId":21943,"answer":"pay the price","form":"원형","example":"I skipped breakfast to save time, and I had to pay the price at noon.","exampleTranslation":"시간을 아끼려고 아침을 걸렀더니 정오쯤 그 대가를 치러야 했다.","sense":"대가를 치르다"},{"wordId":21944,"answer":"for a rainy day","form":"원형","example":"My grandmother keeps some cash in a jar for a rainy day.","exampleTranslation":"할머니는 어려울 때를 대비해 병에 현금을 조금 넣어 두신다.","sense":"어려울 때를 대비해"},{"wordId":21945,"answer":"a pretty penny","form":"원형","example":"Fixing the roof after the storm cost us a pretty penny.","exampleTranslation":"폭풍이 지나간 뒤 지붕을 고치는 데 큰돈이 들었다.","sense":"큰돈"},{"wordId":21946,"answer":"paycheck to paycheck","form":"원형","example":"Many young workers in big cities live paycheck to paycheck.","exampleTranslation":"대도시의 많은 젊은 직장인들이 근근이 월급으로 버틴다.","sense":"근근이 월급으로 버티며"},{"wordId":21947,"answer":"two left feet","form":"원형","example":"My husband says he has two left feet, so he never dances at weddings.","exampleTranslation":"남편은 자기가 몸치라서 결혼식에서 절대 춤을 추지 않는다고 한다.","sense":"몸치"},{"wordId":21948,"answer":"a bundle of nerves","form":"원형","example":"My little sister was a bundle of nerves before her piano recital.","exampleTranslation":"여동생은 피아노 발표회 전에 몹시 긴장해 있었다.","sense":"몹시 긴장한 사람"},{"wordId":21949,"answer":"beside myself","form":"원형","example":"I was beside myself with joy when I heard the good news.","exampleTranslation":"좋은 소식을 듣고 나는 기뻐서 어쩔 줄 몰랐다.","sense":"어쩔 줄 모르는"},{"wordId":21950,"answer":"blow a fuse","form":"원형","example":"My boss might blow a fuse if we miss another delivery date.","exampleTranslation":"배송 날짜를 또 놓치면 사장님이 폭발하실지도 모른다.","sense":"몹시 화를 내다"},{"wordId":21951,"answer":"a chip on your shoulder","form":"원형","example":"If you have a chip on your shoulder, people will not want to work with you.","exampleTranslation":"네가 늘 시비조로 굴면 사람들이 너와 일하고 싶어 하지 않을 거야.","sense":"시비조"},{"wordId":21952,"answer":"fly off the handle","form":"원형","example":"My dad used to fly off the handle when we left the lights on.","exampleTranslation":"아빠는 우리가 불을 켜 두면 버럭 화를 내곤 하셨다.","sense":"버럭 화를 내다"},{"wordId":21953,"answer":"keep a straight face","form":"원형","example":"My little brother told a terrible lie, and I tried to keep a straight face.","exampleTranslation":"남동생이 엉터리 거짓말을 해서 나는 웃음을 참으려고 애썼다.","sense":"웃음을 참다"},{"wordId":21954,"answer":"walking on air","form":"원형","example":"The kids were walking on air after they met their favorite soccer player.","exampleTranslation":"아이들은 좋아하는 축구 선수를 만난 뒤 기분이 날아갈 듯했다.","sense":"기분이 날아갈 듯한"},{"wordId":21955,"answer":"think on your feet","form":"원형","example":"As a tour guide, you must think on your feet when plans change.","exampleTranslation":"여행 가이드라면 계획이 바뀔 때 순발력 있게 대처해야 한다.","sense":"순발력 있게 대처하다"},{"wordId":21956,"answer":"before you know it","form":"원형","example":"If you start saving now, you will have enough money before you know it.","exampleTranslation":"지금 저축을 시작하면 어느새 돈이 충분히 모일 거야.","sense":"어느새"},{"wordId":21957,"answer":"ahead of the curve","form":"원형","example":"My grandmother was ahead of the curve and shopped online years before her friends.","exampleTranslation":"할머니는 시대를 앞서가셔서 친구분들보다 몇 년 먼저 온라인 쇼핑을 하셨다.","sense":"시대를 앞서가는"},{"wordId":21958,"answer":"better luck next time","form":"원형","example":"You missed the bus by one minute, but better luck next time.","exampleTranslation":"일 분 차이로 버스를 놓쳤지만 다음엔 잘될 거야.","sense":"다음엔 잘될 거야"},{"wordId":21959,"answer":"make the grade","form":"원형","example":"My essay needs more work if it is going to make the grade.","exampleTranslation":"내 에세이가 합격점을 받으려면 좀 더 다듬어야 한다.","sense":"합격점을 받다"},{"wordId":21960,"answer":"miss the mark","form":"원형","example":"The new movie had great actors, but the story seemed to miss the mark.","exampleTranslation":"새 영화는 배우들은 훌륭했지만 줄거리가 기대에 못 미쳤다.","sense":"기대에 못 미치다"},{"wordId":21961,"answer":"back to basics","form":"원형","example":"Our team lost five games, so the coach says it is back to basics now.","exampleTranslation":"우리 팀이 다섯 경기를 졌으니 코치는 이제 기본으로 돌아가자고 한다.","sense":"기본으로 돌아가기"},{"wordId":21962,"answer":"go up in smoke","form":"원형","example":"If the airline strike continues, our honeymoon plans will go up in smoke.","exampleTranslation":"항공사 파업이 계속되면 우리 신혼여행 계획은 물거품이 될 거다.","sense":"물거품이 되다"},{"wordId":21963,"answer":"a slam dunk","form":"원형","example":"With the best players on our side, winning tonight looks like a slam dunk.","exampleTranslation":"최고의 선수들이 우리 편이니 오늘 밤 승리는 따 놓은 당상 같다.","sense":"따 놓은 당상"},{"wordId":21964,"answer":"fall on deaf ears","form":"원형","example":"My warnings about the icy roads seemed to fall on deaf ears.","exampleTranslation":"길이 얼었다는 내 경고는 무시당하는 것 같았다.","sense":"무시당하다"},{"wordId":21965,"answer":"keep me posted","form":"원형","example":"Have a safe flight, and keep me posted when you land in Tokyo.","exampleTranslation":"조심히 가고, 도쿄에 도착하면 소식 알려 줘.","sense":"소식을 알려 줘"},{"wordId":21966,"answer":"lost in translation","form":"원형","example":"The meaning of the old song was lost in translation for the foreign fans.","exampleTranslation":"그 옛 노래의 의미는 외국 팬들에게 전달되는 과정에서 사라져 버렸다.","sense":"번역 중 의미가 사라진"},{"wordId":21967,"answer":"to put it mildly","form":"원형","example":"The service at the restaurant was slow, to put it mildly.","exampleTranslation":"그 식당의 서비스는 좋게 말해서 느렸다.","sense":"좋게 말해서"},{"wordId":21968,"answer":"word gets around","form":"원형","example":"If you open a good bakery, word gets around and customers come.","exampleTranslation":"좋은 빵집을 열면 소문이 퍼져서 손님들이 온다.","sense":"소문이 퍼지다"},{"wordId":21969,"answer":"hold your tongue","form":"원형","example":"When your boss is angry, it is better to hold your tongue.","exampleTranslation":"상사가 화가 났을 때는 말을 삼가는 게 낫다.","sense":"말을 삼가다"},{"wordId":21970,"answer":"add insult to injury","form":"원형","example":"The waiter spilled soup on me and, to add insult to injury, forgot my order.","exampleTranslation":"웨이터가 나에게 수프를 쏟더니 설상가상으로 내 주문까지 잊어버렸다.","sense":"설상가상으로 만들다"},{"wordId":21971,"answer":"meet halfway","form":"원형","example":"My son wants to stay up until midnight, so we decided to meet halfway at ten.","exampleTranslation":"아들이 자정까지 안 자겠다고 해서 우리는 열 시로 타협하기로 했다.","sense":"타협하다"},{"wordId":21972,"answer":"a match made in heaven","form":"원형","example":"My grandparents have been married for sixty years, a match made in heaven.","exampleTranslation":"조부모님은 결혼하신 지 육십 년이 된 천생연분이시다.","sense":"천생연분"},{"wordId":21973,"answer":"birds of a feather","form":"원형","example":"My cousins both collect old coins, so they are birds of a feather.","exampleTranslation":"내 사촌들은 둘 다 옛날 동전을 모으니 끼리끼리 노는 사이다.","sense":"유유상종"},{"wordId":21974,"answer":"a fair-weather friend","form":"원형","example":"He only calls me when he needs money, so he is a fair-weather friend.","exampleTranslation":"그는 돈이 필요할 때만 나한테 전화하니 필요할 때만 찾는 친구다.","sense":"좋을 때만 친구"},{"wordId":21975,"answer":"play hard to get","form":"원형","example":"My cat likes to play hard to get when I want to hold her.","exampleTranslation":"우리 고양이는 내가 안으려고 하면 일부러 관심 없는 척한다.","sense":"일부러 관심 없는 척하다"},{"wordId":21976,"answer":"make up your mind","form":"원형","example":"The waiter is coming back, so please make up your mind about dessert.","exampleTranslation":"웨이터가 다시 오고 있으니 디저트를 뭘로 할지 정해.","sense":"마음을 정하다"},{"wordId":21977,"answer":"on the line","form":"원형","example":"The coach knows his job is on the line this season.","exampleTranslation":"코치는 이번 시즌에 자기 자리가 걸려 있다는 걸 안다.","sense":"걸려 있는"},{"wordId":21978,"answer":"go either way","form":"원형","example":"The vote on the new park is close, and it could go either way.","exampleTranslation":"새 공원에 관한 투표는 접전이라 결과를 알 수 없다.","sense":"결과를 알 수 없다"},{"wordId":21979,"answer":"the jury is still out","form":"원형","example":"My brother loves his new electric car, but the jury is still out for me.","exampleTranslation":"형은 새 전기차를 아주 좋아하지만 나는 아직 판단하기 이르다.","sense":"아직 결론이 나지 않았다"},{"wordId":21980,"answer":"draw the line","form":"원형","example":"My kids can have candy on weekends, but I draw the line at soda.","exampleTranslation":"아이들이 주말에 사탕은 먹어도 되지만 탄산음료는 안 된다고 선을 긋는다.","sense":"선을 긋다"},{"wordId":21981,"answer":"out of my element","form":"원형","example":"I grew up in the city, so I am out of my element on a farm.","exampleTranslation":"나는 도시에서 자라서 농장에서는 물 밖에 나온 듯 어색하다.","sense":"내 영역이 아닌"},{"wordId":21982,"answer":"home sweet home","form":"원형","example":"My grandmother put down her suitcase, smiled, and said, \\"Home sweet home.\\"","exampleTranslation":"할머니는 여행 가방을 내려놓고 웃으며 역시 집이 최고라고 하셨다.","sense":"역시 집이 최고"},{"wordId":21983,"answer":"make yourself at home","form":"원형","example":"Please make yourself at home and help yourself to anything in the fridge.","exampleTranslation":"편하게 계시고 냉장고에 있는 건 뭐든 드세요.","sense":"편하게 계세요"},{"wordId":21984,"answer":"the daily grind","form":"원형","example":"My dad plays the guitar every night to escape the daily grind.","exampleTranslation":"아빠는 단조롭고 고된 일상에서 벗어나려고 매일 밤 기타를 치신다.","sense":"고된 일상"},{"wordId":21985,"answer":"all over the place","form":"원형","example":"After the party, there were paper cups all over the place.","exampleTranslation":"파티가 끝난 뒤 종이컵이 여기저기에 널려 있었다.","sense":"여기저기에"},{"wordId":21986,"answer":"bigger fish to fry","form":"원형","example":"The coach ignored the small mistakes because he had bigger fish to fry.","exampleTranslation":"코치는 더 중요한 문제가 있어서 작은 실수들은 그냥 넘겼다.","sense":"더 큰 문제"},{"wordId":21987,"answer":"cream of the crop","form":"원형","example":"Only the cream of the crop get to play in the national orchestra.","exampleTranslation":"최고 중의 최고만 국립 오케스트라에서 연주할 수 있다.","sense":"최고 중의 최고"},{"wordId":21988,"answer":"in one piece","form":"원형","example":"My son came back from his first camping trip in one piece.","exampleTranslation":"아들은 첫 캠핑 여행에서 다친 데 없이 무사히 돌아왔다.","sense":"무사히"},{"wordId":21989,"answer":"out like a light","form":"원형","example":"After swimming all afternoon, the kids were out like a light by eight.","exampleTranslation":"오후 내내 수영한 아이들은 여덟 시가 되자 곧바로 곯아떨어졌다.","sense":"곧바로 곯아떨어진"},{"wordId":21990,"answer":"like clockwork","form":"원형","example":"My neighbor waters his garden at six every evening like clockwork.","exampleTranslation":"이웃은 매일 저녁 여섯 시에 시계처럼 정확하게 정원에 물을 준다.","sense":"시계처럼 정확하게"},{"wordId":21991,"answer":"a tough act to follow","form":"원형","example":"The first singer was amazing, so she was a tough act to follow.","exampleTranslation":"첫 번째 가수가 정말 대단해서 뒤이어 무대에 서기 어려웠다.","sense":"뒤따르기 어려운 대단한 사람"},{"wordId":21992,"answer":"a far cry from","form":"원형","example":"The hotel was a far cry from the pictures on the website.","exampleTranslation":"그 호텔은 웹사이트 사진과는 전혀 달랐다.","sense":"전혀 다른"},{"wordId":21993,"answer":"my hands are tied","form":"원형","example":"I wish I could change your seat, but my hands are tied on this full flight.","exampleTranslation":"좌석을 바꿔 드리고 싶지만 이번 비행기는 만석이라 어쩔 수가 없어요.","sense":"어쩔 수 없다"},{"wordId":21994,"answer":"like the back of my hand","form":"원형","example":"As a taxi driver, I know this city like the back of my hand.","exampleTranslation":"택시 기사라서 나는 이 도시를 손바닥 보듯 훤히 안다.","sense":"손바닥 보듯 훤히"},{"wordId":21995,"answer":"kick the habit","form":"원형","example":"My sister bit her nails for years, but she finally managed to kick the habit.","exampleTranslation":"언니는 몇 년 동안 손톱을 물어뜯었지만 마침내 그 습관을 끊었다.","sense":"습관을 끊다"},{"wordId":21996,"answer":"old habits die hard","form":"원형","example":"My mom still cuts my sandwiches in half; old habits die hard.","exampleTranslation":"엄마는 아직도 내 샌드위치를 반으로 잘라 주신다, 오래된 습관은 고치기 어렵다.","sense":"오래된 습관은 고치기 어렵다"},{"wordId":21997,"answer":"turn heads","form":"원형","example":"Your shiny red sports car will turn heads in this quiet neighborhood.","exampleTranslation":"네 반짝이는 빨간 스포츠카는 이 조용한 동네에서 시선을 끌 거야.","sense":"시선을 끌다"},{"wordId":21998,"answer":"the talk of the town","form":"원형","example":"After the mayor's dog won the show, it became the talk of the town.","exampleTranslation":"시장의 개가 대회에서 우승한 뒤 그 일은 동네의 화제가 되었다.","sense":"동네에서 화제인 것"},{"wordId":21999,"answer":"in the spotlight","form":"원형","example":"My little brother loves being in the spotlight at family parties.","exampleTranslation":"내 남동생은 가족 모임에서 주목받는 걸 아주 좋아한다.","sense":"주목을 받는"},{"wordId":22000,"answer":"some shut-eye","form":"원형","example":"The baby finally fell asleep, so now we can get some shut-eye too.","exampleTranslation":"아기가 마침내 잠들었으니 이제 우리도 눈 좀 붙일 수 있다.","sense":"눈 좀 붙이기"},{"wordId":22001,"answer":"downward dog","form":"원형","example":"Our teacher asked us to rest in downward dog between each set of lunges.","exampleTranslation":"선생님은 매 런지 세트 사이에 다운독 자세로 쉬라고 하셨다.","sense":"다운독 자세"},{"wordId":22003,"answer":"warrior pose","form":"원형","example":"Keep your front knee directly above your ankle in warrior pose.","exampleTranslation":"전사 자세에서는 앞 무릎을 발목 바로 위에 두세요.","sense":"전사 자세"},{"wordId":22004,"answer":"tree pose","form":"원형","example":"My daughter can stand in tree pose longer than anyone in our class.","exampleTranslation":"우리 딸은 우리 반 누구보다 나무 자세로 오래 서 있을 수 있다.","sense":"나무 자세"},{"wordId":22005,"answer":"side plank","form":"원형","example":"At first, I could only hold a side plank for twenty seconds.","exampleTranslation":"처음에 나는 사이드 플랭크를 이십 초밖에 버티지 못했다.","sense":"사이드 플랭크"},{"wordId":22006,"answer":"reformers","form":"복수형","example":"Our gym bought two new reformers for the Pilates room last month.","exampleTranslation":"우리 헬스장은 지난달 필라테스실에 쓸 새 리포머 기구 두 대를 샀다.","sense":"리포머 기구"},{"wordId":22007,"answer":"mat class","form":"원형","example":"The mat class on Saturday morning is perfect for complete beginners.","exampleTranslation":"토요일 아침 매트 수업은 완전 초보자에게 딱 맞다.","sense":"매트 수업"},{"wordId":22008,"answer":"inhaled","form":"과거형","example":"I inhaled deeply before jumping into the cold lake yesterday morning.","exampleTranslation":"나는 어제 아침 차가운 호수에 뛰어들기 전에 숨을 깊이 들이마셨다.","sense":"들이마시다"},{"wordId":22009,"answer":"exhaling","form":"-ing형","example":"Try exhaling slowly when you feel nervous before a job interview.","exampleTranslation":"면접 전에 긴장될 때는 천천히 숨을 내쉬어 보세요.","sense":"내쉬다"},{"wordId":22010,"answer":"engage your core","form":"원형","example":"Engage your core when you lift heavy boxes to protect your back.","exampleTranslation":"무거운 상자를 들 때는 허리를 보호하도록 코어에 힘을 주세요.","sense":"코어에 힘주다"},{"wordId":22011,"answer":"flexibility","form":"원형","example":"Swimming every week has given my grandmother more flexibility in her shoulders.","exampleTranslation":"매주 하는 수영 덕분에 할머니는 어깨 유연성이 더 좋아지셨다.","sense":"유연성"},{"wordId":22012,"answer":"yoga block","form":"원형","example":"I sit on a yoga block when my knees hurt during meditation.","exampleTranslation":"명상할 때 무릎이 아프면 나는 요가 블록 위에 앉는다.","sense":"요가 블록"},{"wordId":22013,"answer":"yoga strap","form":"원형","example":"I forgot my yoga strap, so I used a belt instead.","exampleTranslation":"요가 스트랩을 깜빡해서 대신 벨트를 썼다.","sense":"요가 스트랩"},{"wordId":22014,"answer":"Pilates instructor","form":"원형","example":"My sister became a Pilates instructor after she hurt her back dancing.","exampleTranslation":"언니는 춤추다 허리를 다친 뒤 필라테스 강사가 되었다.","sense":"필라테스 강사"},{"wordId":22015,"answer":"drop-in class","form":"원형","example":"I usually take a drop-in class when I travel to a new city.","exampleTranslation":"나는 새로운 도시로 여행 가면 보통 1회 수업을 듣는다.","sense":"1회 수업"},{"wordId":22016,"answer":"ten-class pass","form":"원형","example":"My friend gave me a ten-class pass for my birthday this year.","exampleTranslation":"친구가 올해 내 생일 선물로 10회 수강권을 줬다.","sense":"10회 수강권"},{"wordId":22017,"answer":"hot yoga","form":"원형","example":"My brother felt dizzy during his first hot yoga session last week.","exampleTranslation":"남동생은 지난주 첫 핫요가 수업 중에 어지러움을 느꼈다.","sense":"핫요가"},{"wordId":22018,"answer":"guided meditation","form":"원형","example":"I listen to a short guided meditation on my phone before bed.","exampleTranslation":"나는 자기 전에 휴대폰으로 짧은 안내 명상을 듣는다.","sense":"안내 명상"},{"wordId":22019,"answer":"breathwork","form":"원형","example":"A little breathwork before a big exam can really calm your nerves.","exampleTranslation":"큰 시험 전에 잠깐 호흡 수련을 하면 긴장이 정말 풀릴 수 있다.","sense":"호흡 수련"},{"wordId":22020,"answer":"modified","form":"과거형","example":"Yesterday the teacher modified the plank for me because of my sore wrist.","exampleTranslation":"어제 선생님은 내 손목이 아파서 플랭크 동작을 쉽게 바꿔 주셨다.","sense":"변형하다"},{"wordId":22021,"answer":"modifications","form":"복수형","example":"She gave us two modifications for the jumping exercises to protect our knees.","exampleTranslation":"그녀는 무릎을 보호하도록 점프 운동의 변형 동작 두 가지를 알려 주었다.","sense":"변형 동작"},{"wordId":22022,"answer":"hold the pose","form":"원형","example":"Smile and hold the pose while I take the photo.","exampleTranslation":"내가 사진을 찍는 동안 웃으면서 자세를 유지해.","sense":"자세 유지하다"},{"wordId":22023,"answer":"alignment","form":"원형","example":"Good alignment in your squat protects your knees from injury.","exampleTranslation":"스쿼트할 때 바른 정렬은 무릎을 부상에서 보호해 준다.","sense":"정렬"},{"wordId":22024,"answer":"tight hamstrings","form":"원형","example":"Runners often complain about tight hamstrings after a long race.","exampleTranslation":"달리기 선수들은 긴 경주 뒤에 햄스트링이 뻣뻣하다고 자주 불평한다.","sense":"뻣뻣한 햄스트링"},{"wordId":22025,"answer":"spines","form":"복수형","example":"The doctor showed us pictures of healthy spines and injured ones.","exampleTranslation":"의사는 건강한 척추와 다친 척추 사진을 우리에게 보여 주었다.","sense":"척추"},{"wordId":22026,"answer":"improve my posture","form":"원형","example":"I bought a new office chair to improve my posture at work.","exampleTranslation":"나는 직장에서 자세를 바르게 하려고 새 사무용 의자를 샀다.","sense":"자세 교정하다"},{"wordId":22027,"answer":"deep stretch","form":"원형","example":"A deep stretch after a long flight helps my back feel better.","exampleTranslation":"긴 비행 후에 깊은 스트레칭을 하면 허리가 한결 나아진다.","sense":"깊은 스트레칭"},{"wordId":22028,"answer":"core strength","form":"원형","example":"Good core strength makes carrying heavy groceries much easier.","exampleTranslation":"코어 근력이 좋으면 무거운 장바구니를 드는 게 훨씬 쉬워진다.","sense":"코어 근력"},{"wordId":22029,"answer":"final relaxation","form":"원형","example":"My favorite part of every class is the final relaxation at the end.","exampleTranslation":"모든 수업에서 내가 가장 좋아하는 부분은 끝의 마무리 이완이다.","sense":"마무리 이완"},{"wordId":22030,"answer":"bend your knees","form":"원형","example":"Always bend your knees when you pick up something heavy from the floor.","exampleTranslation":"바닥에서 무거운 것을 들 때는 항상 무릎을 굽히세요.","sense":"무릎 굽히다"},{"wordId":22031,"answer":"sun salutation","form":"원형","example":"I do one sun salutation every morning to wake up my body.","exampleTranslation":"나는 매일 아침 몸을 깨우려고 태양 경배 자세를 한 번 한다.","sense":"태양 경배"},{"wordId":22032,"answer":"bridge pose","form":"원형","example":"My physical therapist told me to practice bridge pose for my back pain.","exampleTranslation":"물리 치료사가 허리 통증 때문에 브리지 자세를 연습하라고 했다.","sense":"브리지 자세"},{"wordId":22033,"answer":"cobra pose","form":"원형","example":"My back felt much better after a few gentle rounds of cobra pose.","exampleTranslation":"코브라 자세를 몇 번 부드럽게 하고 나니 허리가 훨씬 나아졌다.","sense":"코브라 자세"},{"wordId":22034,"answer":"grip socks","form":"원형","example":"I bought three pairs of grip socks before my first Pilates class.","exampleTranslation":"나는 첫 필라테스 수업 전에 미끄럼 방지 양말을 세 켤레 샀다.","sense":"미끄럼 방지 양말"},{"wordId":22035,"answer":"yoga studio","form":"원형","example":"My aunt runs a small yoga studio in her hometown.","exampleTranslation":"이모는 고향에서 작은 요가원을 운영한다.","sense":"요가원"},{"wordId":22036,"answer":"reserve a spot","form":"원형","example":"Members can reserve a spot in the spin class through the app.","exampleTranslation":"회원은 앱으로 스피닝 수업 자리를 예약할 수 있다.","sense":"자리 예약하다"},{"wordId":22037,"answer":"late cancel","form":"원형","example":"I had to make a late cancel because my train was delayed.","exampleTranslation":"기차가 연착되어서 나는 어쩔 수 없이 늦은 취소를 했다.","sense":"늦은 취소"},{"wordId":22038,"answer":"go at your own pace","form":"원형","example":"There is no deadline for this course, so feel free to go at your own pace.","exampleTranslation":"이 강좌에는 마감이 없으니 편하게 자기 속도대로 하세요.","sense":"자기 속도대로"},{"wordId":22039,"answer":"listen to your body","form":"원형","example":"When you are sick, listen to your body and get plenty of rest.","exampleTranslation":"아플 때는 몸의 신호에 귀 기울이고 푹 쉬세요.","sense":"몸에 귀 기울이다"},{"wordId":22040,"answer":"shoulder blades","form":"원형","example":"My massage therapist found a tight knot between my shoulder blades.","exampleTranslation":"마사지사가 내 날개뼈 사이에서 뭉친 곳을 찾아냈다.","sense":"날개뼈"},{"wordId":22041,"answer":"neutral pelvis","form":"원형","example":"Finding a neutral pelvis was hard for me in my first Pilates lesson.","exampleTranslation":"첫 필라테스 수업에서 중립 골반을 찾는 게 나에게는 어려웠다.","sense":"중립 골반"},{"wordId":22042,"answer":"one vertebra at a time","form":"원형","example":"Lower your back to the mat one vertebra at a time.","exampleTranslation":"척추 마디 하나씩 등을 매트로 내리세요.","sense":"척추 마디 하나씩"},{"wordId":22043,"answer":"most limber","form":"최상급","example":"My grandmother is the most limber person in her swimming group.","exampleTranslation":"우리 할머니는 수영 모임에서 몸이 가장 유연한 분이다.","sense":"유연한","alts":["most flexible"]},{"wordId":22044,"answer":"private session","form":"원형","example":"My tennis coach offers a private session every Sunday afternoon.","exampleTranslation":"우리 테니스 코치는 매주 일요일 오후에 개인 레슨을 한다.","sense":"개인 레슨"},{"wordId":22045,"answer":"most mindful","form":"최상급","example":"Of all my coworkers, Ken is the most mindful of other people's time.","exampleTranslation":"내 동료들 중에서 켄이 다른 사람의 시간을 가장 신경 쓴다.","sense":"의식하는"},{"wordId":22046,"answer":"more toned","form":"비교급","example":"Her legs became more toned after a summer of hiking.","exampleTranslation":"여름 내내 등산을 한 뒤 그녀의 다리가 더 탄탄해졌다.","sense":"탄탄한"},{"wordId":22047,"answer":"headstands","form":"복수형","example":"The kids did headstands on the grass at the picnic yesterday.","exampleTranslation":"어제 소풍에서 아이들이 잔디 위에서 물구나무서기를 했다.","sense":"물구나무서기"},{"wordId":22048,"answer":"mat cleaner","form":"원형","example":"The gym ran out of mat cleaner, so I used wet wipes.","exampleTranslation":"헬스장에 매트 클리너가 떨어져서 나는 물티슈를 썼다.","sense":"매트 클리너"},{"wordId":22049,"answer":"twists","form":"복수형","example":"Our teacher added a few seated twists at the end of class.","exampleTranslation":"선생님은 수업 마지막에 앉아서 하는 비틀기 동작 몇 개를 추가했다.","sense":"비틀기 동작"},{"wordId":22050,"answer":"pigeon pose","form":"원형","example":"After long bike rides, I stretch my hips in pigeon pose.","exampleTranslation":"나는 자전거를 오래 탄 뒤에 비둘기 자세로 엉덩이를 스트레칭한다.","sense":"비둘기 자세"},{"wordId":22051,"answer":"first-time buyer","form":"원형","example":"The bank offers a lower interest rate to every first-time buyer this year.","exampleTranslation":"그 은행은 올해 모든 생애 첫 주택 구매자에게 더 낮은 금리를 제공한다.","sense":"첫 주택 구매자"},{"wordId":22052,"answer":"listing agent","form":"원형","example":"I called the listing agent to ask if the house has a basement.","exampleTranslation":"나는 집에 지하실이 있는지 물어보려고 매도인 측 중개인에게 전화했다.","sense":"매도인 측 중개인"},{"wordId":22054,"answer":"get preapproved","form":"원형","example":"It only took us two days to get preapproved for our loan.","exampleTranslation":"우리가 대출 사전 승인을 받는 데는 겨우 이틀밖에 걸리지 않았다.","sense":"사전 승인받다"},{"wordId":22055,"answer":"preapproval letter","form":"원형","example":"The real estate agent asked to see our preapproval letter before the tour.","exampleTranslation":"부동산 중개인은 집을 보여 주기 전에 우리 대출 사전 승인서를 보자고 했다.","sense":"사전 승인서"},{"wordId":22056,"answer":"bidding war","form":"원형","example":"We lost the bidding war to a buyer who paid in cash.","exampleTranslation":"우리는 현금으로 결제한 구매자에게 가격 경쟁에서 졌다.","sense":"가격 경쟁"},{"wordId":22057,"answer":"closing costs","form":"원형","example":"Our closing costs came to about eight thousand dollars in total.","exampleTranslation":"우리 클로징 비용은 모두 합쳐 약 팔천 달러가 나왔다.","sense":"클로징 비용"},{"wordId":22058,"answer":"closing date","form":"원형","example":"We planned our moving day for the morning after our closing date.","exampleTranslation":"우리는 이사 날짜를 잔금일 다음 날 아침으로 잡았다.","sense":"잔금일"},{"wordId":22059,"answer":"fixed-rate mortgage","form":"원형","example":"My parents paid off a fixed-rate mortgage on their first house over thirty years.","exampleTranslation":"부모님은 첫 집의 고정 금리 주택담보대출을 삼십 년에 걸쳐 다 갚으셨다.","sense":"고정 금리 대출"},{"wordId":22060,"answer":"adjustable-rate mortgage","form":"원형","example":"My uncle regrets choosing an adjustable-rate mortgage when interest rates were low.","exampleTranslation":"삼촌은 금리가 낮을 때 변동 금리 주택담보대출을 고른 것을 후회한다.","sense":"변동 금리 대출"},{"wordId":22061,"answer":"loan term","form":"원형","example":"We picked a fifteen-year loan term to save money on interest.","exampleTranslation":"우리는 이자를 아끼려고 십오 년 대출 기간을 골랐다.","sense":"대출 기간"},{"wordId":22062,"answer":"lenders","form":"복수형","example":"We talked to three different lenders before choosing the best rate.","exampleTranslation":"우리는 가장 좋은 금리를 고르기 전에 대출 기관 세 곳과 상담했다.","sense":"대출 기관"},{"wordId":22063,"answer":"mortgage broker","form":"원형","example":"Our mortgage broker found us a lower rate than our own bank offered.","exampleTranslation":"우리 주택담보대출 중개인은 우리 거래 은행보다 더 낮은 금리를 찾아 주었다.","sense":"대출 중개인"},{"wordId":22064,"answer":"loan officer","form":"원형","example":"The loan officer called this morning to say our application was approved.","exampleTranslation":"대출 담당자가 오늘 아침 전화해서 우리 신청이 승인되었다고 했다.","sense":"대출 담당자"},{"wordId":22065,"answer":"home inspection","form":"원형","example":"We paid four hundred dollars for a home inspection before signing anything.","exampleTranslation":"우리는 아무것도 서명하기 전에 주택 점검 비용으로 사백 달러를 냈다.","sense":"주택 점검"},{"wordId":22066,"answer":"appraisals","form":"복수형","example":"We got two appraisals, and they came back with very different values.","exampleTranslation":"우리는 감정 평가를 두 번 받았는데 결과 금액이 매우 달랐다.","sense":"감정 평가"},{"wordId":22067,"answer":"appraised value","form":"원형","example":"The appraised value came in higher than we expected, which was great news.","exampleTranslation":"감정가가 예상보다 높게 나와서 정말 좋은 소식이었다.","sense":"감정가"},{"wordId":22068,"answer":"escrow","form":"원형","example":"Our lender keeps money in escrow to pay the property taxes each year.","exampleTranslation":"우리 대출 기관은 매년 재산세를 내기 위해 돈을 에스크로에 예치해 둔다.","sense":"에스크로"},{"wordId":22069,"answer":"earnest money","form":"원형","example":"The sellers kept our earnest money when we backed out of the deal.","exampleTranslation":"우리가 거래에서 빠지자 매도인은 우리 계약 보증금을 돌려주지 않았다.","sense":"계약 보증금"},{"wordId":22070,"answer":"out of our price range","form":"원형","example":"We loved the house with the pool, but it was out of our price range.","exampleTranslation":"수영장이 있는 그 집이 정말 마음에 들었지만 우리 가격대를 벗어났다.","sense":"가격대 밖인"},{"wordId":22071,"answer":"move-in ready","form":"원형","example":"The apartment downtown is move-in ready, so we can move there next week.","exampleTranslation":"시내의 그 아파트는 바로 입주할 수 있어서 우리는 다음 주에 이사할 수 있다.","sense":"바로 입주 가능한"},{"wordId":22072,"answer":"fixer-uppers","form":"복수형","example":"My brother loves buying fixer-uppers and selling them after the repairs.","exampleTranslation":"형은 수리가 필요한 집을 사서 수리한 뒤에 파는 것을 좋아한다.","sense":"수리할 집"},{"wordId":22073,"answer":"starter home","form":"원형","example":"Our first child was born while we lived in our starter home.","exampleTranslation":"우리 첫아이는 우리가 처음 장만한 작은 집에 살 때 태어났다.","sense":"첫 집"},{"wordId":22074,"answer":"single-family home","form":"원형","example":"Prices for a single-family home in this town have doubled since 2015.","exampleTranslation":"이 동네의 단독 주택 가격은 2015년 이후 두 배가 되었다.","sense":"단독 주택"},{"wordId":22075,"answer":"townhouses","form":"복수형","example":"Several new townhouses are being built near the train station.","exampleTranslation":"기차역 근처에 새 타운하우스 몇 채가 지어지고 있다.","sense":"타운하우스"},{"wordId":22076,"answer":"homeowners association","form":"원형","example":"The homeowners association does not allow residents to paint their front doors red.","exampleTranslation":"주택 소유자 협회는 주민들이 현관문을 빨간색으로 칠하는 것을 허용하지 않는다.","sense":"주택 소유자 협회"},{"wordId":22077,"answer":"refinanced","form":"과거분사","example":"We have refinanced our home twice since we bought it in 2010.","exampleTranslation":"우리는 2010년에 집을 산 뒤로 두 번 대출을 갈아탔다.","sense":"재융자하다"},{"wordId":22078,"answer":"lock in a rate","form":"원형","example":"My friend waited too long to lock in a rate, and it went up.","exampleTranslation":"친구는 금리를 고정하는 것을 너무 오래 미루다가 금리가 올라 버렸다.","sense":"금리 고정하다"},{"wordId":22079,"answer":"home equity","form":"원형","example":"They used their home equity to pay for their daughter's college.","exampleTranslation":"그들은 주택 순자산을 이용해 딸의 대학 학비를 냈다.","sense":"주택 순자산"},{"wordId":22080,"answer":"debt-to-income ratio","form":"원형","example":"Paying off my car loan lowered my debt-to-income ratio quite a bit.","exampleTranslation":"자동차 대출을 다 갚았더니 소득 대비 부채 비율이 꽤 낮아졌다.","sense":"부채 비율"},{"wordId":22081,"answer":"title search","form":"원형","example":"The title search showed an old unpaid bill attached to the property.","exampleTranslation":"권리 조사에서 그 부동산에 걸린 오래된 미납 청구서가 드러났다.","sense":"권리 조사"},{"wordId":22082,"answer":"deeds","form":"복수형","example":"My grandfather kept the deeds to both of his farms in a metal box.","exampleTranslation":"할아버지는 두 농장의 권리증을 철제 상자에 보관하셨다.","sense":"권리증"},{"wordId":22083,"answer":"final walk-through","form":"원형","example":"We scheduled the final walk-through for Friday morning, right before signing the papers.","exampleTranslation":"우리는 서류 서명 직전인 금요일 아침으로 잔금 전 최종 점검 일정을 잡았다.","sense":"최종 점검"},{"wordId":22084,"answer":"contingencies","form":"복수형","example":"Our offer had fewer contingencies, so the sellers accepted it quickly.","exampleTranslation":"우리 제안에는 조건부 조항이 더 적어서 매도인이 빨리 받아들였다.","sense":"조건부 조항"},{"wordId":22085,"answer":"under contract","form":"원형","example":"The cute house we liked went under contract after only three days.","exampleTranslation":"우리가 마음에 들어 한 예쁜 집은 겨우 사흘 만에 매매 계약에 들어갔다.","sense":"계약 진행 중인"},{"wordId":22088,"answer":"square footage","form":"원형","example":"We need more square footage now that we have twins.","exampleTranslation":"쌍둥이가 생겼으니 이제 우리는 더 넓은 면적이 필요하다.","sense":"면적"},{"wordId":22089,"answer":"curb appeal","form":"원형","example":"A new front door can add a lot of curb appeal for little money.","exampleTranslation":"새 현관문은 적은 돈으로 집 외관의 첫인상을 크게 높여 줄 수 있다.","sense":"외관 첫인상"},{"wordId":22090,"answer":"mortgage payment","form":"원형","example":"We set up automatic transfers so we never miss a mortgage payment.","exampleTranslation":"우리는 주택담보대출 상환금을 절대 놓치지 않도록 자동 이체를 설정했다.","sense":"대출 상환금"},{"wordId":22091,"answer":"pay off the mortgage","form":"원형","example":"My parents threw a party when they finally managed to pay off the mortgage.","exampleTranslation":"부모님은 마침내 주택담보대출을 다 갚게 되자 파티를 여셨다.","sense":"대출 다 갚다"},{"wordId":22092,"answer":"qualify for a loan","form":"원형","example":"Students with part-time jobs can still qualify for a loan from this bank.","exampleTranslation":"아르바이트를 하는 학생도 이 은행에서 대출 자격을 얻을 수 있다.","sense":"대출 자격 얻다"},{"wordId":22093,"answer":"private mortgage insurance","form":"원형","example":"We stopped paying private mortgage insurance once we owned twenty percent of the house.","exampleTranslation":"집 지분이 이십 퍼센트가 되자 우리는 민간 주택담보대출 보험료를 더 이상 내지 않았다.","sense":"대출 보험"},{"wordId":22094,"answer":"amortization schedule","form":"원형","example":"Our bank emails us an updated amortization schedule every January.","exampleTranslation":"우리 은행은 매년 일월에 갱신된 대출 상환 일정표를 이메일로 보내 준다.","sense":"상환 일정표"},{"wordId":22095,"answer":"seller concessions","form":"원형","example":"In a busy market like this, buyers rarely receive any seller concessions.","exampleTranslation":"이렇게 활발한 시장에서는 구매자가 매도인 양보 조건을 받는 일이 드물다.","sense":"매도인 양보"},{"wordId":22096,"answer":"foreclosures","form":"복수형","example":"There were many foreclosures in our town after the factory closed.","exampleTranslation":"공장이 문을 닫은 뒤 우리 동네에서 압류가 많이 일어났다.","sense":"압류"},{"wordId":22097,"answer":"mortgage calculator","form":"원형","example":"The mortgage calculator on the bank website is free and easy to use.","exampleTranslation":"은행 웹사이트의 주택담보대출 계산기는 무료이고 쓰기 쉽다.","sense":"대출 계산기"},{"wordId":22098,"answer":"down payment assistance","form":"원형","example":"My cousin received down payment assistance through a state program for veterans.","exampleTranslation":"사촌은 주 정부의 참전 용사 프로그램을 통해 계약금 지원을 받았다.","sense":"계약금 지원"},{"wordId":22099,"answer":"price reduction","form":"원형","example":"After a small price reduction, the apartment sold in just one week.","exampleTranslation":"가격을 조금 인하한 뒤 그 아파트는 딱 일주일 만에 팔렸다.","sense":"가격 인하"},{"wordId":22100,"answer":"co-signers","form":"복수형","example":"The bank asked for two co-signers because my credit history was short.","exampleTranslation":"내 신용 기록이 짧아서 은행은 공동 서명인 두 명을 요구했다.","sense":"공동 서명인"},{"wordId":22101,"answer":"pump number","form":"원형","example":"Please check your pump number before you pay inside the store.","exampleTranslation":"가게 안에서 계산하기 전에 주유기 번호를 확인해 주세요.","sense":"주유기 번호"},{"wordId":22102,"answer":"pay at the pump","form":"원형","example":"The card reader was broken, so we could not pay at the pump.","exampleTranslation":"카드 단말기가 고장 나서 우리는 주유기에서 결제할 수 없었다.","sense":"주유기 결제하다"},{"wordId":22103,"answer":"prepays","form":"3인칭 단수형","example":"My dad usually prepays for a full tank when we go on road trips.","exampleTranslation":"아빠는 우리가 자동차 여행을 갈 때 보통 기름을 가득 채울 만큼 선결제하신다.","sense":"선결제하다"},{"wordId":22104,"answer":"nozzles","form":"복수형","example":"Two of the nozzles at this gas station were out of order yesterday.","exampleTranslation":"어제 이 주유소의 주유 노즐 두 개가 고장 나 있었다.","sense":"주유 노즐"},{"wordId":22105,"answer":"gas cap","form":"원형","example":"Make sure you twist the gas cap until it clicks three times.","exampleTranslation":"주유구 마개는 딸깍 소리가 세 번 날 때까지 꼭 돌려 잠그세요.","sense":"주유구 마개"},{"wordId":22106,"answer":"fuel door","form":"원형","example":"The fuel door on my new car opens with a button inside.","exampleTranslation":"내 새 차의 주유구 덮개는 차 안의 버튼으로 열린다.","sense":"주유구 덮개"},{"wordId":22107,"answer":"self-service","form":"원형","example":"This self-service station is open twenty-four hours a day.","exampleTranslation":"이 셀프 주유소는 하루 스물네 시간 문을 연다.","sense":"셀프의"},{"wordId":22108,"answer":"full-service","form":"원형","example":"In the rain, I always look for a full-service gas station.","exampleTranslation":"비가 오면 나는 항상 직원이 주유해 주는 주유소를 찾는다.","sense":"직원 주유의"},{"wordId":22109,"answer":"per gallon","form":"원형","example":"My new car gets about forty miles per gallon on the highway.","exampleTranslation":"내 새 차는 고속도로에서 갤런당 약 사십 마일을 간다.","sense":"갤런당"},{"wordId":22110,"answer":"automatic car wash","form":"원형","example":"My dog barks the whole time we are in the automatic car wash.","exampleTranslation":"우리 개는 자동 세차기 안에 있는 내내 짖는다.","sense":"자동 세차"},{"wordId":22111,"answer":"touchless wash","form":"원형","example":"A touchless wash cannot remove the dried mud from my wheels.","exampleTranslation":"비접촉 세차로는 내 바퀴에 말라붙은 진흙을 없앨 수 없다.","sense":"비접촉 세차"},{"wordId":22112,"answer":"wax","form":"원형","example":"I put a coat of wax on my car before the long winter.","exampleTranslation":"나는 긴 겨울이 오기 전에 차에 왁스를 한 겹 발랐다.","sense":"왁스"},{"wordId":22113,"answer":"vacuum station","form":"원형","example":"After our beach trip, we spent ten minutes at the vacuum station.","exampleTranslation":"해변 여행 후에 우리는 셀프 청소기 앞에서 십 분 동안 청소했다.","sense":"셀프 청소기"},{"wordId":22114,"answer":"interior cleaning","form":"원형","example":"After the road trip with our dogs, the car badly needed interior cleaning.","exampleTranslation":"개들과 자동차 여행을 다녀온 뒤 차는 실내 청소가 절실했다.","sense":"실내 청소"},{"wordId":22115,"answer":"basic wash","form":"원형","example":"A basic wash is enough if your car is only a little dusty.","exampleTranslation":"차에 먼지가 조금만 있으면 기본 세차로 충분하다.","sense":"기본 세차"},{"wordId":22116,"answer":"tire shine","form":"원형","example":"My brother spends twenty minutes putting tire shine on every wheel.","exampleTranslation":"형은 바퀴마다 타이어 광택제를 바르는 데 이십 분을 쓴다.","sense":"타이어 광택제"},{"wordId":22117,"answer":"underbody wash","form":"원형","example":"After driving on the muddy farm road, I paid for an underbody wash.","exampleTranslation":"진흙투성이 농장 길을 달린 뒤 나는 돈을 내고 하부 세척을 했다.","sense":"하부 세척"},{"wordId":22118,"answer":"wash code","form":"원형","example":"The cashier printed my wash code at the bottom of the receipt.","exampleTranslation":"계산원이 영수증 맨 아래에 내 세차 코드를 인쇄해 주었다.","sense":"세차 코드"},{"wordId":22119,"answer":"squeegees","form":"복수형","example":"The station keeps squeegees and paper towels next to every pump.","exampleTranslation":"그 주유소는 주유기마다 옆에 스퀴지와 종이 타월을 둔다.","sense":"스퀴지"},{"wordId":22120,"answer":"low on gas","form":"원형","example":"The warning light came on because we were low on gas.","exampleTranslation":"기름이 얼마 안 남아서 경고등이 켜졌다.","sense":"기름이 부족한"},{"wordId":22121,"answer":"gas can","form":"원형","example":"My neighbor keeps a gas can in his garage for the lawn mower.","exampleTranslation":"이웃은 잔디 깎는 기계용으로 차고에 휴대용 기름통을 둔다.","sense":"휴대용 기름통"},{"wordId":22122,"answer":"fast charger","form":"원형","example":"The mall parking lot just added a fast charger for electric cars.","exampleTranslation":"그 쇼핑몰 주차장에 전기차용 급속 충전기가 새로 생겼다.","sense":"급속 충전기"},{"wordId":22123,"answer":"gas station attendant","form":"원형","example":"The gas station attendant gave us directions to the nearest hotel.","exampleTranslation":"주유소 직원이 가장 가까운 호텔로 가는 길을 알려 주었다.","sense":"주유소 직원"},{"wordId":22124,"answer":"overfilled","form":"과거형","example":"I overfilled the tank yesterday, and gas spilled onto my shoes.","exampleTranslation":"나는 어제 기름을 너무 많이 채워서 신발에 기름이 흘렀다.","sense":"넘치게 채우다"},{"wordId":22125,"answer":"octane","form":"원형","example":"Higher octane gas costs more, but my old car does not need it.","exampleTranslation":"옥탄가가 높은 기름은 더 비싸지만 내 오래된 차에는 필요 없다.","sense":"옥탄가"},{"wordId":22126,"answer":"fuel rewards","form":"원형","example":"My fuel rewards expire at the end of the month, so I should use them.","exampleTranslation":"내 주유 적립 혜택이 이번 달 말에 만료되니 써야겠다.","sense":"주유 적립 혜택"},{"wordId":22127,"answer":"unlimited wash plan","form":"원형","example":"I canceled my unlimited wash plan because I rarely drive in winter.","exampleTranslation":"나는 겨울에는 운전을 거의 안 해서 무제한 세차 이용권을 해지했다.","sense":"무제한 세차권"},{"wordId":22128,"answer":"bird droppings","form":"원형","example":"Parking under that big tree means your car will be covered in bird droppings.","exampleTranslation":"저 큰 나무 아래에 주차하면 차가 새똥투성이가 될 거야.","sense":"새똥"},{"wordId":22129,"answer":"water spots","form":"원형","example":"Washing your car in direct sunlight often leaves water spots on the glass.","exampleTranslation":"햇빛이 쨍쨍할 때 세차하면 유리에 물 얼룩이 자주 남는다.","sense":"물 얼룩"},{"wordId":22130,"answer":"microfiber towel","form":"원형","example":"I always keep a microfiber towel in the car to clean my glasses.","exampleTranslation":"나는 안경을 닦으려고 차에 항상 극세사 수건을 둔다.","sense":"극세사 수건"},{"wordId":22131,"answer":"spot-free rinse","form":"원형","example":"The spot-free rinse costs one more dollar, but it saves me a lot of time.","exampleTranslation":"물 얼룩 방지 헹굼은 일 달러가 더 들지만 시간을 많이 아껴 준다.","sense":"얼룩 방지 헹굼"},{"wordId":22132,"answer":"pressure washer","form":"원형","example":"My dad rented a pressure washer to clean the mud off our truck.","exampleTranslation":"아빠는 트럭에 묻은 진흙을 씻어 내려고 고압 세척기를 빌리셨다.","sense":"고압 세척기"},{"wordId":22133,"answer":"foam brush","form":"원형","example":"The foam brush at this car wash is old and full of dirt.","exampleTranslation":"이 세차장의 거품 브러시는 낡았고 먼지투성이다.","sense":"거품 브러시"},{"wordId":22134,"answer":"restroom key","form":"원형","example":"The restroom key is attached to a big wooden spoon so nobody takes it.","exampleTranslation":"화장실 열쇠는 아무도 가져가지 못하게 큰 나무 숟가락에 달려 있다.","sense":"화장실 열쇠"},{"wordId":22135,"answer":"fill-ups","form":"복수형","example":"I keep track of my fill-ups in an app to check my mileage.","exampleTranslation":"나는 연비를 확인하려고 기름을 가득 채운 기록을 앱에 남긴다.","sense":"가득 채우기"},{"wordId":22136,"answer":"fuel price app","form":"원형","example":"My fuel price app showed that gas is cheaper in the next town.","exampleTranslation":"유가 비교 앱을 보니 옆 동네가 기름값이 더 쌌다.","sense":"유가 비교 앱"},{"wordId":22137,"answer":"detailing","form":"원형","example":"My cousin earns extra money by doing car detailing on weekends.","exampleTranslation":"사촌은 주말마다 차량 정밀 세차를 해서 부수입을 번다.","sense":"정밀 세차"},{"wordId":22138,"answer":"washer fluid","form":"원형","example":"Buy a jug of washer fluid before our long drive tomorrow.","exampleTranslation":"내일 장거리 운전 전에 워셔액을 한 통 사 둬.","sense":"워셔액"},{"wordId":22139,"answer":"air machine","form":"원형","example":"The air machine at this station is free for all customers.","exampleTranslation":"이 주유소의 공기 주입기는 모든 손님에게 무료다.","sense":"공기 주입기"},{"wordId":22140,"answer":"car wash tunnel","form":"원형","example":"My little son was scared of the loud brushes in the car wash tunnel.","exampleTranslation":"어린 아들은 터널식 세차장의 시끄러운 브러시를 무서워했다.","sense":"터널식 세차장"},{"wordId":22141,"answer":"side of the pump","form":"원형","example":"I parked on the wrong side of the pump, so I had to turn around.","exampleTranslation":"나는 주유기의 엉뚱한 쪽에 차를 세워서 다시 돌아 들어가야 했다.","sense":"주유기 쪽"},{"wordId":22142,"answer":"diesel pump","form":"원형","example":"There was a long line of trucks waiting at the diesel pump.","exampleTranslation":"경유 주유기 앞에 트럭들이 길게 줄 서 있었다.","sense":"경유 주유기"},{"wordId":22143,"answer":"pump is down","form":"원형","example":"The cashier told me the pump is down until the repairman arrives.","exampleTranslation":"계산원은 수리 기사가 올 때까지 주유기가 고장 난 상태라고 말했다.","sense":"주유기 고장"},{"wordId":22144,"answer":"ceramic coating","form":"원형","example":"My new car came with a ceramic coating from the dealer.","exampleTranslation":"내 새 차에는 대리점에서 해 준 세라믹 코팅이 되어 있었다.","sense":"세라믹 코팅"},{"wordId":22145,"answer":"streak-free","form":"원형","example":"This glass cleaner leaves my bathroom mirror streak-free every time.","exampleTranslation":"이 유리 세정제를 쓰면 욕실 거울이 매번 얼룩 없이 깨끗해진다.","sense":"얼룩 없는"},{"wordId":22146,"answer":"gas receipt","form":"원형","example":"I threw away my gas receipt before I noticed the wrong price.","exampleTranslation":"나는 잘못된 가격을 알아차리기 전에 주유 영수증을 버려 버렸다.","sense":"주유 영수증"},{"wordId":22147,"answer":"wheel cleaner","form":"원형","example":"This wheel cleaner turns purple when it touches brake dust.","exampleTranslation":"이 휠 클리너는 브레이크 분진에 닿으면 보라색으로 변한다.","sense":"휠 클리너"},{"wordId":22148,"answer":"self-serve bay","form":"원형","example":"We washed our muddy bikes in the self-serve bay at the car wash.","exampleTranslation":"우리는 세차장의 셀프 세차 칸에서 진흙 묻은 자전거를 씻었다.","sense":"셀프 세차 칸"},{"wordId":22149,"answer":"pre-soak","form":"원형","example":"The pre-soak did not remove all the bugs from the front bumper.","exampleTranslation":"애벌 세제로는 앞 범퍼의 벌레가 다 지워지지 않았다.","sense":"애벌 세제"},{"wordId":22150,"answer":"half a tank","form":"원형","example":"My sister always fills up when she has half a tank left.","exampleTranslation":"언니는 기름이 반 탱크 남으면 항상 가득 채운다.","sense":"반 탱크"},{"wordId":22151,"answer":"my better half","form":"원형","example":"I would love to come, but my better half has already made dinner plans.","exampleTranslation":"정말 가고 싶지만 우리 배우자가 이미 저녁 약속을 잡았어.","sense":"내 배우자"},{"wordId":22152,"answer":"hubbies","form":"복수형","example":"Our hubbies went fishing together, so we went shopping.","exampleTranslation":"남편들이 같이 낚시를 가서 우리는 쇼핑을 갔다.","sense":"남편","alts":["husbands"]},{"wordId":22153,"answer":"married life","form":"원형","example":"My grandparents enjoyed sixty happy years of married life together.","exampleTranslation":"조부모님은 육십 년 동안 행복한 결혼 생활을 함께하셨다.","sense":"결혼 생활"},{"wordId":22154,"answer":"separate finances","form":"원형","example":"My parents have kept separate finances since they got married.","exampleTranslation":"부모님은 결혼하신 이후로 각자 돈 관리를 해 오셨다.","sense":"각자 돈 관리"},{"wordId":22155,"answer":"the silent treatment","form":"원형","example":"My little brother gave everyone the silent treatment after losing the game.","exampleTranslation":"남동생은 게임에서 진 뒤 모두에게 말을 안 하며 침묵으로 맞섰다.","sense":"말 안 하기"},{"wordId":22156,"answer":"honey-do list","form":"원형","example":"I finished everything on my honey-do list before lunch on Saturday.","exampleTranslation":"나는 토요일 점심 전에 집안일 목록에 있는 것을 다 끝냈다.","sense":"집안일 목록"},{"wordId":22157,"answer":"couples counseling","form":"원형","example":"My friend suggested couples counseling when we kept arguing about money.","exampleTranslation":"우리가 돈 문제로 계속 다투자 친구가 부부 상담을 권했다.","sense":"부부 상담"},{"wordId":22158,"answer":"hog the blanket","form":"원형","example":"My dog likes to hog the blanket when he sleeps on our bed.","exampleTranslation":"우리 개는 우리 침대에서 잘 때 이불을 독차지하는 것을 좋아한다.","sense":"이불 독차지하다"},{"wordId":22159,"answer":"your turn to cook","form":"원형","example":"Mom says it is your turn to cook for the family this Sunday.","exampleTranslation":"엄마가 이번 일요일엔 네가 가족을 위해 요리할 차례래.","sense":"네가 요리할 차례"},{"wordId":22160,"answer":"dual-income","form":"원형","example":"Many dual-income families in our neighborhood hire a babysitter after school.","exampleTranslation":"우리 동네의 많은 맞벌이 가정은 방과 후에 아이 돌보미를 고용한다.","sense":"맞벌이의"},{"wordId":22161,"answer":"vow renewal","form":"원형","example":"My parents invited all their old friends to their vow renewal last spring.","exampleTranslation":"부모님은 지난봄 혼인 서약 갱신식에 옛 친구들을 모두 초대하셨다.","sense":"서약 갱신"},{"wordId":22162,"answer":"empty nesters","form":"원형","example":"Many empty nesters move into smaller homes after their kids leave.","exampleTranslation":"자녀가 독립한 많은 부부가 아이들이 떠난 뒤 더 작은 집으로 이사한다.","sense":"자녀 독립한 부부"},{"wordId":22163,"answer":"bickers","form":"3인칭 단수형","example":"My grandma bickers with my grandpa every morning about the TV remote.","exampleTranslation":"할머니는 매일 아침 텔레비전 리모컨을 두고 할아버지와 티격태격하신다.","sense":"티격태격하다"},{"wordId":22164,"answer":"give each other space","form":"원형","example":"Roommates should give each other space when someone has a bad day.","exampleTranslation":"룸메이트끼리는 누군가 힘든 날을 보내면 서로 혼자 있을 시간을 줘야 한다.","sense":"서로 시간 주다"},{"wordId":22165,"answer":"mental load","form":"원형","example":"Remembering every family birthday is part of the mental load I carry.","exampleTranslation":"가족의 생일을 모두 기억하는 것도 내가 짊어진 정신적 부담의 일부다.","sense":"정신적 부담"},{"wordId":22166,"answer":"handle the bills","form":"원형","example":"My husband offered to handle the bills while I study for my exams.","exampleTranslation":"남편은 내가 시험공부를 하는 동안 공과금을 처리하겠다고 했다.","sense":"공과금 처리하다"},{"wordId":22167,"answer":"husband and wife","form":"원형","example":"At the end of the ceremony, they were announced as husband and wife.","exampleTranslation":"식이 끝날 무렵 두 사람은 남편과 아내로 선언되었다.","sense":"부부"},{"wordId":22168,"answer":"romantic gesture","form":"원형","example":"Cooking her favorite meal after a long day was a sweet romantic gesture.","exampleTranslation":"긴 하루를 보낸 그녀에게 좋아하는 음식을 만들어 준 것은 다정하고 로맨틱한 행동이었다.","sense":"로맨틱한 행동"},{"wordId":22169,"answer":"feel appreciated","form":"원형","example":"A simple thank-you note can make your coworkers feel appreciated.","exampleTranslation":"간단한 감사 쪽지 하나로도 동료들이 인정받는다고 느낄 수 있다.","sense":"인정받는다 느끼다"},{"wordId":22170,"answer":"first fight","form":"원형","example":"We had our first fight on our honeymoon over a lost map.","exampleTranslation":"우리는 신혼여행에서 잃어버린 지도 때문에 첫 싸움을 했다.","sense":"첫 싸움"},{"wordId":22171,"answer":"in sickness and in health","form":"원형","example":"They promised to love each other in sickness and in health.","exampleTranslation":"두 사람은 아플 때나 건강할 때나 서로 사랑하겠다고 약속했다.","sense":"아플 때나 건강할 때나"},{"wordId":22172,"answer":"family budget","form":"원형","example":"Eating out less has helped our family budget a lot this year.","exampleTranslation":"외식을 줄인 것이 올해 우리 가계 예산에 큰 도움이 되었다.","sense":"가계 예산"},{"wordId":22173,"answer":"big purchase","form":"원형","example":"A new sofa is a big purchase, so we should compare prices first.","exampleTranslation":"새 소파는 큰 지출이니까 먼저 가격을 비교해 봐야 해.","sense":"큰 지출"},{"wordId":22174,"answer":"love language","form":"원형","example":"My husband's love language is quality time, so we take long walks.","exampleTranslation":"남편의 사랑의 언어는 함께하는 시간이라서 우리는 오래 산책을 한다.","sense":"사랑의 언어"},{"wordId":22175,"answer":"meet the in-laws","form":"원형","example":"I bought a nice shirt to wear when I meet the in-laws on Sunday.","exampleTranslation":"나는 일요일에 배우자 가족을 만날 때 입으려고 멋진 셔츠를 샀다.","sense":"배우자 가족 만나다"},{"wordId":22176,"answer":"sleep on the couch","form":"원형","example":"Our guests can sleep on the couch if the spare room is full.","exampleTranslation":"손님방이 차면 손님들은 소파에서 자도 된다.","sense":"소파에서 자다"},{"wordId":22177,"answer":"apology flowers","form":"원형","example":"My brother bought apology flowers for his girlfriend after he forgot her birthday.","exampleTranslation":"형은 여자 친구의 생일을 잊어버린 뒤 사과의 꽃을 샀다.","sense":"사과의 꽃"},{"wordId":22178,"answer":"stay-at-home mom","form":"원형","example":"My neighbor is a stay-at-home mom who also sells cakes online.","exampleTranslation":"내 이웃은 전업주부 엄마인데 온라인으로 케이크도 판다.","sense":"전업주부 엄마"},{"wordId":22179,"answer":"pet peeve","form":"원형","example":"One pet peeve of mine is people who talk loudly on the phone.","exampleTranslation":"내가 유난히 짜증 나는 것 하나는 전화로 크게 떠드는 사람들이다.","sense":"짜증 나는 것"},{"wordId":22180,"answer":"spend time apart","form":"원형","example":"During his business trip, we had to spend time apart for a month.","exampleTranslation":"그의 출장 기간 동안 우리는 한 달간 떨어져 시간을 보내야 했다.","sense":"떨어져 지내다"},{"wordId":22181,"answer":"life partner","form":"원형","example":"After ten years together, she knew he was her life partner.","exampleTranslation":"함께한 지 십 년이 지나자 그녀는 그가 인생의 동반자라는 것을 알았다.","sense":"인생의 동반자"},{"wordId":22182,"answer":"meet my parents","form":"원형","example":"Next weekend, my girlfriend will fly to Busan to meet my parents.","exampleTranslation":"다음 주말에 내 여자 친구가 우리 부모님을 만나러 비행기를 타고 부산에 간다.","sense":"부모님 만나다"},{"wordId":22183,"answer":"keep the spark alive","form":"원형","example":"Cooking dinner together on Fridays helps us keep the spark alive.","exampleTranslation":"금요일마다 함께 저녁을 요리하는 것이 우리가 설렘을 유지하는 데 도움이 된다.","sense":"설렘 유지하다"},{"wordId":22184,"answer":"give and take","form":"원형","example":"Living with roommates requires a lot of give and take.","exampleTranslation":"룸메이트와 함께 사는 데는 서로 많은 양보가 필요하다.","sense":"서로 양보"},{"wordId":22185,"answer":"two-income household","form":"원형","example":"Growing up in a two-income household taught me to cook early.","exampleTranslation":"맞벌이 가정에서 자라서 나는 일찍 요리를 배웠다.","sense":"맞벌이 가정"},{"wordId":22186,"answer":"wedding band","form":"원형","example":"I lost my wedding band at the beach, but a kind stranger found it.","exampleTranslation":"나는 해변에서 결혼반지를 잃어버렸는데 친절한 낯선 사람이 찾아 주었다.","sense":"결혼반지"},{"wordId":22187,"answer":"tough patch","form":"원형","example":"Our small business went through a tough patch during the long winter.","exampleTranslation":"우리 작은 가게는 긴 겨울 동안 힘든 시기를 겪었다.","sense":"힘든 시기"},{"wordId":22188,"answer":"meal planning","form":"원형","example":"Meal planning helps my roommate eat healthier during busy exam weeks.","exampleTranslation":"식단 계획 덕분에 내 룸메이트는 바쁜 시험 기간에 더 건강하게 먹는다.","sense":"식단 계획"},{"wordId":22189,"answer":"love note","form":"원형","example":"My husband hid a love note inside my suitcase before my trip.","exampleTranslation":"남편은 내 여행 전에 여행 가방 안에 사랑의 쪽지를 숨겨 두었다.","sense":"사랑의 쪽지"},{"wordId":22190,"answer":"joint decision","form":"원형","example":"Moving to a new city was a joint decision, not just my idea.","exampleTranslation":"새 도시로 이사한 것은 함께 내린 결정이지 내 생각만은 아니었다.","sense":"함께 내린 결정"},{"wordId":22191,"answer":"pick your battles","form":"원형","example":"With teenagers, you have to pick your battles every single day.","exampleTranslation":"십 대 자녀와 지낼 때는 매일 싸울 일을 가려서 해야 한다.","sense":"싸울 일 가리다"},{"wordId":22192,"answer":"long-distance marriage","form":"원형","example":"Video calls every night made our long-distance marriage much easier.","exampleTranslation":"매일 밤 영상 통화 덕분에 떨어져 사는 결혼 생활이 훨씬 수월해졌다.","sense":"떨어져 사는 결혼"},{"wordId":22193,"answer":"homemakers","form":"복수형","example":"Many homemakers in our town volunteer at the local library.","exampleTranslation":"우리 동네의 많은 주부들이 지역 도서관에서 봉사한다.","sense":"주부"},{"wordId":22194,"answer":"breadwinners","form":"복수형","example":"In many families today, both parents are breadwinners.","exampleTranslation":"오늘날 많은 가정에서는 부모 둘 다 주 소득자이다.","sense":"주 소득자"},{"wordId":22195,"answer":"wedding album","form":"원형","example":"My mother keeps her wedding album on the top shelf of the closet.","exampleTranslation":"어머니는 결혼식 앨범을 옷장 맨 위 칸에 보관하신다.","sense":"결혼식 앨범"},{"wordId":22196,"answer":"cuddled","form":"과거형","example":"The kids cuddled with their grandmother on the sofa last night.","exampleTranslation":"어젯밤 아이들은 소파에서 할머니에게 꼭 붙어 있었다.","sense":"꼭 껴안다"},{"wordId":22197,"answer":"spend the holidays","form":"원형","example":"This year we will spend the holidays at a cabin in the mountains.","exampleTranslation":"올해 우리는 산속 오두막에서 연휴를 보낼 것이다.","sense":"연휴 보내다"},{"wordId":22198,"answer":"forgive and forget","form":"원형","example":"It is hard to forgive and forget when a friend lies to you.","exampleTranslation":"친구가 거짓말을 하면 용서하고 잊기가 어렵다.","sense":"용서하고 잊다"},{"wordId":22199,"answer":"welcome home","form":"원형","example":"Welcome home, sweetie, and how was your first week at college?","exampleTranslation":"어서 와, 얘야, 대학에서 첫 주는 어땠니?","sense":"어서 와"},{"wordId":22200,"answer":"working mom","form":"원형","example":"Being a working mom means my evenings are always busy.","exampleTranslation":"워킹맘으로 산다는 건 저녁이 늘 바쁘다는 뜻이다.","sense":"워킹맘"},{"wordId":22201,"answer":"tryouts","form":"복수형","example":"Tryouts for the school volleyball team start next Monday after class.","exampleTranslation":"학교 배구팀 입단 테스트는 다음 주 월요일 방과 후에 시작한다.","sense":"입단 테스트"},{"wordId":22202,"answer":"rec league","form":"원형","example":"My dad still plays softball in a rec league at age sixty.","exampleTranslation":"아빠는 예순의 나이에도 생활 체육 리그에서 소프트볼을 하신다.","sense":"생활 체육 리그"},{"wordId":22203,"answer":"pickup game","form":"원형","example":"We joined a pickup game of volleyball on the beach yesterday.","exampleTranslation":"우리는 어제 해변에서 즉석 배구 경기에 끼었다.","sense":"즉석 경기"},{"wordId":22204,"answer":"running club","form":"원형","example":"I made most of my close friends through my running club.","exampleTranslation":"나는 친한 친구 대부분을 러닝 클럽에서 사귀었다.","sense":"러닝 클럽"},{"wordId":22205,"answer":"annual dues","form":"원형","example":"I paid my annual dues for the book club in January.","exampleTranslation":"나는 일월에 독서 모임 연회비를 냈다.","sense":"연회비"},{"wordId":22206,"answer":"rosters","form":"복수형","example":"Both coaches handed their rosters to the referee before kickoff.","exampleTranslation":"두 코치 모두 경기 시작 전에 심판에게 선수 명단을 건넸다.","sense":"선수 명단"},{"wordId":22207,"answer":"substitutes","form":"복수형","example":"Our team brought three substitutes to the tournament in case of injuries.","exampleTranslation":"우리 팀은 부상에 대비해 대회에 교체 선수 세 명을 데려갔다.","sense":"교체 선수"},{"wordId":22208,"answer":"short-handed","form":"원형","example":"The restaurant was short-handed last night, so the food came out slowly.","exampleTranslation":"어젯밤 그 식당은 일손이 부족해서 음식이 늦게 나왔다.","sense":"인원이 부족한"},{"wordId":22209,"answer":"scrimmages","form":"복수형","example":"The team played two scrimmages against the high school before the season.","exampleTranslation":"그 팀은 시즌 전에 그 고등학교와 연습 경기를 두 번 했다.","sense":"연습 경기"},{"wordId":22210,"answer":"skill level","form":"원형","example":"The tennis coach watched me hit a few balls to check my skill level.","exampleTranslation":"테니스 코치는 내 실력 수준을 확인하려고 내가 공 몇 개 치는 것을 지켜보았다.","sense":"실력 수준"},{"wordId":22211,"answer":"newcomers","form":"복수형","example":"Our book club welcomes newcomers on the first Monday of every month.","exampleTranslation":"우리 독서 모임은 매달 첫째 월요일에 신입을 환영한다.","sense":"신입"},{"wordId":22212,"answer":"meetups","form":"복수형","example":"I went to two language meetups last month to practice my Spanish.","exampleTranslation":"나는 스페인어를 연습하려고 지난달 언어 교환 모임에 두 번 갔다.","sense":"모임","alts":["get-togethers"]},{"wordId":22213,"answer":"organizers","form":"복수형","example":"The organizers of the charity run thanked every volunteer at the finish line.","exampleTranslation":"자선 달리기 대회 주최자들은 결승선에서 모든 자원봉사자에게 감사를 전했다.","sense":"주최자"},{"wordId":22214,"answer":"team captain","form":"원형","example":"Everyone voted for Jake as team captain this season.","exampleTranslation":"모두가 이번 시즌 팀 주장으로 제이크에게 투표했다.","sense":"팀 주장"},{"wordId":22215,"answer":"sit on the bench","form":"원형","example":"With a sprained ankle, he had to sit on the bench all game.","exampleTranslation":"발목을 삐어서 그는 경기 내내 벤치에 앉아 있어야 했다.","sense":"벤치에 앉다"},{"wordId":22216,"answer":"friendly match","form":"원형","example":"The two schools played a friendly match to raise money for the library.","exampleTranslation":"두 학교는 도서관 기금을 모으려고 친선 경기를 했다.","sense":"친선 경기"},{"wordId":22217,"answer":"standings","form":"원형","example":"Check the league standings on the website to see who is in first place.","exampleTranslation":"누가 일 위인지 웹사이트에서 리그 순위표를 확인해 봐.","sense":"순위표"},{"wordId":22218,"answer":"pass the ball","form":"원형","example":"The coach taught the young kids to pass the ball with the inside of their foot.","exampleTranslation":"코치는 어린아이들에게 발 안쪽으로 공을 패스하는 법을 가르쳤다.","sense":"공을 패스하다"},{"wordId":22219,"answer":"shin guards","form":"원형","example":"My son grew so fast that his shin guards no longer fit.","exampleTranslation":"아들이 너무 빨리 자라서 정강이 보호대가 더 이상 맞지 않는다.","sense":"정강이 보호대"},{"wordId":22220,"answer":"cleats","form":"원형","example":"Leave your muddy cleats outside the front door, please.","exampleTranslation":"진흙 묻은 축구화는 현관문 밖에 두세요.","sense":"축구화"},{"wordId":22221,"answer":"court rental","form":"원형","example":"The court rental went up to twenty dollars an hour this year.","exampleTranslation":"올해 코트 대여료가 시간당 이십 달러로 올랐다.","sense":"코트 대여료"},{"wordId":22222,"answer":"book a court","form":"원형","example":"It is almost impossible to book a court on Saturday evenings.","exampleTranslation":"토요일 저녁에는 코트를 예약하기가 거의 불가능하다.","sense":"코트 예약하다"},{"wordId":22223,"answer":"doubles","form":"원형","example":"My grandparents still play doubles at the tennis club every Sunday.","exampleTranslation":"할아버지 할머니는 지금도 매주 일요일 테니스 클럽에서 복식을 치신다.","sense":"복식"},{"wordId":22224,"answer":"badminton club","form":"원형","example":"Our office started a badminton club that meets after work on Tuesdays.","exampleTranslation":"우리 회사에 매주 화요일 퇴근 후에 모이는 배드민턴 동호회가 생겼다.","sense":"배드민턴 동호회"},{"wordId":22225,"answer":"group ride","form":"원형","example":"It rained hard, so the group ride was canceled this morning.","exampleTranslation":"비가 많이 와서 오늘 아침 단체 라이딩이 취소되었다.","sense":"단체 라이딩"},{"wordId":22226,"answer":"pace group","form":"원형","example":"I stayed with my pace group for the whole half marathon.","exampleTranslation":"나는 하프 마라톤 내내 내 페이스 그룹과 함께 달렸다.","sense":"페이스 그룹"},{"wordId":22227,"answer":"make the team","form":"원형","example":"My daughter was thrilled to make the team on her first try.","exampleTranslation":"딸은 첫 도전에 팀에 뽑혀서 몹시 기뻐했다.","sense":"팀에 뽑히다"},{"wordId":22228,"answer":"season opener","form":"원형","example":"Tickets for the season opener sold out in just one hour.","exampleTranslation":"시즌 개막전 표가 한 시간 만에 매진되었다.","sense":"시즌 개막전"},{"wordId":22229,"answer":"end-of-season party","form":"원형","example":"The kids got trophies and pizza at the end-of-season party.","exampleTranslation":"아이들은 시즌 종료 파티에서 트로피와 피자를 받았다.","sense":"시즌 종료 파티"},{"wordId":22230,"answer":"bond with","form":"원형","example":"Camping trips help me bond with my teenage son.","exampleTranslation":"캠핑 여행은 내가 십 대 아들과 친해지는 데 도움이 된다.","sense":"친해지다"},{"wordId":22231,"answer":"water break","form":"원형","example":"It was so hot that the referee called a water break midway through.","exampleTranslation":"너무 더워서 심판은 경기 도중에 물 마시는 휴식을 선언했다.","sense":"물 마시는 휴식"},{"wordId":22232,"answer":"weekend warrior","form":"원형","example":"My dad became a weekend warrior after buying a new mountain bike.","exampleTranslation":"아빠는 새 산악자전거를 산 뒤 주말에만 열심히 운동하는 사람이 되셨다.","sense":"주말 운동가"},{"wordId":22233,"answer":"pickleball","form":"원형","example":"My grandparents play pickleball at the community center three times a week.","exampleTranslation":"조부모님은 일주일에 세 번 주민 센터에서 피클볼을 치신다.","sense":"피클볼"},{"wordId":22234,"answer":"co-ed","form":"원형","example":"My college had a co-ed soccer league that anyone could join.","exampleTranslation":"우리 대학에는 누구나 참가할 수 있는 남녀 혼성 축구 리그가 있었다.","sense":"남녀 혼성의"},{"wordId":22235,"answer":"rematches","form":"복수형","example":"After losing, my little brother demanded rematches all evening.","exampleTranslation":"진 뒤에 남동생은 저녁 내내 재경기를 하자고 졸랐다.","sense":"재경기"},{"wordId":22236,"answer":"sign-up form","form":"원형","example":"Please return the sign-up form to the front desk by Friday.","exampleTranslation":"금요일까지 가입 신청서를 안내 데스크에 제출해 주세요.","sense":"가입 신청서"},{"wordId":22237,"answer":"trial session","form":"원형","example":"I enjoyed the trial session so much that I signed up for a year.","exampleTranslation":"체험 수업이 너무 즐거워서 나는 일 년 회원으로 등록했다.","sense":"체험 수업"},{"wordId":22238,"answer":"club president","form":"원형","example":"Our club president booked the hall for the spring tournament.","exampleTranslation":"우리 동호회 회장이 봄 대회를 위해 강당을 예약했다.","sense":"동호회 회장"},{"wordId":22239,"answer":"team jersey","form":"원형","example":"I accidentally washed my white team jersey with my red socks.","exampleTranslation":"나는 실수로 흰색 팀 유니폼을 빨간 양말과 함께 빨았다.","sense":"팀 유니폼"},{"wordId":22240,"answer":"pick teams","form":"원형","example":"The two captains took turns to pick teams for the dodgeball game.","exampleTranslation":"두 주장이 번갈아 가며 피구 경기 편을 갈랐다.","sense":"편을 가르다"},{"wordId":22241,"answer":"playing time","form":"원형","example":"The young striker got more playing time after the captain was injured.","exampleTranslation":"주장이 부상당한 뒤 그 젊은 공격수는 출전 시간이 늘었다.","sense":"출전 시간"},{"wordId":22242,"answer":"league game","form":"원형","example":"We lost our first league game, but we played much better than expected.","exampleTranslation":"우리는 첫 리그 경기에서 졌지만 예상보다 훨씬 잘했다.","sense":"리그 경기"},{"wordId":22243,"answer":"warm-up lap","form":"원형","example":"The runners jogged a slow warm-up lap before the race began.","exampleTranslation":"선수들은 경주가 시작되기 전에 준비 운동으로 천천히 한 바퀴를 돌았다.","sense":"준비 운동 바퀴"},{"wordId":22244,"answer":"club t-shirt","form":"원형","example":"I wear my club t-shirt every time we have a match.","exampleTranslation":"나는 경기가 있을 때마다 동호회 티셔츠를 입는다.","sense":"동호회 티셔츠"},{"wordId":22245,"answer":"hiking club","form":"원형","example":"My grandmother joined a hiking club after she retired from teaching.","exampleTranslation":"할머니는 교직에서 은퇴하신 뒤 등산 동호회에 가입하셨다.","sense":"등산 동호회"},{"wordId":22246,"answer":"more beginner-friendly","form":"비교급","example":"This new trail is more beginner-friendly than the steep one we hiked last year.","exampleTranslation":"이 새 등산로는 우리가 작년에 오른 가파른 길보다 초보자가 걷기에 더 좋다.","sense":"초보자용인"},{"wordId":22247,"answer":"post-game","form":"원형","example":"The coach gave a short post-game speech about teamwork.","exampleTranslation":"코치는 경기 후에 팀워크에 대해 짧게 연설했다.","sense":"경기 후의"},{"wordId":22248,"answer":"team photo","form":"원형","example":"Our team photo from the championship hangs on the wall at the gym.","exampleTranslation":"우승 대회 때 찍은 우리 단체 사진이 체육관 벽에 걸려 있다.","sense":"단체 사진"},{"wordId":22249,"answer":"practice schedule","form":"원형","example":"I printed the practice schedule and put it on our fridge.","exampleTranslation":"나는 연습 일정을 인쇄해서 냉장고에 붙였다.","sense":"연습 일정"},{"wordId":22250,"answer":"volunteer coach","form":"원형","example":"My mom has been a volunteer coach for the girls' basketball team for years.","exampleTranslation":"엄마는 몇 년째 여자 농구팀의 자원봉사 코치로 일하고 계신다.","sense":"자원봉사 코치"},{"wordId":22251,"answer":"on tap","form":"원형","example":"This little pub has twelve kinds of beer on tap.","exampleTranslation":"이 작은 술집에는 생맥주가 열두 종류 있다.","sense":"생맥주로"},{"wordId":22252,"answer":"bartenders","form":"복수형","example":"The bartenders at this hotel wear black vests and bow ties.","exampleTranslation":"이 호텔의 바텐더들은 검은 조끼와 나비넥타이를 착용한다.","sense":"바텐더"},{"wordId":22253,"answer":"draft beer","form":"원형","example":"After the long hike, a cold draft beer tasted amazing.","exampleTranslation":"긴 등산 후에 마신 시원한 생맥주는 정말 맛있었다.","sense":"생맥주"},{"wordId":22254,"answer":"craft beer","form":"원형","example":"My brother started brewing craft beer in his garage last year.","exampleTranslation":"형은 작년에 차고에서 수제 맥주를 만들기 시작했다.","sense":"수제 맥주"},{"wordId":22255,"answer":"house wine","form":"원형","example":"We ordered a bottle of the house wine to share with our pasta.","exampleTranslation":"우리는 파스타와 함께 나눠 마시려고 하우스 와인 한 병을 주문했다.","sense":"하우스 와인"},{"wordId":22256,"answer":"by the glass","form":"원형","example":"This restaurant sells champagne by the glass on New Year's Eve.","exampleTranslation":"이 식당은 새해 전날에 샴페인을 잔으로 판다.","sense":"잔으로"},{"wordId":22257,"answer":"cocktail menu","form":"원형","example":"The new cocktail menu has three drinks made with fresh peaches.","exampleTranslation":"새 칵테일 메뉴에는 신선한 복숭아로 만든 음료가 세 가지 있다.","sense":"칵테일 메뉴"},{"wordId":22258,"answer":"mocktails","form":"복수형","example":"The wedding served colorful mocktails for the children and the drivers.","exampleTranslation":"결혼식에서는 아이들과 운전할 사람들을 위해 알록달록한 무알코올 칵테일을 내놓았다.","sense":"무알코올 칵테일"},{"wordId":22259,"answer":"non-alcoholic","form":"원형","example":"The office party offered only non-alcoholic drinks this year.","exampleTranslation":"올해 회사 파티에서는 무알코올 음료만 나왔다.","sense":"무알코올의"},{"wordId":22260,"answer":"neat","form":"원형","example":"My grandfather always drinks his brandy neat after a big holiday meal.","exampleTranslation":"할아버지는 명절에 푸짐하게 식사한 뒤 항상 브랜디를 얼음 없이 그대로 드신다.","sense":"그대로"},{"wordId":22261,"answer":"last call","form":"원형","example":"We arrived just before last call and ordered two quick beers.","exampleTranslation":"우리는 마지막 주문 직전에 도착해서 맥주 두 잔을 급히 시켰다.","sense":"마지막 주문"},{"wordId":22262,"answer":"open a tab","form":"원형","example":"My friends wanted to open a tab, but the bar only took cash.","exampleTranslation":"친구들은 외상 장부를 열고 싶어 했지만 그 바는 현금만 받았다.","sense":"외상 장부 열다"},{"wordId":22264,"answer":"next round","form":"원형","example":"My cousin insisted on buying the next round for the whole table.","exampleTranslation":"사촌은 테이블 전체의 다음 잔을 자기가 사겠다고 고집했다.","sense":"다음 잔"},{"wordId":22265,"answer":"bottoms up","form":"원형","example":"The groom raised his glass, smiled at the guests, and said bottoms up.","exampleTranslation":"신랑은 잔을 들고 하객들에게 미소 지으며 원샷이라고 말했다.","sense":"원샷"},{"wordId":22267,"answer":"bar stool","form":"원형","example":"My little nephew climbed onto a bar stool in our kitchen.","exampleTranslation":"어린 조카가 우리 부엌의 바 의자 위로 기어 올라갔다.","sense":"바 의자"},{"wordId":22268,"answer":"coasters","form":"복수형","example":"My aunt bought us cork coasters as a housewarming gift.","exampleTranslation":"이모가 집들이 선물로 우리에게 코르크 컵 받침을 사 주셨다.","sense":"컵 받침"},{"wordId":22269,"answer":"pitchers","form":"복수형","example":"We ordered two pitchers of lemonade for the birthday party.","exampleTranslation":"우리는 생일 파티를 위해 레모네이드 피처 두 개를 주문했다.","sense":"피처"},{"wordId":22270,"answer":"bar snacks","form":"원형","example":"We filled up on bar snacks, so we skipped dinner.","exampleTranslation":"우리는 술안주로 배를 채워서 저녁을 건너뛰었다.","sense":"술안주"},{"wordId":22271,"answer":"cards","form":"3인칭 단수형","example":"This store usually cards every customer who buys beer, even grandparents.","exampleTranslation":"이 가게는 맥주를 사는 손님이면 조부모님이라도 보통 모두 신분증을 확인한다.","sense":"신분증 확인하다"},{"wordId":22272,"answer":"pubs","form":"복수형","example":"There are three Irish pubs on the same street downtown.","exampleTranslation":"시내의 같은 거리에 아일랜드식 펍이 세 곳 있다.","sense":"펍"},{"wordId":22273,"answer":"wine list","form":"원형","example":"The wine list at this restaurant is longer than the food menu.","exampleTranslation":"이 식당의 와인 리스트는 음식 메뉴보다 길다.","sense":"와인 리스트"},{"wordId":22274,"answer":"drier","form":"비교급","example":"I want something drier than this sweet wine for dinner tonight.","exampleTranslation":"오늘 저녁에는 이 단 와인보다 더 드라이한 것을 원해.","sense":"드라이한"},{"wordId":22275,"answer":"soju","form":"원형","example":"We shared a bottle of soju with grilled pork at the night market.","exampleTranslation":"우리는 야시장에서 구운 돼지고기와 함께 소주 한 병을 나눠 마셨다.","sense":"소주"},{"wordId":22276,"answer":"shot glass","form":"원형","example":"My little brother uses a shot glass to measure his cough medicine.","exampleTranslation":"남동생은 기침약 양을 재는 데 작은 술잔을 쓴다.","sense":"작은 술잔"},{"wordId":22277,"answer":"whiskeys","form":"복수형","example":"The tour guide let us try three different whiskeys at the distillery.","exampleTranslation":"투어 가이드는 증류소에서 서로 다른 위스키 세 종류를 맛보게 해 주었다.","sense":"위스키"},{"wordId":22278,"answer":"sipping","form":"-ing형","example":"My grandmother was sipping hot tea on the porch this morning.","exampleTranslation":"할머니는 오늘 아침 현관 앞에서 뜨거운 차를 홀짝이고 계셨다.","sense":"홀짝이다"},{"wordId":22279,"answer":"grab a drink","form":"원형","example":"We should grab a drink after the concert tonight.","exampleTranslation":"오늘 밤 공연 끝나고 한잔하자.","sense":"한잔하다"},{"wordId":22280,"answer":"not much of a drinker","form":"원형","example":"My husband is not much of a drinker, but he loves wine tastings.","exampleTranslation":"남편은 술을 별로 안 마시지만 와인 시음은 정말 좋아한다.","sense":"술 안 즐기는 사람"},{"wordId":22281,"answer":"company dinner","form":"원형","example":"I left the company dinner early because I had a headache.","exampleTranslation":"나는 머리가 아파서 회식에서 일찍 나왔다.","sense":"회식"},{"wordId":22282,"answer":"after-parties","form":"복수형","example":"This festival is famous for its late-night after-parties near the beach.","exampleTranslation":"이 축제는 해변 근처에서 열리는 늦은 밤 뒤풀이로 유명하다.","sense":"뒤풀이"},{"wordId":22283,"answer":"garnishes","form":"복수형","example":"The chef uses fresh herbs and edible flowers as garnishes.","exampleTranslation":"그 요리사는 신선한 허브와 식용 꽃을 고명으로 쓴다.","sense":"고명"},{"wordId":22284,"answer":"ice bucket","form":"원형","example":"We kept the juice boxes cold in an ice bucket at the picnic.","exampleTranslation":"우리는 소풍에서 주스 팩을 얼음 통에 넣어 시원하게 두었다.","sense":"얼음 통"},{"wordId":22285,"answer":"mixers","form":"복수형","example":"The host bought plenty of mixers like tonic, soda, and lime juice.","exampleTranslation":"주인은 토닉, 탄산수, 라임 주스처럼 술에 섞는 음료를 넉넉히 샀다.","sense":"섞는 음료"},{"wordId":22286,"answer":"ginger ale","form":"원형","example":"My mom always gave me ginger ale when I had an upset stomach.","exampleTranslation":"엄마는 내가 배탈이 나면 항상 진저에일을 주셨다.","sense":"진저에일"},{"wordId":22287,"answer":"sparkling water","form":"원형","example":"I drink sparkling water instead of soda to cut down on sugar.","exampleTranslation":"나는 설탕을 줄이려고 탄산음료 대신 탄산수를 마신다.","sense":"탄산수"},{"wordId":22288,"answer":"soft drink","form":"원형","example":"The movie theater sells a large popcorn and a soft drink for ten dollars.","exampleTranslation":"그 영화관은 큰 팝콘과 청량음료를 십 달러에 판다.","sense":"청량음료"},{"wordId":22289,"answer":"separate checks","form":"원형","example":"The waiter asked if we wanted separate checks or one bill.","exampleTranslation":"웨이터는 우리에게 따로 계산할지 한 번에 계산할지 물었다.","sense":"따로 계산"}]`);export{e as default};